/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090119-6","meetingId":"h21-cm01","date":"2009年1月19日","dateIso":"2009-01-19","committee":"区民委員会","time":"午前１０時１３分～午後０時０１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"１第２号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"１第２号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"若林委員","kind":"質問","question":"そこら辺の考え方について、どういうふうな支援ができるのかということをお聞きしたいということと、みずほ銀行の件がありました。じゃあ０.６％でお借りするのかということなのか、信用保証協会のほうで他行にご紹介等するのか、その２点をちょっとお聞きしたいと思います。","respondent":"金子産業振興課長","answer":"１点目、いわゆる借りかえの問題なんですけれども、この件に関しましては、今回の小規模のほうではなくて、２の経営支援資金ですね。","id":"exchange-001"},{"speaker":"若林委員","kind":"確認","question":"ご案内というのは、相談を受けたこちら側でもご案内してくださいということなのか、すみません、ちょっと確認です。","respondent":"金子産業振興課長","answer":"失礼いたしました。もしご相談等、委員の皆様方もありましたら、そのようにご説明いただければ幸いです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは求めていたことでもあるので非常に歓迎しているんですけれども、１０月末の時点ですけれども、全額補助というところも結構あるんですね。据置きというのもせいぜい１年ぐらいはやるべきなんじゃないかなと思うんですが、そちらの考え方もあわせてお伺いします。","respondent":"金子産業振興課長","answer":"品川区としましては、３分の１は自己負担していただくというところで今回の対応ということに関しては問題がない。さまざまな考え方がありますが、私どもとしては、これで今回については対応は十分であろうというふうに考えているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"今回いろいろな業種の方に話を聞いてみますと、やっぱり業種とか規模とか、あらわれ方が厳しいのは確かです。どういうところに手を伸ばそうとか、補助を３分の２にして、どういうことをやったのかなというのをちょっとそこもお伺いしたい。","respondent":"金子産業振興課長","answer":"今回の３年間無利子であるということ、また信用保証料については、非常に今回の緊急対応については歓迎をされているところです。そのように意見をいただいておりますので、今のところはこういうふうな制度で実施していきたいと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"まず制度設計の段階からいろいろお話を伺って、つくって、そういった点ではいかがでしょうか。いかがか尋ねました。","respondent":"金子産業振興課長","answer":"それから、従来から昨年は２回融資をしまして、その際にもいろいろ申し出られた意見については今まで伺ってまいりました。その辺について評価をいただいているということですので、その辺についてはご理解をいただければと思います。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"１点だけお伺いしたいんですが、区の融資制度の中で、融資あっ旋状というのを発行、ご相談に来てあっ旋状が出せる企業で区のあっ旋をもらいました。","respondent":"金子産業振興課長","answer":"それから、不実行になった場合の問題ですけれども、私どもは融資あっ旋だけをやっているわけじゃなくて、金融に関して全般の相談をやっております。","id":"exchange-006"},{"speaker":"稲川委員","kind":"質問・要望","question":"スピーディーな対応を求められると思うんですが、１名分だけで対応することができるのかどうなのかというのをまず、迅速に並ぶことのない。まあ、その辺を説明を求めました。","respondent":"金子産業振興課長","answer":"いわゆる当面１名対応で足りるかなというふうに考えておりますが、また別途増やして対応していこうかなと思ってあります。金融機関につきましても、同じく迅速な対応をしていただけるよう今回改めて議決を踏まえて協定を結ぶということが新しい資金の種目を設置するので。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"提案","question":"そこのところの考え方というか、そこのところの対応の変化を求めるものというのが、ちょっと今回の提案の中では、どういうふうになるのかな。","respondent":"金子産業振興課長","answer":"向こうの対応の話し方からすると、対応はしたいんだけれども、システム上対応し切れないというふうに伺っていますので。実は昨年二つの緊急資金を実施しておりましたが、７月のころは私どもの緊急資金を実施するについては、信用保証協会が８０％負担するものなんですね。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問","question":"信用保証が１００％ということで、何かもうちょっとこういう対応だとか、考えられるものはないのかどうなのか。本当に今お金が必要なところにお金が回ったのか、ちょっと漠然とした質問になるかもしれないんですけど、どうか尋ねました。","respondent":"金子産業振興課長","answer":"相談は国の、いわゆる原材料価格高騰対応等がスタートした１０月３１日からの累計になりますが、１月１６日までで３,４１５件になります。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"新たに仕事をつくってもらったというところが一つの励ましというんですか、１月１６日の朝日新聞に、品川区は。奨学金というのはこちらの所管じゃなかったかと思うんですが、あるいは今の従来の奨学金の制度を拡充するとか、そういったお考えというのはないのか。","respondent":"本間委員長、宮地区民生活事業部長","answer":"理事者のほうで答えられる部分とあれなんですが、ちょっと答える方、どなたが答えるのか。 ただいまの安藤委員のお話は、この間たまたま新聞で就業資金、学業資金の貸付制度というのは確かにございました。改めてそういう機会がありますときに、またお答え申し上げさせていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"そういった、この辺から結果として中小企業の苦境というのを支えるというお考えはないのかなという質問だったんですけれども、うまく言えない。仕事の総数という点ではどうなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"本間委員長","kind":"質問","question":"よろしいですか。よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"２第１号議案、平成２０年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"２第１号議案、平成２０年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"本多委員","kind":"質問","question":"ただ、前倒しをしてさらに上乗せというか、次年度も従来通りやっていくというか、その方針みたいなものをちょっと伺いたいんですけど。それぞれは結構ですが、総括的なところでいいと思うんですけど、方針といいますか、その辺、教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"１７ページの大ホールの照明設備とかというのは、実際区内の小さい企業にまわるのかどうか、そこら辺は担保されているものなんか尋ねました。","respondent":"小野区民課長","answer":"全体の照明システムというか、そういう形で特殊な部分もあります。機具のそういう専門性というところから、できるだけそういう区内の事業者に行くような形で工夫しながら発注をしていくというふうに考えてあります。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"今防災フェアをやっていまして、そこで室内の火災報知機のコーナーにちょっと行ってお話を伺ったんですが、実際受注したのが新宿区の。どういった具体的にできるだけというのは考えて仕組みがあるのか、どういうふうにやっていくのか、もう少しお伺いしたいんですけど。","respondent":"小野区民課長","answer":"そういうものがある場合には、区内の事業者から調達するということを契約の中で確認する、こういうことです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ、じゃあ、よろしくお願いいたします。今緊急にやっぱり仕事がないというところで困っていらっしゃるわけですから、企業が多いわけですから、そういったアイデアはないのかなというのを。","respondent":"金子産業振興課長、久保田環境清掃事業部長","answer":"その中で、できる限り区内企業者を優遇させていくという方向で区としては過去もやってまいりましたし、これ以降もやっていくというふうな考えです。今年度の新しい事業で環境ビジネスの支援事業というものもスタートしまして… そういう情報を私どもも入手しまして、より環境対策のために生かせるものがあれば、そういう形での盛り上げ方なり何なりは研究していきたいというふうには考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"やっぱり所管の課としてこういう緊急経済総合対策なわけですから、これまでの制度の充実ということで広く考えていく必要があると思うんです。そういう悪循環になっていくと思うので、この補正予算にすぐ入れるかどうかというのはあると思うんですけど、今後の考え方としていかがか尋ねました。","respondent":"小野区民課長","answer":"そういう点では非常に関心があって、経済的な理由によって進学が阻まれないようにということで十分ご活用いただいているというふうに考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"ぜひ従来の制度の申し込みが多いということなんで、しかも中小企業の方も多いということなんで、さらに例えば大学生まで拡充するとか、あるいはそこまで行かなくても利子を区として補充するというようなこと、そういったことも視野に入れながらぜひご支援願いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"６月からの３カ月間と１１月からの３カ月間で、今回どういうふうに、そういった観点。これからどういうふうに周知期間を含めた拡大、いわゆる商店街の振興ということで生活支援という消費関係ですかね、そこら辺の角度もふまえた。","respondent":"金子産業振興課長","answer":"参加店についてはこれからまた区商連等と詰めていこうと考えていますので、前回の課題については解決しながら実施していこうと考えています。実施の前には区民委員会でご報告を申し上げていきたいと考えていますので、よろしくお願いしたいと思います。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"要するに、八潮のパトリア、あそこはたしか区商連扱いで、個店の集まりなんですかね。というところで伺いました。","respondent":"金子産業振興課長","answer":"基本的には商店街の関連しているところ、あるいはその周辺の商店で現在取り扱っているお店というのが対象になります。それ以外の部分については私どもで調査をしていきたいと、確認したいと考えていますので、よろしくお願いいたします。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"確認","question":"１点だけ確認したいんですが、買い替えなきゃいけないのと、修理すればいいのといろいろあるかと思うんですよね。そこら辺の考え方というのをどういうふうに、そこら辺の考え方というのはどういうふうにしているのか、お聞かせほしいと求めました。","respondent":"金子産業振興課長","answer":"これについては修理で対応しておりますけども、老朽備品としてすべてを買い替えるというふうな格好にしております。ですので、お尋ねのお答えとしては、常日ごろ修理等々については対応しております。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問","question":"中小企業センターのところなんですけども、これはちょっと部長のほうになるかと思うんですけど、要するに今回は中小企業センターですけども、基本的に区の考え方としては今の質問、同じ質問の場合、どういうふうに、基準というか、それがあるのかないのか。","respondent":"宮地区民生活事業部長","answer":"平成２１年度予算で組んでいるものの中から、あるいは孫請け等まで含めて、できる限り区内で生産しているものを中心に選んできているはずです。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"じゃあ新年度予算のときにその分はどうなるのというのが出てくるんですけども、今出ているものと新年度予算のときにまた何か探してくるんですか。そういうのがあるかと思うんですけど、そこら辺のところはどういうふうな考え方なんか尋ねました。","respondent":"宮地区民生活事業部長","answer":"すぐに対応できるというスピーディーな対応というのを区長も大変気にしておりまして、それでも１９日に開いてちょっとでも早くという考え方ですので。","id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"意見","question":"じゃあ来年度の予算のときは、じゃあ来年度、仕事確保という点ではちょっとまだ不十分なのかなというふうに思うんですよね。全体の仕事をつくっていくんだという立場が必要なんじゃないかなというふうに思うんですけども、実際その部分はとの意見を述べました。","respondent":"宮地区民生活事業部長","answer":"仕事を創出するというのも大きなテーマですので、そもそも平成２１年度もかなり上乗せした予算を組んでおります。それでなおかつ前倒しができれということですので、常に仕事はつくっていくというのは変わらない姿勢ですので、ご理解をいただければと思います。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/911630?Template=document&Id=2538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":29954,"voices":76}},{"id":"h21-20090119-7","meetingId":"h21-cm01","date":"2009年1月19日","dateIso":"2009-01-19","committee":"厚生委員会","time":"午前１０時１３分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"第１号議案 平成２０年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１号議案 平成２０年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"社会福祉会ですか、その辺の現状をどうとらえていらっしゃるのか、基本的なところ。どうか、品川区ではどうなっているのかというあたりを、お伺いしたいと思います。","respondent":"志村生活福祉課長","answer":"今まとめて対応しているところでございまして、２か月に一遍程度、大崎等のほうに巡回相談にきているとは聞いております。実績のほうは、あまり数は上がってございませんけれども、相談、紹介等はあります。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"提案","question":"数が若干増えているというような状況も伺ったので、まず提案したいと思うんですが、この点が一つです。保育園の繁忙期対応臨時職員経費で、もうちょっと中味も、人数的なこともあわせてお伺いさせてほしいと求めました。","respondent":"志村生活福祉課長、山田副区長、小林保育課長","answer":"５回出動していただいて、福祉会の方が２人で１チームを組みまして、相談に努めているところであります。ですから… ご提案とご説明をしていますので、いわゆる全体像ということになれば、その中の仕切りということでご理解いただきたいと思います。今回の補正でご説明させていただきました、３月１カ月間、２０人任用することを前提としてお願いしております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日特に強調したのは、障害者の雇用のところを、前からぜひ増やしていただきたいと。よその対策を見ても、事務の…。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点、一番お伺いしたのは、１００万円をどういうふうに使ってもらって雇用につなげるのかというところを、もうちょっと伺いたい。これをどう使って、どう雇用を増やしていくか、その辺の中味ももうちょっとお伺いしたいと思います。","respondent":"小林保育課長、高橋障害者福祉課長、冨岡高齢福祉課長","answer":"臨時職員を任用するということで、今回の３月につきましても、実態に合わせた任用を行っていきたいと考えています。その総量としては… それも就労支援センターから紹介し、実態としては、最後は就労支援センターで次の雇用先を考えていくというような状況です。したがいまして、知的… あわせて、助成を受けた運営事業者の運営する事業所に、引き続き６カ月以上雇用されることというようなことで考えているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういったことで、やはり継続性ということをすごく求められているので、ちょっとその辺をどういうふうに考えていらっしゃるのかというところ。１００万円の使い方なんですけれども、これからつくっていくのかどうか、ちょっとその辺を伺わせてください。","respondent":"冨岡高齢福祉課長","answer":"１００万円につきましては、私どもにありますので、あくまでもセットでお願いをしたいと考えています。それから、要綱等につきましては、今とにかく準備をして、これから詳細につきまして固めていくところです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事業所において雇用が継続される、今の不況がすぐに終わるわけではないので、ぜひ継続して長く続く方向に持って行っていただきたいなと思います。現状がどうなっていて、１５万４,０００円がつくとどういうふうになるのか、ちょっと具体的に説明を求めました。","respondent":"高橋障害者福祉課長","answer":"ヘルパー２級以上の資格で、ヘレンケラー協会を４日受講し、社会福祉協議会のガイドヘルパーのところに登録できるということが条件になっております。現行では５名分ということで、プラス７名分で、今年度につきましては１２人養成をするという内容になっております。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"２点、介護事業所の雇用促進について、伺いたいと思います。この１００人という数字を想定した経緯とか、ちょっと伺っておきたいなと思いましたので、お願いします。","respondent":"冨岡高齢福祉課長","answer":"特に訪問介護事業所につきましては４４カ所ありますが、１０人未満の事業者が３３ということで７５％を占めているといった状況を把握しています。なぜ１００名かですが、全体事業所が１０５カ所ということで、おおむね１００名と決めさせていただきました。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"意見","question":"どうしてもハードルになっているのが、非常に今回の緊急のみならず、今後もすごく注目度が高い。そういったことに行政がサービスする必要性があるかと思いますので、ぜひ継続性のところも、今後お願いできればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問・要望","question":"値段は少し高いらしいんですけれども、その分、２０年はもつからもとが取れるんだというお話も伺いました。そういった視点をお持ちであるかどうかということと、どうされていくかということを、教えてほしいと求めました。","respondent":"小林保育課長、高橋障害者福祉課長","answer":"もしくは、子育ての地域力を増していくという取り組みの一助となればということで、来年度以降も継続してまいりたいと思います。引き続きが必要なのかどうかの検討はしますが、今年度限りの対応ということで、現段階では考えております。来年度、心身障害者福祉会館で、かもめ第３工房等でインテリアをやった方のアドバイスを受けながら改修の内容を考えているということがあります。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"最後に１点、これは要望なんですけれども、先ほども、ちょっと障害者雇用の話が出ました。これは、ちょっとここからは外れました要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の補正予算の中で、話を伺った限り、また、今回の質問の中でも出ておりますけれども、継続して費用が出るものが多分ないのではないかなと。１年ぐらい前倒しをして購入するものだと思っているんですけれども、継続して費用が発生するものがないのかという確認を、まずしたいと思います。","respondent":"山岡健康課長、冨岡高齢福祉課長","answer":"先ほどの説明で申し上げたとおり、これは当面、今年度限りと考えております。それ以外はすべて前倒しで、工事、あるいは物品購入を考えているものですので、後年度まで引き続きというのは入っておりません。 福祉高齢事業部関係につきましても、平成２１年度を見込んだ部分の工事と、それから事業としては、２年間にまたがります訪問介護員の雇用等の部分ということで、これについては、あくまでも今年度分、５０人分についての計上です。","id":"exchange-011"},{"speaker":"浅野委員","kind":"確認","question":"確認したかったことと、１人１０万円、本人に渡されるものかなと思うんです。取ると支援があるとも聞いているんですけれども、期間と費用について、概略を教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"いろいろそれぞれの都合でお受けになるわけですけれども、大体３カ月ぐらいが平均かなと理解をしております。それから、費用ですけれども、９万円前後が多いと伺っております。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"１人増えるということで、事業所自体の経営の状況ですね、そちらのほうも大きくかかわってくると思うんです。こちらのほうについての見通しというんでしょうか、そこら辺のお考えはあるのかどうか、お伺いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"それに対しましての対応ですので、その辺の確保は大丈夫だと考えております。その趣旨を十分にご説明申し上げて、継続的、６カ月はやはり最低条件だというふうな考えで取り組んでまいりたいと思っているところです。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ここの予算で１２人にするということ、先に前に持ってきたのかという点が、ちょっとわからない。４月は４月でまた増やすんでしょうかという点、３点、先にお答えをお願いします。","respondent":"高橋障害者福祉課長、小林保育課長","answer":"ガイドヘルパーの養成ですが、平成１８年度から５名ずつ養成をし、平成２１年度も５名養成を考えております。ある程度のレベルを維持できる方の養成を考えておりますので、幅広く、今後も養成を続けさせていただきたいと考えております。 年度当初の臨時職員の任用につきましては、平成２１年度の予算の議決を経て、できれば来年度も継続して任用してまいりたいと考えています。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"逆に言うと、さっきからいろいろ出ているということ、やっぱり継続性を持った数字を上げてほしいというこれからの希望もあります。これも緊急で５０人分前倒ししたんだなと、１００人予定が５０人前に来たのかなという感じがするんですけれども、もう１回説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"こちらの期間も３カ月程度と考えておりますので、事業所と一体になって仕事のほうを進めていただければ、新しい提案です。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大変すばらしい制度ができたなという気がします。質問の中で、１００万円の使い道をどうするんですかというお話がありましたけれども、その辺はいかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"生活のほうの支援はできますけれども、３級の方以外はできないということになっていますので、お願いをしている。基本的には、職場研修等の部分で考えていきたいと考えています。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいのは、お尋ねしたいのは、お尋ねしたいのは。私が思うには、それはもう既に勤めているんですから、新たな雇用対策にはつながらないんじゃないかと。","respondent":"冨岡高齢福祉課長","answer":"新たな雇用ということで考えておりますので、雇用の開始とか、やはり事業所が交付申請をしていただいたより後と考えております。新しい人材の確保というところで考えているところです。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問・要望","question":"そうすると、新たなということですから、場合によっては、まだこの３事業所に勤めていない、だけれども希望はあると。人材の確保はできますというんですか、ぜひ検討を加えていっていただきたいなと思いますが、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"事業所の方には説明をする、ぜひ継続して雇用していただくように、ハローワーク等にもお願いをしたいと考えています。同じような趣旨で、ぜひ、ご協力をお願いしたいと考えているところです。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"お伺いしたいんですが、１００人を超えて希望が出されたときには、どういうふうにしていくのかというところ。その４点について、まず説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"１００名までいくかどうかという部分もありますけれども、１カ所で何人というのは、ちょっと難しいかなと考えております。１００万円ですけれども、それなりの受講する期間の部分プラスアルファという考えで、大体１００万円ということにさせていただきました。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平成２０年度に５０名に満たない場合は、平成２１年度で、一つ確認をさせてほしいと求めました。これをさらに今後もずっと継続していただきたい、そういう制度としてつくっていただきたいという強いご要望が、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"１００万円については、民民契約とか、そういう感じの仕事はできないんじゃないか。いわゆる継続ですが、今回については、ご資格を持っていらっしゃらなくてお勤めになりたいという方を対象に緊急的に対応するという趣旨です。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"各事業所からの強い要望でしたので、区としてつくっていただきたいということで、ぜひご検討いただきたい。品川区での講座で資格を取れる仕組みをつくってほしいという強い希望が出されておりましたので、ぜひ、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"国のほうの大きい方針が、今後どういう方向に行くのかということを、まず見極める必要があるだろうと考えています。２級のヘルパー講習の部分についてのご質問がありましたけれども、今回と来年度の分で１００人で、継続はいたしません。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"４.７％引き下げられたところまで戻らないという状況で、ぜひ現場からの要望を受けていただいて、ご検討ほしいと求めました。","respondent":"大沢委員長","answer":"本件についての質疑を終了いたします。採決に移る前に、態度ならびに意見の聴取を行いたいと思います。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としては、今回の緊急経済対策に対しては、十分に評価をしておりますし、先ほどのご説明にあった中での、介護事業所の雇用促進、緊急の雇用促進ということも十分に評価いたしますので、本件に賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"検討してほしいとか、あるいは公共事業の前倒しでありますとか、さまざまな視点で要請をしてまいりました。ただ、何点か要望させていただきました点につきましては、今後、十分にご検討いただければ幸いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"提案","question":"中でも、意見を述べさせていただきましたけれども、今後さらに充実をしていただきたい、拡大をしていただきたいということで、提案を３点。１点目は、職や住まいを失った方の総合相談窓口をつくっていただきたいということと、保育園をもっと増やしてほしいという点との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"阿部委員","kind":"意見","question":"前倒しした分が平成２１年度予算でそっくり穴があいてしまったのでは、今後とも継続的に景気対策を打っていく必要が、当面はあろうかと思います。その点、ご留意いただいた上で、ここは賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/854582?Template=document&Id=3224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":28793,"voices":63}},{"id":"h21-20090119-8","meetingId":"h21-cm01","date":"2009年1月19日","dateIso":"2009-01-19","committee":"建設委員会","time":"午前１０時１３分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"お聞きしている範囲で、平成２１年度の前倒しの部分なんかも含めてなんですけれども、まずお聞かせ願いたいと思います。","respondent":"松代管理工事課長","answer":"全体的な今回の取り組みの基本的な考え方としましては、冒頭述べたような対応で、各所管それぞれが事業の打ち出しをしています。先ほど説明しました土木管理費、または、さらに前倒しをして工事を発注することで経済対策につなげるといったことで抽出したものです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"これは金額的なものになりますけれども、まちづくり事業部として、総額でこれだけの補正の事業を抽出をするという考え方でこれが組まれたのか。この事業を前倒ししていけば、これらの事業が抽出をされてきているのか、ちょっとその辺をもう少し教えていただけますか。","respondent":"松代管理工事課長","answer":"今回の平成２０年度１月補正予算の事業規模は、約１５億円ぐらい予定をしているということで、全体的にまとまったものと聞いております。２カ年全体の事業規模は、約２８億円という見込みを立てていると、全庁的なものとして聞いております。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"１人は新たに雇用してやってくださいということで、お聞きしたところ、延べ何人ということですから。だから、極端な話をすれば、１人の方を雇用すれば３００日間の仕事という感じですかね。","respondent":"松代管理工事課長","answer":"委託をして、雇用に結びつける、そういった事業としての洗い出しをしております。実際の今後の事業等にきちんと反映でき、かつ、雇用創出に結びつくようなものとしての抽出をしてきたというところが実態です。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"ちょっとお聞きしたいんですが、ここに新たに今回の対策として組み込まれているのか、そのところの状況をお伺いしたい。３２ページで、今回の対策に伴って委託が新たに発生しているものなのか、ちょっと区別をお知らせください。","respondent":"松代管理工事課長","answer":"３月議会にかけるものを１月臨時会でかけて、前倒しで対応し、それを少しボリュームを増やしたというものが一つです。することによって、再三申し上げております経済対策、雇用対策に結びつくような事業の打ち出しをしています。","id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"先ほどの４４ページの屋外広告物等実態調査委託等々と言われたんですけれども、やろうとしていたものだから、早くにやるのかどうか。どういうふうに調査をかけていこうかとか、そういったところでは、どういうふうに考えているのかとの意見を述べました。","respondent":"松代管理工事課長","answer":"平成２１年度継続して行う事業の一環ですし、平成２１年度に予定をすべく、今回の第１回定例会で計上する予定でありました調査を前倒しでやる。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"清掃というと、今まであったんだけれども、２００万円の増額で、もっと回数を増やしていただきましょうとか、そういう個別のことになるのか。その考え方をお示しほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"先ほどの債務負担行為の部分ですけれども、これはすべて、当初は来年度の予算で実施をする事業と位置づけていたものです。３月までで完結する事業でございまして、区長の考えで、全く新たにプラスアルファで入れている事業もあります。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"省エネ型街路灯建替の８０基ぐらいですか、将来的に早くそれを立てることによってＣＯ２の削減にもつながるし、財政的な効果があるわけです。は、各事業部のバランスになってしまったのか、その辺はどうなんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"今年度、来年度でどんと投資しますと、１０年なら１０年後の取り替え時期にまた同じ額がどんとでてきます。待ったなしのＣＯ２対策、しばらく数を多くしてやっていきましょうと、長期計画の中ではこういう考え方になっております。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"あるいは雇用される方が品川区民という形態になるのか、その辺の考え方というか、担保の仕方はどうなのか。品川区の経済対策ですから、その点の担保の仕方というのは、どういうふうになっているのか。","respondent":"松代管理工事課長","answer":"一応、契約に当たっての仕様書の中に、そういったことを盛り込んでいくことを検討しています。委員がおっしゃったような、契約部門とも十分に協議を重ねて、そういった契約の発注の仕方も検討してまいりたいと考えております。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、委託する業者への仕様書の中でということなんですけれども、その辺、ある程度、徹底した流れをつくっていただきたいなと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、２カ月と１０日ぐらいになるのかな、喜んでもらえるように取り組んでほしいと求めました。ですから、品川区が考えざるを得ないと思いますけれども、そこらあたりの取り組みをきちっとしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点だけお伺いしたいんですけれども、ペンキがはがれていたりとかいうのが、歩いていて見えたりするんです。撤去するのか、それともペンキの塗り替え等も含む意味での工事の金額なのか、ちょっとその辺を教えていただきたい。","respondent":"藤田道路公園課長","answer":"ちょっと一番最初の説明の中で、３５ページの中には、公園灯の建替は含まれておりません。ゼロ債務負担行為で行うものですから、後の債務負担行為のほうで見ていただくようになりますので、よろしくお願いいたします。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":12492,"voices":36}},{"id":"h21-20090119-9","meetingId":"h21-cm01","date":"2009年1月19日","dateIso":"2009-01-19","committee":"文教委員会","time":"午前１０時１４分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"第１号議案、平成２０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１号議案、平成２０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"１００万円の寄附金があって、そこの視点での提案だと思っていたんですが、違うんですかね。ちょっとそこをお聞きしますとの意見を述べました。","respondent":"市川教育次長","answer":"基本的に平成２１年度予算で予定していたもののいわゆる前倒ししているもの、先ほど庶務課長の説明でございましたが、１校当たり５０万円。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"夫婦２人のところから四、仕事の出し方の工夫なのか、そういうちょっとそこのところの思いを伺いたいなと思っています。こうした検討はなぜ行わないのか、あわせて教えていただけますか。","respondent":"市川教育次長","answer":"ただ、今回区として広く底辺に対応した緊急経済対策ということで、いわゆる面的な広がりとしては一定程度確保できるかなと思っています。２点目の給食費の関係ですけれども、これは経済対策として有効か有効でないか、その点を判断した上での結論です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"小中一貫校推進経費ということですから。なぜ今回これを補正に盛り込んだのか、スタートだから、それだけに補正に盛り込んだ理由を教えていただきたい。","respondent":"市川教育次長","answer":"少なくとも既定の路線であると私どもは承知をしているというか、認識をしていますので、決して区民の間に意見が分かれているというような受けとめ方はしてございません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"不十分だという意見もありますし、学校の改築、こういう予算ならあり得ると思いますよ。私はここはやっぱり一貫校の拡大推進につながるこれについては意見があるし、はいそうですかと認めるわけにはいかないなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"山元委員","kind":"確認","question":"ちょっともう一回、ごめんなさい、確認ですが、あくまでも区内の企業に発注なさるということですよね。","respondent":"田村庶務課長","answer":"私どもで把握しているのは、どうしても特殊な専門の機器の補修だとかというと区内にその業者がいないということになると、その納入した関連業者のほうでやるという例外を除いて区内と、規模からしても小規模ですから、区内というふうに考えてあります。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"それをということで、これは取り替えなかったら、壊れちゃって使えない状態なんですか。そうでもないか尋ねました。","respondent":"富田学務課長、市川教育次長","answer":"消毒管理等々を徹底しなさいということで、国のほうから手洗いマニュアル等々昨年出されたところです。今はこういう自動噴霧というのは使っていないわけですけれども、それを受けて、新たに設置をしていくものです。受注の広がりということを考えたときに、いわゆる規模の大きい工事よりも、学校関係の工事に焦点が当てられました。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"緊急経済対策ですから、すぐにお金が回っていかなきゃいけない状況なので、区としてはどういう形でお金を回していくのかなというところ。平成２１年度のこの部分がなくなってくるわけであって、平成２１年度のこれからの審議になりますけれども、考え方をちょっとお聞きしたいと思います。","respondent":"田村庶務課長","answer":"基本的な考え方は、３７ページのプールなんかですと、塗装する前に補修しなきゃならないですよね。先ほどお話ししたように、基本的な考え方はできるだけ規模のあまり大規模なのは無理ですけど、比較的小規模なものを追加で入れたいという考え方です。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"平成２１年度の予算の前倒しですから、平成２１年度前倒しになっていくんだったら、２１年度は新規に追加項目というのを出してもいいんじゃないかな。プラスアルファという形の考え方なので、もうちょっと経済が潤ってくるという形になるんではないかなと思いますが、いかがか尋ねました。","respondent":"田村庶務課長","answer":"３万円の工事もいっぱいありますので、区の方針じゃなく、地域の密着型の経済効果は見込めるのかなというふうに思っています。７０万円に限らず追加令達というのをやって処理していますので、来年度はまた平成２１年度の予算で審議がありますが、そのような考えです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々もそういうふうに要望してきたけれども、なぜ緊急なのか、我々も区民に説明をしなくちゃならない部分があるという思いね。逆に今言った令達予算５０万円増やしたよと、こういう部分のほうが、思いの中でこれが最大のメリットですというのを改めてもう一度説明を求めました。","respondent":"市川教育次長","answer":"平成２１年度では取り込めない、平成２１年度の枠の中でおさまらないので、平成２２年度以降に対応しようというような項目が幾つかございました。これもきちんと説明していきませんと、その点は十分これから配慮した上で説明に努めていきたい、このように考えてあります。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう意味では、我々も議会としてアナウンスをしっかりしていって、アナウンス効果というのもあるでしょうから、それをやっていきたいと思います。これは皆さんどういうふうにとらえるのかわからないけど、一つ伺いたいのは、我々が今までに最終補正というのを経験してきたわけですよね。","respondent":"市川教育次長","answer":"１点目の最終補正、本日教育費の関係で説明申し上げている、大半がいわゆる工事請負費です。３点目の流用の問題ですけれども、何らかの予算措置によって対応していた事業かと思いますが、そういうことでご理解いただければと思います。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どういうことを言いたいかというと、平成２０年度予算があって、しっかり皆さん執行されてきている。６月補正をやっていけと私らは言うかもしれないけれども、そこであまりに３月補正で不用ということが出てくれば、これは要望にいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"山内副委員長","kind":"質問・要望","question":"１点だけちょっと教えていただきたいんですが、この残りの１２校は何で配られなかったのかなというのが１点あるんですけれども、説明を求めました。","respondent":"田村庶務課長","answer":"小山小学校、今年の２月で竣工、第二延山小学校、平成１８年の１２月で竣工、八潮学園が仮設に移っています。八潮学園中学校ということで、その学校を除いた学校で４２校というのを追加で今回の補正予算に入れさせていただいたと、そういう内容です。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"中国四川の地震からも学校耐震化は強い要望が上がっていますし、今回のように一貫校が前提だということは認めることはできません。今回の補正予算については、賛成できないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4656#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":18079,"voices":50}},{"id":"h21-20090119-5","meetingId":"h21-cm01","date":"2009年1月19日","dateIso":"2009-01-19","committee":"総務委員会","time":"午後１時０２分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"提案","question":"しかしながら、個々のところで、提案も含めて質問させてほしいと求めました。個々の質問ということではなく、そこのところの区側の姿勢というんでしょうか、そういうところをまず伺っておきたいと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"年末にやっております緊急資金の対応を６、７月に前倒しをいたしまして、区としても中小企業に対する対策の強化ということで取り組んでまいりました。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"雇用促進が今求められているんですけれども、それは財政規模にすると２８億円のうちの３億円だということが、１割強ぐらいですよね。委託等々で雇用する部分と２種類に分かれているんですけれども、１割の予算化の中で、その辺については伺っておきたいと思います。","respondent":"日下部企画財政課長","answer":"これに対してどのような対応がとれるのかということなんですが、特に中小の事業所における受発注の支援ということで、その中で対応していきたい。私ども認識をしておりますが、応急的な対応ということにはなりますが、最大限努力をさせていただいたです。","id":"exchange-002"},{"speaker":"南委員","kind":"提案","question":"生活支援、法には盛り込まれていないところをもっとやるべきじゃないかと思うので、ちょっと改めて具体的に提案したいと思うんです。駅の広報のスタンド取替え３８台と説明されましたけれども、その辺についてはどうなのか、一つ伺っておきたいところですとの意見を述べました。","respondent":"日下部企画財政課長、福田企画部長","answer":"２５ページにまいりまして、繁忙期対応の臨時職員ということで、臨時的な雇用につながってまいります。財源更生ということも含めまして、しっかりと対応して、財源の確保には努力をしてまいりたいと考えております。 広報紙の全戸配布につきましてお答えしてまいりましたとおりですが、実効性、こうしたものを引き続き検討する中で。この考え方につきましては、引き続き堅持してまいりたいと考えております。","id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"そういう中で、一つちょっとお伺いしたいのは、物品購入は、買ったらもうそれでしばらく買わない可能性が大いにありますね。修理みたいなものは、しばらくないとは思いますけれども、それをちゃんと埋めていく何か方策を考えていかれるんでしょうねという意味も含めて。","respondent":"日下部企画財政課長","answer":"７億５,０００万円組みましたが、ちょうど平成２１年度の予算編成と並行作業で進めておりましたので、前倒しをする。よく全治３年というようなことも言われておりますし、今後の検討課題ということで考えていく必要があるのかなと、このようにまずは考えてあります。","id":"exchange-004"},{"speaker":"土井委員","kind":"質問・要望","question":"やはり今、大変なときですから、少し皆さんにピークをつくらなきゃいけないと。だけれども、後のほうもなだらかにいくように、ぜひよろしく検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"国が基本的にやるべきだと、２３区、僕は本筋だと思います。その辺をちょっと、最初に説明を求めました。","respondent":"日下部企画財政課長","answer":"先ほどご説明申し上げたように、さらに債務負担も含めて、先ほど申し上げた１５億円。それから、ホームヘルパーの雇用促進のほうにつきましても、ご議決をいただければ、即、事業者に対する説明会を開催して実施をする。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"ちゃんときれいに波及効果を考えれば、いろいろな会社が取れれば一番いいわけですよね、基本的には。ある何社かに固まっちゃうと、実際、波及効果としてはさらに薄くなると思うんですが、その辺についての考えだけ説明を求めました。","respondent":"阿部経理課長","answer":"１社に偏るということではなくて、１社に固まるということではなくて、１社に固まるということはないと考えています。早速契約事務はやってまいりますので、即効性ということが出ていましたけれども、そういうことも踏まえながらやっていきたいと思います。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"意見だけで、できるだけ多くの区内業者から買って、また事業をしていただくということが、私はほんとうに優しい品川区につながると思いますので、ぜひ支援ということで、非常事態なので、その辺、経理課のほうとしても、少しでも考えていただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"林委員","kind":"意見","question":"緊急総合経済対策に対する考え方が出ているんならば、各部によって、経済対策を考えたものを知らせてほしいんです。その辺をまず、区の考え方として聞かせてくださいとの意見を述べました。","respondent":"日下部企画財政課長","answer":"具体的にこういう方針で取り組んでいきたいということで、そういう形で、今回の内容の取りまとめを行った。先ほど申し上げましたが、全庁を挙げて、各事業部の提案を特に重視しまして取りまとめさせていただいたというものです。","id":"exchange-009"},{"speaker":"林委員","kind":"提案","question":"３とある３番は、１番と２番を、こうだから提案をしてくれと。それで、提案が出てきた数字を、ここにはこういうものが必要だ、こういうものが必要だとやったのは経営者会議ですか、それとも企画か尋ねました。","respondent":"日下部企画財政課長","answer":"これは、最終的には１月補正予算の区長査定という形で、補正予算の提案を受けまして、それを段階を踏んで各事業部と調整をしながら、最終的には、区長判断でこの中味を取りまとめるという形をとらせていただきました。","id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"１００年に一度の危機が来たとか、言っていることは非常にすごいんだけれども、やっていることは単なる補正をつくったというだけですか。区民の暮らしだとか、そういうものを、１００年の危機から救おうという意気込みはどこにあるんか尋ねました。","respondent":"日下部企画財政課長","answer":"これをしっかりと実施、先ほどご説明させていただきましたように、前提としています。私どもとして考えておりますのは、このような形で緊急の総合経済対策を実施すると、この辺に大きな意義があるのではないかと考えております。","id":"exchange-011"},{"speaker":"林委員","kind":"質問","question":"この補正予算の大きさを見ろ、議会はと、そういう意味の議会なんですか。条例改正で、議会に付託じゃないんか尋ねました。","respondent":"福田企画部長","answer":"この予算の規模、それから多様性、総合性としたことを考えたのが一つ。品川区という法人全体の意志として区民にメッセージを送る、これが妥当なものではないかと考えたものが、一番大きな理由です。","id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"２０日以降になると、僕はそこまでわかっていないと思うんです、事業主は。この打ち出されてきた補正がどのぐらい区の事業主、あるいは区民の中に浸透していくのかというのか、考えられたんでしょうかね。","respondent":"日下部企画財政課長","answer":"広報「しながわ」２１日号で区民の皆さんに周知をしますけれども、かなりの反響が見込まれるのではないかと考えております。５、６月あたりというのが、かなり効果が期待できるのではないかと考えています。","id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"７億５,０００万円のうち、財政調整の基金を見てきたんですけれども、現金はそんなにないんですよね。とすると、国債なのか、積立なのか、崩していかなきゃいけないんですけれども、そういうことまでも考えていらっしゃるんか尋ねました。","respondent":"日下部企画財政課長","answer":"今、ちょっと私も手元に持ち合わせておりませんけれども、それはしっかりと、必要な取り崩しをして、財源として充てていく。その中の７億５,０００万円ということで、取り崩しをしまして活用していくというような考え方でおります。","id":"exchange-014"},{"speaker":"林委員","kind":"意見","question":"それから、決算特別委員会のときに、品川区は区債を２年間立てないで、先々のことを考えて、予算、決算をつくっているんだと。その辺の問題も絡めて、ちょっといわゆる基金を取り崩すということについて、説明してくれますかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"申し上げるまでもありませんけれども、７億５,０００万円ほどの今回の補正の財源には、まず足りないというのが一つです。実は、私どもいろいろな角度から検討しましたが、そういう結論に至ったです。","id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"平成２１年度の予算案が計上されてくる３月定例会のときに、もう一度補正が入ってくるんですか、こないんですか。毎年の３月予算と一緒に出されてきているんですけれども、効果を上げたいというか、そういうことについて聞かせておいてください。","respondent":"日下部企画財政課長","answer":"結論から申し上げますと、基本的に、最終補正予算も第１回定例会に上程をします。やはり年間を通してやっぱりさまざまな要因での検討もありますし、これを最終でしっかりと整理をするという予定です。","id":"exchange-016"},{"speaker":"金野委員","kind":"質問・要望","question":"内容もお聞かせいただいた中で、先ほど、ほかの委員からも出ておりましたけれども、確認も含めて質問させてほしいと求めました。平成２１年度予算を見越して前倒しでするんですけれども、もう一度、確認の意味でそこの考え方を教えてほしいと求めました。","respondent":"阿部経理課長、日下部企画財政課長","answer":"例えば外階段なんかですと、単に塗るだけではなくて、補修もしつつ塗装も行う場合があります。塗装単体の場合には、塗装業者を優先していくということは従来から行っておりますし、今後もそういうことで続けていきたいと思っています。プレミアム付の商品券につきましては、今、産業振興課のほうで、具体的な実施の内容につきまして、商店街連合会のほうと調整をしております。","id":"exchange-017"},{"speaker":"金野委員","kind":"質問","question":"１１月ごろだということでありますので、区民の皆様の生活により潤いをあたえていかれるような形で発注の時期を考えていくべきだろうなと思います。より効果を発揮するには、使えるところがよりわかりやすく、また使えるところの範囲を広げるというような考え方はいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"おっしゃるように、使える店舗は最大限広げていくということは、確かにそのとおりです。大変に努力をしていただいているということでもありますので、改めまして、その辺は商工会連合会のほうにもお願いをしてまいりたいと考えております。","id":"exchange-018"},{"speaker":"南委員","kind":"確認","question":"改めてちょっと確認したいんですけれども、この地域の小中一貫校建設については、この予算が初めてということで認識していいんでしょうか。そこだけ確認して、この補正予算には賛成をしていきたいということを、ちょっと表明しておきたいと思います。","respondent":"日下部企画財政課長","answer":"具体的に申し上げますと、平成２０年度当初予算におきまして、品川地区一貫校につきましては、まず、実施設計の経費です。平成２１年度着工を前提とした実施設計の経費です。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1808#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":29847,"voices":50}},{"id":"h21-20090120-6","meetingId":"h21-cm01","date":"2009年1月20日","dateIso":"2009-01-20","committee":"区民委員会","time":"午後１時０３分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"１の大崎第二地域センターの移転","agenda":"１の大崎第二地域センターの移転","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"幾つか教えてください。その辺の公有財産としての位置づけというものを教えていただきたいのと、それとこの建物の地上１階、わかれば教えてほしいと求めました。","respondent":"中山地域活動課長","answer":"１・２階の部分ですけれども、１階は倉庫及び会議ができるスペースができる予定です。２階につきましては生活支援施設という位置づけになっておりまして、いわゆる子育ての支援施設を基本に現在検討が進められていると伺っております。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"要望だけをちょっとさせていただきたいと思うんですけれども、できれば現行の地域センターの３階を地域の活動拠点に使えないかという要望が。別の部署になってしまうかもしれませんので、要望という形でとどめさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域に貢献できるような施設をつくってほしいという要望が数々出されるんですけれども、何か工夫といいますか、配慮というのは考えがあったのかどうかというのをお伺いします。","respondent":"中山地域活動課長","answer":"新しいこの施設については、いわゆる洋室の仕様というか、通常の集会室の仕様で面積を広げて対応していくということを基本に考えているところです。全体としては駅からの利便性は上がってくるとは考えておりますけれども、区でできること、対応を考えているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"できるかどうかというか、ぜひお願いしたいんですが、いかがですかということです。もし言えるのであれば言っていただきたいのと、区の財産としての地域センターはどうなってしまうのかというのを、ぜひお伺いしたいと思います。","respondent":"中山地域活動課長","answer":"仮定でのお話というのはお答えが難しいかなと考えていますが、区分所有での役割、区としても配慮していくというふうに認識しております。ご要望のようなそういう利用団体とのお話、丁寧な形での説明等については、十分行っていきたいと考えております。","id":"exchange-004"},{"speaker":"若林委員","kind":"質問・要望","question":"それから駐輪、駐車はどういう対策を立てられているのか。そういった近隣からの苦情も含めて、使う人が使いやすいようにという意味で、どういう対策をとられているかお聞かせほしいと求めました。","respondent":"中山地域活動課長","answer":"１階から下の部分、貫通しているのはこのエレベーター２という形で、中で上下するものとで分けているものです。２点目の駐輪対策ですけれども、ちょっと今、建物の中にしかるべき利用者の想定をした必要な駐輪場のスペースは確保していく予定ですので。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。付置義務というんでしょうかね、いずれにしても余裕のある、ゆとりのあるものにしていただければと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問","question":"１階、２階部分のところでお伺いしたいんですけれども、ここはもうどこが使うとかということは決まってはいないんですか。どういう形でつくるのかというのが、お願いしたいんですが、この西口中地区の再開発全体でつくるようになるんか尋ねました。","respondent":"中山地域活動課長","answer":"これは新年度の予算にかかわることになってしまうわけですけれども、今、月額で６０万円ぐらいをベースに折衝しているという状況です。この辺についてはきちんと予算の中でお示したいと考えています。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"さっきエレベーターの件で質問があったんですけれども、要するに２階部分、会議室というのが集会室ですよね。そうすると、１階、２階との関係でいくと、エレベーターとどういうふうに使うようになるんか尋ねました。","respondent":"中山地域活動課長","answer":"これは先ほどもお答えしたとおり、この貢献施設の地下２階、１階の部分から上がってくるためのエレベーターという形です。階段およびこのエレベーター２を使って、上部の区民集会所等への施設内での上下の移動、こういう区分けになっているものです。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"意見","question":"１点なんですけれども、３室というと現在と同じということなんですけれども、どんな検討がされたのかと思うんですけれども。現在のままでいこうということだったのかとの意見を述べました。","respondent":"中山地域活動課長","answer":"先ほど申し上げましたけれども、駅から近づくという部分で言えば、そういう点でも利用が上がる可能性はあると考えております。利用の中で面積に応じてパーテーションを使って分けることもできるような形をとりながら、柔軟な利用も可能な形でレイアウトを考えたです。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"意見","question":"私は大崎のほうまではあまり行かないんですけれども、ここら辺でも集会室を取るのはなかなか大変なんですよね。今までが３室ということだったので、これを動かすとこうなるんじゃないかなと改めて感じたので、ちょっと言わせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"６０万円ほどじゃないかということなんですが、これまで今までの場所にあったときというのは、そういう負担というのはあったんでしょうか。あそこは駅の高さと合わせて通路ができていまして、１階部分というところが実質上、２階になっているということなんか尋ねました。","respondent":"中山地域活動課長","answer":"道路の部分が、４層の低層部分の一番下がグランドレベルになりますので、ここに駐輪のスペースを設けるという形です。駅のほうから回り込んでくるのもその下の部分になりますので、そこに駐輪場を必要台数設けるという考えです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"それともこれまでは区で単独で管理していたから、逆に安くなるのかという、そこら辺の変化というのはどんな感じなんか尋ねました。","respondent":"中山地域活動課長","answer":"ただ単純な年間のそういう維持経費をはじきますと、従来よりも毎年の負担というのは上がろうかと思います。建物の構造上の質あるいはグレードの問題にもかかわるわけですが、単年度だけで高い、安いというのは言えるものではないと考えています。","id":"exchange-012"}]},{"id":"topic-02","title":"２の区民集会所ＩＴ対応のモデル実施","agenda":"２の区民集会所ＩＴ対応のモデル実施","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"地域センターでやったらパソコンにウィルスが入ったというのはよくあることですから、区民集会所側のセキュリティというのはどうなっているのか。１週間に１回、それを入力させてアクセスさせるとかが必要なんじゃないかなと思いますが、その辺を説明を求めました。","respondent":"中山地域活動課長","answer":"無線ＬＡＮカードを最大２０枚用意いたしまして、一斉にできることにも対応しようかと考えていますが、しょっちゅうあるものではない。パスワード変更については、やたら頻繁にパスワードを変えるとなると、今度説明の資料というんですか。","id":"exchange-013"},{"speaker":"稲川委員","kind":"意見","question":"だから、例えば車を外にとめて、営業時間内に外からでもアクセスができるのかなという部分がちょっと心配だったんですね。とにかくセキュリティはしっかりとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういう方々がどういう思いで求めているのかというのを、どういうものが届いているのかというのをお伺いしたいというのが１つと、大体どれぐらいの事業費を想定しているのかというのをお伺いしたい。","respondent":"中山地域活動課長","answer":"町会なんかも当初はなかなかホームページの扱いが難しいという認識だったんですが、２日で４０人弱の町会からもホームページ講習会の参加が出てきた。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"さっきのただ乗りという言葉、多分そういう意味だと思うんですけれども、これはただ乗りしちゃいけないんですかね。そういうのを含めた今後の全体的な計画性とかというのを教えていただきたいのと、極端に言うと２０台つないだ場合には、学校なんかでもありますよね。","respondent":"中山地域活動課長","answer":"これは最初のご質問にもお答え申し上げましたけれども、今のところ、有線については最大２本までを考えております。この辺もきちんと見極めながら、お声を聞きながら、実態を見て適正な運用に努めていきたいと考えています。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"最後にします。最初にお伺いすることなんでしょうが、このモデルを品川第一と荏原第四にしたという選定の意図を説明を求めました。","respondent":"中山地域活動課長","answer":"ある程度地区のバランスを考えましたが、従前からかなりパソコンを使っての利用の声が地域センターに寄せられていたというのが１つあります。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"１台ずつ設定していかなければならないですから、多分２０台設定するとなると、素人考えながら１時間やそこらで設定はし切れない。どのような形になるかというのは、本格実施のときにいろいろ変わってくるんだと思うんですが、どうお考えか尋ねました。","respondent":"中山地域活動課長","answer":"利用後の以前に、きちんとその辺の事前の説明も含めて、伝えていくところからスタートかなと考えています。地域側からまとめてというのは例外かなと考えていますので、利用時間の中でなるべくむだがないような工夫はしていきたいと考えています。","id":"exchange-018"}]},{"id":"topic-03","title":"３の地域食事サービス事業２０周年記念式典","agenda":"３の地域食事サービス事業２０周年記念式典","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１０年以上やっているということは、誘っていきたいわという周りの方々とかというのをお誘いしてというふうにはなかなかならないんでしょうか。そうすると、体験談を聞いて、私もやってみたいという人が出てくるのかなと思ったんですが、そこら辺はいかがか尋ねました。","respondent":"中山地域活動課長","answer":"お知らせして一般の方が参加できるものもありますので、今回はどちらかというと懇親を深めつつ労うという場面ですので、そういう呼びかけについては別の場でしっかりやっていきたいと考えております。","id":"exchange-019"}]},{"id":"topic-04","title":"４のしながわ環境大賞および環境講演会","agenda":"４のしながわ環境大賞および環境講演会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こういう感じで講演会を選定した考えといいますか、理由といいますか、お伺いしたいと思います。","respondent":"工藤環境課長","answer":"まず１点目の選考委員会のメンバーですけれども、こちらのほうは環境大賞の実施要綱の中で選考委員会の設置というのをうたってあります。この３０名の中から、日程等、都合がつく方からという部分が選考しているというものです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"産業構造というか、もっと一人ひとりの有権者がどういう社会をつくっていかないと抜本的にＣＯ２を減らすことはできないのかという方面からも。ですから、選考理由として講師派遣の方が２０名いらっしゃいますけれども、派遣講師の方がいるということで研究したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/911630?Template=document&Id=2540#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":26581,"voices":70}},{"id":"h21-20090120-7","meetingId":"h21-cm01","date":"2009年1月20日","dateIso":"2009-01-20","committee":"厚生委員会","time":"午後１時０２分～午後５時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"そういった、この間の異常なほどの高齢者の財政的な負担をどうとらえているのか、そこの認識のところを１点お伺いしたい。本人はもちろん、病院内でも困っているといった実態をどうとらえているのかというあたりを、まずお伺いしたいと思います。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"当時平成１２年、天引きに関する苦情というのは、私は記憶を一切しておりません。いろいろな角度から考えていきますと、そういう点も踏まえますと、このような枠組みの中でやっていくべきものだと考えているところです。ケアマネジメントが対応していくということで、杓子定規ということではなくて、できるだけ柔軟な対応をできるように心がけているところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺はどうなんでしょうか。基金のことをちょっとお伺いしたいと思いますが、その辺も教えてほしいのと、その辺もあわせて教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"今回も介護報酬の改定が見込まれておりますけれども、その改定と自然増の部分を加味しまして、まずサービスの給付額の見込みを３年分立てるわけです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"基金の状況、介護保険制度が始まってからの基金の推移を教えてほしかったんですが。","respondent":"冨岡高齢福祉課長","answer":"基金の推移につきましては、今、手元には持っておりませんが、基金の取り崩しにつきましては二期で１人当たり１００円、三期で２２５円、四期におきましては３５４円を取り崩して保険料に算定しているという流れです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"使われずに残って基金として積み立てられた額が、２０００年以来どういうふうに推移しているのかなというのと、現状を教えてほしかったんです。ここに２０億円余と書いてありますけれども、推移を含めて。","respondent":"冨岡高齢福祉課長","answer":"二期、開始時が１９億円です。三期が２０億円、今回は２３億円の見込みです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"二期も三期も四期も取り崩しているので、総額で保険料を出すときに、このぐらいだったらば削ってもいいという算定の基準とかはあるんですか。この辺の取り崩す額を算定するときの基準があるのかどうかということと、２３億円にまでなったというのはどうしてなのか、その辺を説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"大体９億円を取り崩しまして、総給付費の１割ぐらいを次期の分、予備として残しておくというふうに考えているところです。それで結果的に何億円になったということで、それは結果的にそちらの部分を使わない状況であったです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"三期のときも５億３,５００万円ですか、なおかつ３億円ぐらい、また積み増しになったわけですよね。私は、ここの１番目の請願項目の「基金を使って保険料基準額の値下げをしてください」というあたり、その辺はいかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"そのぐらいの基金を持っていませんと、急に制度が変わって給付が伸びたようなときなどに適切に対応できないだろうということが予測されます。そのぐらいの額を留保するということは、保険者として適当な数字だろうと考えております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"１,０００万円、１,５００万円、低所得者のところの保険料を安くしていくという対策をとっている区がかなりたくさんありました。工夫をすれば、もっと低所得者対策ができると思うんですが、その辺はいかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"低所得者に対する対応をすることで、残念ながら一番高いところを３００万円以上と設定させていただいて、あるいは最低でも同じ額という形の保険料の設定に工夫をした状況です。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"品川区はこれが精一杯ですか。私は本当にがっかりしたんですけれども、そのところはいかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"今、お手元の資料が確定版なのかどうか。条例は多分第１回定例会で決まる話ですので、品川区もあらゆる考えられることを考えた上で、私どもは精いっぱいであると申し上げたいと思います。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それから２番のところでちょっと確認なんですが、区としては市町村特別給付だということで、もう１回確認をさせてください。それもまた、その部分の中で、サービス対応は個々に行っているということでいいんですねということの確認を、もう１回お願いします。","respondent":"冨岡高齢福祉課長","answer":"今後の条例の改正に向けて対応してまいりたいと考えております。個々のケース、ケアマネジメントの中で、機械的でなく対応させていただいているです。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですからあとは全体の意見になってしまうので、これ以上は質問としてはやりませんけれども、あとでまた態度は出します。ただ、時間的にもこの後報告等がありますので、質問はこの辺で控えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"そうしますと、むしろこの先１５年とか２０年のスパンで、できるだけ負担可能な保険料の設定がされていくべきであろうかと思うんです。この基金というのは、そのころもこの基金の総額を維持しなければならないというお考えなのか、その辺の考え方をちょっと聞かせてください。","respondent":"冨岡高齢福祉課長","answer":"じゃあ幾らかというのは難しい内容ですが、基金の幅は当然圧縮されてくるだろうというところですが、給付の１割というのはある程度考えてまいりたい。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"私どもも昨年の第３回の定例会だったかと思いますが、それは幾ら何でも現状に合わないのではないかというような話をさせていただきました。そういう意味では、この請願項目については、ほぼ実現されるであろうと理解してよろしいか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"請願の中身については実現の見込みがあると申し上げたいと思います。ただ、その手当の仕方とかなんかでは違っているです。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"３点目なんですけれども、すべて足りるかどうかというのは、私もむしろ足りないであろうと考えています。高齢者向けの居住系の施設全体を、これからもつくっていく必要があると考えておりますが、区の今後の施設系の充実策を教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"例えば高齢者住宅についても、そういう部分を具体的にどう対応していくか、そのようなことも含めて今後は考えていく必要があろうかと考えています。","id":"exchange-013"},{"speaker":"阿部委員","kind":"意見","question":"品川区では、在宅をまずは中心とするということではありますけれども、様々な形での住居系のサービスがあってこそ、安心して在宅介護ができるという状況になっていると思いますので、ぜひ、今後ともそちらの充実を図ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"なるべく重複しないように質問したいなと思うんですけれども、請願の１項目目、基準額の算出方法のお話を伺いました。この前の決算特別委員会でも要望はしたところですけれども、ましてや介護についての費用はこれからもますます上がっていくし、対象となる方も多い。","respondent":"冨岡高齢福祉課長","answer":"ただ、一方で給付費を作為的に圧縮というのはできないわけでありますので、適切な認定と、それからサービスの提供ということがあります。給付費と、それから第１号被保険者からいただく私どもの保険料、一方的に下げればいいという中身ではございません。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう一つ、基金についてお伺いしたいんですけれども、これは関連するかどうか、先ほども部長の方から財政安定化基金の話があったと思います。毎年決算表を見ると差は出ているんですが、こちらの基本的な国の考え方というか、運用の仕方を簡単に教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"介護保険制度では、先ほど課長が申し上げましたように、総給付費の２０％は６５歳以上の方の保険料でまかないなさいということになっています。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"先ほど言われていた１０％程度ですか、これは想像に難くないところですので、この点もうまく運用してほしいと求めました。ここは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特養ホームの待機者５００人、増設をお願いしたいの項目なんですが、低所得者対策ということですかね。私はこの５００人を一体どういうふうにして老後の安心を勝ち取るのかということをぜひ聞かせていただきたいんですが、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"正確には今回は４９５だったと思いますけれども、見込みが立つという形で、今後そういう方が増えていくということで八潮についてもまた考えていく。５００という数字、今までも、ある程度在宅で頑張っていただいた方には入所の見込みが立っているというふうに理解をしています。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５００人がどうかというんだったら、２０万とか、そういうお金を払えない人は行き場がないんです。だから、こういう人たちの現在をどうするのか、願いがかなえられないということに対してどうなのかということを最後にお伺いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホームほか、ケアホームを含めた施設を用意させていただいておりまして、この中で対応しようということです。区としては考えておりますが、その辺のバランスという部分についても、保険者としては責任を持って考えていかざるを得ないテーマだと考えています。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"５億３,５００万円取り崩すところが、逆に４億５,０００万円ぐらい積み増ししたわけですから、そこのところを確認させてほしいと求めました。本当に負担能力に応じたということで、厚生労働省で求めているような配慮をぜひしていただきたいと思うんですけど、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"結果的に取り崩す予定が積みになったということにつきましては、報酬改定が見込まれますけれども、このご意向というのが入ってまいりますし。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１００％保険料だけでこの財政はまかなうというのが、私は何度も何度も窓口に行ったりご相談にお伺いしたときに、保険料に跳ね返ってくるんですよ。通えるところに息子さんがいるというだけで打ち切られるというのが実態ですから、他の区は実際に始めていますので、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"病院などへの付き添い、あるいは外出介護というのは、今まで法内でできない部分のサービスを横に出しているものです。先ほど申し上げたとおり、保険料の基準額に跳ね返しをせずに、何とか維持できるという内容で財政を組み立てているところです。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今はたまった基金があるから、本来は保険料を引き下げるということで使うべきものですから、私はそこのところはぜひ強力に求めておきたいと思います。１を超えているところが本当に多いですから、１以下というのは６しかありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都が、そういう１以下のところに１.５倍の補助金を出してぜひ誘導したいということでやっているこの時期にこそ、特養ホーム増設の計画を立てて、１以上に引き上げていただきたいと私は思うんですけれども、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"平成２２年、平成２３年で、これは八潮の分をきちんと載せさせていただいているということです。現時点で具体的な場所の手当てができておりませんので、その点については計画上明らかにすることができないということであります。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"よく見ていただきたいなと思うんですけれども、それなので、第４段階、品川区が３,９００円のところ、渋谷区は３,３００円です。そういうところは、一般財源でやるということしか考えなかったというのを渋谷区の担当課長からお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"３番につきましては、１番の部分、この骨子案の中に既に９億円の取り崩しを考えている。現状に特別の指定ができないということも考えると、今回の請願そのものについて、不採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問・要望","question":"長期基本計画の１０年というんでしょうか、そういう長いスパンの中で対応していくということでいいのではないかと思います。平成２０年、私どもの予算要望の中でもかねがね区長の方には介護という視点から、あるいは介護施設等も含めまして要望してきたことがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"値下げの努力をすべきであると私は思いますし、他区と比較すると、三期のときよりも四期の品川区の内容は努力が足りません。こういった実態であると思いますので、ぜひ改善をしていくといった立場で採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"阿部委員","kind":"質問・要望","question":"サービスは充実した方がいいですし、お金が天から降ってくるのであれば、本当に幾らでもやってほしいことはたくさんあります。ですから、三期というのはすごく絞った時期であったと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今度の骨子案の、まず２ページ目で気になっているところが１個あります。この表の中で行くと、真ん中に長期基本計画が入らないとおかしいんじゃないかなという気がしましたが、その辺お答えをいただきたいと思うんですが。","respondent":"冨岡高齢福祉課長","answer":"この骨子案をまとめる段階では、まだ策定という部分で現在進行形でございましたので、当然基本計画の策定の状況を見すえながら、この中に取り組んでまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"三点確認なんですが、第五期までに１３カ所に原則１カ所というところの第五期までというと、四期中にやるということですか。ここら辺はどういう仕切りをしているのか。","respondent":"冨岡高齢福祉課長","answer":"これから２カ所見込みが立っているわけでありますが、なかなか３年間で１３全部というのは、計画としては非常に難しい。それから２点目の大井・八潮地区ですが、これは、私が説明を忘れまして恐縮です。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺何か説明や報告がしていただける部分なのかどうか。急にこれが出てきたような気がするので、その辺を教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"これにつきましては、作成のぎりぎりのところで民間型ということで話が出ておりまして、それで載せさせていただいたということで、これはまだ進みつつある状況です。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺もこれから条例ということなんですが、量的なものとか予算というのはどのぐらいの規模なのかというのを教えていただきたいのが二つ目。なかなか利用料金が高いといったところにおいて、家賃助成とかの低所得者対策がぜひ必要ではないかと思うんですが、この辺の見解も説明を求めました。","respondent":"冨岡高齢福祉課長、木下福祉高齢事業部長","answer":"これは三つございまして、まず要支援者を通院介助サービスする部分、それから要支援者の外出支援サービスをする部分。ある程度適地ができた場合ということも考えて、どれが一番ということではなく… 問題意識として今後拡充ということは考えていかなければいけませんが、区が直接、現実にはなかなか厳しい面があると考えています。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１６.４％見込んでいたのが、この三期の平成２０年、これは実数ですかね。今回のところで、どうしてこんなに数字が低くなっているのかというのをお聞かせほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"今後、それからリハビリの拠点としての老人保健施設の整備を検討するという形で、この３年間は対応させていただきたいと考えております。要介護と要支援の部分で、以前要支援だった方が、要支援２と要介護１の二つに分かれたということで。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"１０年の長期基本計画のところだったらそれの文章が載ればいいし、第四期においてのめどというのもきちんと書かれるべきではないでしょうか。そこのところをもう１回お伺いしたいです。","respondent":"木下福祉高齢事業部長","answer":"もう１点は、保険者として優良なサービスを品川区の中に導入するという考え方をとる必要があるということです。例えば先ほど出ました特定施設は１３ブロックに一つという考え方があるわけでありますから、そういうような部分で。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"南大井１カ所では、もうちょっと積極的に踏み込んでお考えいただければと思うんですけれども、改めて区のお考えを伺います。私はよく知らないんですけれども、区としては、四期では介護予防および特定高齢者というのはどういう形で実施していくことになるのか説明を求めました。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"医療職の確保とか、直接区が設置するということではなく、医療法人の方から手を挙げていただくような方向というのがあれば一番望ましいわけですね。その辺の問題の認識は持っておりますので… 特定高齢者がそのまま要支援にならないように、今後も継続して、予防マネジメントの中で対応していくつもりです。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"もう少しどこか「ここで知恵を使いました」というところがないと、新たな計画ですとは言いにくいと思うんですけれども、いかがでしょうか。何か工夫するところはないんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"これが、３年間区として努力してきた結果として、一応制度的には特定高齢者という方々についてはかなりの数が把握できるようになってまいりました。","id":"exchange-036"},{"speaker":"浅野委員","kind":"質問・要望","question":"今の質問にも関連するかと思うんですが、三期限りでやめてしまうものとか、そういうものがもしあればちょっと教えていただきたい。特に、大切に育てていかないといけないという部分もあるかと思いますので、この方針等につきましてもあれば教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"非常に献身的に取り組んでいただいていまして、地域の福祉の担い手としてご活躍いただきたい、また協力いただきたい。ぜひ、このネットワークの中心になっていただきたいと思っているところです。","id":"exchange-037"},{"speaker":"浅野委員","kind":"意見","question":"ある意味では負荷の分散とかということも、必要に応じてＯＢの方に再度お願いするとか、そういうようなことも考えられなくはない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これがちょっとわからないので中身を教えていただきたいのと、地域で説明を行っていただきたいと思うんですが、その点が一つ。もう一つ、その辺がどうなっているのかお伺いしたいのと、もしそうなったらその辺をどうやって補っていくのかなというのも聞かせてください。","respondent":"冨岡高齢福祉課長","answer":"協議をいただいて、現在のところは社会福祉協議会のさわやかサービスのみがお出かけ移送サービスということで実施をしています。それから、パブリックコメントにつきましては、現在説明会については考えておりません。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"パブコメの期間が何日間なのかなというところと、重ねてですが、保険料のこの表を見ても中身がなかなかわかりにくいので、ぜひ住民の方も質問も受けられるという意味では、ぜひ説明会をやってからパブコメをやるべきではないかなと思うんですが、再度いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"パブコメの期間ですけれども、今の予定では２月１日から１６日までを予定しております。それから、説明会につきましては、現在のところ考えておりませんので、その内容を見ていただいて大いに意見をいただければと考えています。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"意見","question":"厚生労働省の要介護認定のところの調査項目が変わるというあたりが、今年の４月と聞いているので、その辺がどういう扱いになっているのか。いろいろ問題点が起きると思うんですが、その辺の対策とかがあったら聞かせてくださいとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"今の項目の変更につきましては、聞き及んでいるところですけれども、今後の詳細についてはまだ手元に情報が入ってきておりませんので、引き続き注視をして対応してまいりたいと考えております。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１０ページの市町村特別給付についてお伺いしたいんですけれども、ここで３点、１番はおおよそわかります。それと、先ほど保険料で９億円基金の取り崩しをしますということで言われましたが、この２億円は９億円の中に入っていると考えていいんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"要介護者の方に対して、夜間対応型の訪問介護サービスを実施いたしておりますけれども、これを要支援者の方まで広げていくという内容です。具体的にあれできませんが、サービスの経費について１万円から５万５,０００円までの、それでは事業者の方に非常に負担になる。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、これは要支援の方が例えば夜間のおむつ交換だとか身体介護というふうなところで使われるということなんでしょうか。次に、都南の跡地に３カ所つくったほかに、この第四期でケアホームをつくるという考えがあるのかどうかということをお聞かせほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"夜間対応型の訪問介護サービスをなぜ要支援にです。あるいは要支援の方でも、要介護から要支援に認定の結果移って、特別給付としてフォローしてまいりたいと考えているところです。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平成２２年、平成２３年ということで出されていまして、これは平成２０年度を１００としたときの考え方ということでいいんでしょうか。保険料の問題なんですけど、この第１段階から第９段階までの段階別の人数がどれぐらいなのかというのを教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"例えばホームヘルプとか通所介護とか一つ一つについて今後どのぐらいの伸びが見込まれるかということを、全部推計をしているところです。各段階ごとの人数については、今、手元に資料がないので、保留させていただきたいと思います。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"各段階ごとの人数というのは、後でもお知らせいただくことはできますでしょうか。いつも大体パーセンテージで毎回出されてくるんじゃないかと思います。","respondent":"冨岡高齢福祉課長","answer":"今、正確なところを調べておりますので、後でまたよろしくお願いいたします。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ、人数でもパーセンテージでも教えてほしいと求めました。そういう第三期の他区の状況も踏まえて、なぜ３００万円以上が一率同じ額というようにしたのか、そこら辺の考え方について説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"例えば９段階をさらに伸ばして、２倍ぐらいとったらというお話もあるかもしれませんけれども、いろいろ検討する中で出てまいりました。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もっと５００万円以上、１,０００万円以上、２,０００万円以上の人に負担を求めているという区が多くあって。そこら辺の配慮した形での保険料設定というのはできないものなのかというところを最後にお聞かせほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"平成１９年度の経過措置を継続することができるということで、平成１９年度の措置を平成２０年度にも適用したということであります。今回の新４段階が設置されておりますけれども、新４段階というのは、品川区としても新４を設けることによって配慮させていただいた。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうことで、厚労省からの政令も出されて第４段階の８０万円以下の方というふうなものが区としてもつくられたということですので、これをぜひ。それから第６段階もそういうことで、ぜひご検討いただけたらというふうに要望をして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そう理解していいですか。どういう計算方法なのか、考え方として１８万１,５０６円からそっくり１万８,０００円引いていいのかどうかという考え方として教えてもらえますか。","respondent":"冨岡高齢福祉課長","answer":"考え方といたしましては、例えば１８万１,５０６円から１万８,０００円を引いていただくというように、トータルから引いていただくということです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"この指針がどういうところから出ている何という名前なのかもちょっと教えてほしいんですが、自治体が勝手にやりなさいという中身なのかどうか、その辺も説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"Ｂタイプ、Ｃタイプで、なるべく厚生年金の方でも入れるようにということを一つの考え方として進めてまいりましたので。今、検討しておりまして、これは条例案で改めてご提案させていただきたいと考えています。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"例えば家賃のところが５万４,０００円ですけれども、本当に選ばれた人というか、その特別給付の使い方はすごく疑問です。ケアホームとグループホームのところの居室の広さ、前に聞いたかもしれないんですが、もう１回説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"個々には若干違う部分がありますけれども、ケアホームについては１５平方メートル以上、１８平方メートル未満です。それからグループホームにつきましては１２平方メートルです。","id":"exchange-051"},{"speaker":"阿部委員","kind":"質問","question":"募集に関してなんですけれども、これはケアマネさんを通して募集ということでいいんでしょうか。それで、募集期間はおおむね２０日間、３週間程度となっているんですけれども、これは大体こんなものでよろしいんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"在宅介護支援センターと連携しながら、その中で連携をとりながら進めてまいりますので、基本的には大丈夫かと思います。","id":"exchange-052"},{"speaker":"阿部委員","kind":"確認","question":"例外的に区外を使っていらっしゃる方がいるという話を聞いたことがあるような気もしたんですが、私の勘違いですか。それはないか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"申し込みの中に一緒に在宅介護支援センターという形で挙げていただいて、在宅支援センターの方で私どもの方で探して、「どうでしょう」という形で連絡を取れるということでフォローができるかなと考えています。","id":"exchange-053"},{"speaker":"浅野委員","kind":"質問","question":"たしか避難通路をどうするのかという質問をさせていただいたことがございまして、４月入居ということになりますと、どのような形で避難をするのか。その辺も解決をされたのかなと思いまして、この１点だけお願いいたします。","respondent":"冨岡高齢福祉課長","answer":"避難通路につきましては、消防法の関係等がありますので、確保されているというふうに申し上げていいと思います。","id":"exchange-054"},{"speaker":"浅野委員","kind":"質問","question":"確保されているということであれば、安心してというふうに思いますので、ぜひとも、前に質問した項目ですので、また何らかの機会に教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"先ほどの特別給付の関係なんですけど、サービス提供に要する費用の算定基準というところで、このあい差の分というのは、結局事業者が負担するということで、本人の利用料負担が２万円ずつ全員引き下がるという考え方で、理屈はいいわけですよねとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"結果的には１割引きますから１万８,０００円ということになりますけど、引き下がるということでご理解いただければと思います。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、西大井は１.５対１体制だったと思うんですけど、ここは何対１ということになるのかということをひとつお聞かせいただきたい。それから、そういうことで２万円というのが出てきたのか、その２万円という額がどうして出てきたのかということとあわせて説明を求めました。","respondent":"冨岡高齢福祉課長、木下福祉高齢事業部長","answer":"この部分については、大体１対２.５人での報酬費を挙げておりまして、実質的には指定管理者が２対１でやるというような話で進めているところです。そういう形で進めてまいりたいと考えています。そうすると、住みかえということも先々考えていったほうがいいだろうというふうになりまして、グループホームですと、ここは今、１７万円弱です。","id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だって、これだけお金が払える人というのは、本当に国民の中でも一部の人なわけじゃないですか。基金を使ってやるわけですから、所得の少ない人は、どんなに保険料はとられてもここには入ることができないわけですよね。","respondent":"木下福祉高齢事業部長","answer":"考え方といたしましては、言ってみれば施設整備のイニシャルコストがあって、国や都のいろいろな補助金がありますね。より低減するためには、既に一般財源投入というのは、区としてはイニシャルコストの中で十分にやっているです。","id":"exchange-058"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今の説明ではちょっと納得いかない。どう考えてもおかしいんじゃないかなと私は思いますので、ぜひ、品川区の一般財源で減額制度をつくっていただきたいという要望で終わります。","respondent":"小林保育課長","answer":"立会小学校を避難場所とする形で、今、学校との調整がほぼ合意に至っております。その経路については詳細詰めておりますので、３月までには具体的な通過地点の確定を含めて、避難経路の確定をしてまいりたいと考えています。","id":"exchange-059"},{"speaker":"浅野委員","kind":"質問","question":"先ほど言いましたように、高齢者の方も多分この避難経路は、立会小学校に行くような経路を通るんですかね。それをメインに伺ったわけなんですけれども、もし決まっていなければ決まったときで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"当初、休館しないで工事をすると伺っていたんですけれども休館になって、なぜそのことが遅かったのかなと。ですから、周りも、「休館しない」と聞いていたはずのものが変わったという話を聞いたもので。","respondent":"諸岡児童課長","answer":"かえって危険を伴うということをいろいろ考えまして、その段階で、これは休館にして実施していこうとなったということがあります。検討いたしました結果、１カ月半休館をして、そのように進めていきたいと思っているものです。","id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"質問","question":"状況はわかりました。ただ、設計が決まったのというのはいつごろだったのか、そこだけ説明を求めました。","respondent":"諸岡児童課長","answer":"具体的な構造設計、それから実施設計を含めまして決まりましたのが１１月に入ってからの段階でございました。私どもで十分検討いたしまして、１２月に入りまして、これは閉館をせざるを得ないだろうという結論になりました。","id":"exchange-062"},{"speaker":"阿部委員","kind":"質問","question":"長期休業中は丸１日使うような子どもも、春休みに当ててこの期間を組んだとか、外そうとしたけど外せなかったのか。それともお休みとはかかわりなく、工事の都合でこの日程になったのか、ちょっと考え方を説明を求めました。","respondent":"諸岡児童課長、永尾高齢事業課長","answer":"耐震工事につきましては、今年度９カ所工事を予定しておりまして、今年度の耐震補強ということでかなり急いでということでやっています。その９カ所の補強工事を進めていく中で、それから実施設計をやっていく中で… 今後のスケジュールですが、今年度中に実施設計を終わらせまして、工事は今年１０月から来年１月までの４カ月間を予定しております。","id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ご高齢の方だから、例えば１年間空いてしまうと、次に来られなくなってしまう。それはお願いしますとの意見を述べました。","respondent":"永尾高齢事業課長","answer":"その状況については私もご利用者から直接いろいろお伺いしておりまして、個々に対応するということでやっていきたいと思いますので、よろしくお願いいたします。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/854582?Template=document&Id=3226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":64280,"voices":147}},{"id":"h21-20090120-8","meetingId":"h21-cm01","date":"2009年1月20日","dateIso":"2009-01-20","committee":"建設委員会","time":"午後１時０２分～午後２時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１つだけ伺いたいのですけれども、どこがどのように調査して、どのように規制をかけていくのかという流れを教えていただけますか。","respondent":"諸石交通安全担当課長","answer":"それをとらえて、昭和４７年の春の交通安全運動から、ゾーン規制というものが日本の各地で実施されたです。当区におきましても、昭和４７年から幾つかの小学校をモデルケースとしてスクールゾーンという面規制を実施したと聞いております。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"マンションが一つ建ち上がると５００世帯とか、大変大きなマンションが最近は建ち上がっています。例えば親からスクールゾーンに指定してほしいということが出てきた場合、ＰＴＡが警察と交渉していくのか、その辺だけ説明を求めました。","respondent":"諸石交通安全担当課長","answer":"その部分で、各警察署のほうに規制のお願いを仲介するというような形で、当区の場合は実施しています。警察と一緒に実査をいたしまして、必要ということであれば警察署から公安委員会に上申していただくという流れになっております。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"交通規制の規制内容ですが、車を通行止めにするということも含まれているということですけれども、全部がそうではないですよね。うちの近くにただ小さな看板がありますけれども、具体的には規制としてどのような段階があるのか尋ねました。","respondent":"諸石交通安全担当課長","answer":"線の規制ですけれども、路線の規制につきましては、大半のところが歩行者専用道路あるいは歩行者および自転車専用という形で実施しております。子どもが安全に通学できるかという検討を警察と学校関係が実施しまして、例えばゾーンの中に入る道路、そういうわけではございません。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"それぞれの地域の現状での住民数と世帯数、それから準備組合に参加している人数、実際のこの地域の地権者、借地権者はどのぐらいなのか教えていただけますか。","respondent":"青木都市開発課長","answer":"既に認可申請の段階ですので、所有権者につきましては７５.６％相当、借地権者につきましては１００％の同意を得ております。借地権者が４名、所有権者が９２.５％、借地権者が７５％の同意をいただいて申請に至ったという現状です。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"特定事業参加者が決まっていると思いますので、その辺も教えてほしいと求めました。お聞きしたいのは、北品川五丁目第１地区の場合は１００ｍ級の建築物が３棟ぐらい建ちますね。","respondent":"青木都市開発課長","answer":"以前に建設委員会および教育の方の所管委員会で、この再開発事業に合わせて御殿山小学校の改築等を検討していくという答弁をしたと記憶しています。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"午前中の日照は確保できるだろうと。一体化をすることで容積率が大きくなるということなのか、それとも学校そのものの位置を変えていくということなのか、その辺がよくわからないとの意見を述べました。","respondent":"青木都市開発課長","answer":"説明が足りなくて申しわけございません。そういった検討をした上で、そういった形で言えば、何とか御殿山小学校の環境は維持できるという判断の上に現在の計画を進めているものです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"提案","question":"こうすればいいと教育委員会に対して提案をしたということだと思いますけれども、グラウンドそのものに日影が現実に落ちるわけですよね。グラウンドの端のほうに校舎棟を持ってこない限り、無理なものなのではないかと地図を見ていると思うんですけれども、どうなんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"これは数年前の建設委員会ならびに文教委員会に図面を添付して、既に議会にはご説明済みです。そのときには法定再開発事業を進めるにあたって、地区計画の変更を行っております。","id":"exchange-007"},{"speaker":"井上委員","kind":"確認","question":"今、答弁の中に入っていたかもしれないですが、北品川五丁目第１地区の地域コミュニティ施設と子育て支援施設はどういうものなのか、確認の意味で説明を求めました。","respondent":"青木都市開発課長","answer":"集会所といいますか、ギャラリーといいますか、そういったものを権利者の方々の提案として地域に設置したいというものを想定しております。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"大崎の違うところのように区に譲渡とか無償提供するというものではないのかどうかということが１点と、企業に預けたものになるのかというところは、どのような計画になっているのか尋ねました。","respondent":"青木都市開発課長","answer":"例えば区に譲渡するとか、民間で運営するとかという運営の仕方については、現在まだ検討中で結論は出ておりません。それから、子育て支援施設につきましては、これは別の所管のほうで幼稚園や保育園の設置のあり方等については議論いただいているはずですので。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"品川区は総合体育館の権利者として、区の施設がここにあるのかないのかというのはどうですか。共有とするのか、あるいは区の施設としてこの中に何かつくるという計画はあるのか尋ねました。","respondent":"青木都市開発課長","answer":"提案して、これが認可される見込みですから、権利者の一員として応分の責任を果たしていくという位置づけになります。ただ、組合の一員としてこういった施設に何らかの一定の責任を負っていくというのが、現在の品川区の姿勢です。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"どうもよくわからないのは、１つは、その辺の説明も少ししていただきたいなと思います。わずか十数万円の所得ということは、その辺の考え方は、どうやってとらえればいいんか尋ねました。","respondent":"齋藤住宅課長","answer":"所得の考え方ということですけれども、２つあります。そういうことでございまして、法令に従って料金設定をせざるを得ないです。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"法令に従って、もちろん公営住宅ですから、国が設定した家賃体系を逸すれば公営住宅にならなくなってしまうというのは確かですよね。私もよくわからないんですけれども、要は、ほんとうに限られた人たちだけが入居できる体制づくりを進めるということでとらえていいのか尋ねました。","respondent":"齋藤住宅課長","answer":"６００万円、７００万円、公営住宅からご転居いただいて民間でお借りいただくという形で努力義務が生じるです。こういったことをお伝えしながら、より低所得者の方に入居していただくように声かけをきちっとしていきたいと考えています。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"もう１つ聞きたいのは、こういう場合に、例えば減免制度というのがありますよね。減免制度そのものは、中身として変わってはいかないわけか尋ねました。","respondent":"齋藤住宅課長","answer":"第１区分の方は、今回、使用料もお安くなります。そういう意味で、低所得者に対する使用料というのはお安くなっているということで、制度の趣旨自体は間違ったものではないと考えております。","id":"exchange-013"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"井上委員","kind":"確認","question":"ちょっと先に確認というか、現状をお伺いしたいところがあるんですけれども、うまく着いていないという状況があると思うんです。しながわ中央公園でも、西小山の道路整備に伴って、補助３０号線のところの現状がどういうふうになっているのかというところはいかがか尋ねました。","respondent":"松代管理工事課長","answer":"植えて１年間の間に、保険に入っておりまして、新しく植えかえるということも状況を見て対応していきたいと考えています。先般ご説明しましたが、今年の３月までに完成を予定しておりますけれども、一体的なもので今進めております。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"そういったところの対策が、対策は当然とられていると思うんですけれども、きちんとそういうことは経験則に基づいて行っているのかと。そういったときに、そういったところの対策はちゃんととられているとは思いますけれども、どういうふうに考えていらっしゃるのか尋ねました。","respondent":"松代管理工事課長","answer":"そこの道路幅員が１１ｍしかございませんけれども、それを双方通行にするような形で車線の変更をしました。は請け負った技術者に加えて、その特性を見て、その桜が一番活着しやすいような対応等をとって実際やっているところです。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"担当の方に伺うと、そういうところで支援しますよとか、そういうことも木を大切にする思いみたいなことが育つと思うんです。それに関連して、それをこれに合わせてどういうふうに進めていこうとしていらっしゃるのかというところをお願いしたいと思います。","respondent":"藤田道路公園課長","answer":"緑の基本計画ではありませんというような形の記載もありますので、そのことも含めながら施策のあり方については今後考えていきたいと思ってあります。件数がよく上がっていないというのは認識しておりまして、緑の実態調査の中でも、実際にまちをもう少し確認しようよと。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、あまりそういうところを打ち上げていないので、相談の電話もあまりないということを伺っております。そういうことも含めて、今後ぜひ広げていっていただきたいなと私は思っていますので、検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"三上委員","kind":"質問","question":"そのほか洗足までの間に対しても、緑道のこれからの計画、スケジュール的な部分というのは、現段階ではどうなっているのでしょうか。ちょっと教えてほしいと求めました。","respondent":"松代管理工事課長","answer":"それは今年度、完了する予定です。来年度、西小山地区の工事にかかって、そこの部分も、一応おおむね完了する予定です。","id":"exchange-018"},{"speaker":"三上委員","kind":"質問","question":"そうすると、今、目黒線上部の武蔵小山駅周辺については３月いっぱいで、要するに駅前広場と合わせて、その整備はすべて終わるという考え方でよろしいのか尋ねました。","respondent":"松代管理工事課長","answer":"終わる計画です。おおむね終わると思いますし、終わるように一生懸命、頑張っております。","id":"exchange-019"},{"speaker":"三上委員","kind":"質問・要望","question":"それが放置されたままですから、ガードレールより２０cm以上も高く伸びているようなところがいっぱいあるわけです。そこらあたりは、いかがか尋ねました。","respondent":"藤田道路公園課長","answer":"その辺をご理解いただく中での管理というのもあろうかと思いますので、東京都のほうにも、その辺は申し出ていきたいなと考えております。","id":"exchange-020"},{"speaker":"三上委員","kind":"質問","question":"畑仕事も随分やったりしてきた経験があるものですから、身近なところでのそういうことの提供というのは、積極的にやっていただければなと思います。そういう案内をするような形のものも、これからやっていけないのかなと思っていますので、そこらあたりはどうか尋ねました。","respondent":"藤田道路公園課長","answer":"そういうのがスタートで、公園等については、大名の庭園だったところが一般に公開されたりとか、そのような形で公園行政自体もスタートしております。なかなか制約もあるとは思いますけれども、今のお話を参考に、生かせるものについては検討していきたいと考えています。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"１つだけ。これからそういうものをつくっていくというか、そういう流れで考えていらっしゃるのか、ちょっとその辺をお聞かせ願えますかとの意見を述べました。","respondent":"藤田道路公園課長","answer":"１つは大規模な緑地がぽんとできれば増えますけれども、品川区で考えたときに、非常に厳しい状態であるというのは間違いないのかなと思います。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問・要望","question":"あるのだと思うんですけれども、長期基本計画で考えたときに１０年間の施策だといったときに、「いつまでにどうするんだ」みたいな基本的な考え方があれば教えていただきたいです。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"１つには、基本構想をつくり、みどりの条例をつくりというような形で着実にそれを推進するような形をしてきました。向こう１０年間の中で、これまで続けてきたことを着実に少しずつ積み上げていく… それから、緑化推進計画、先ほども申し上げましたけれども、その中で１２.２％という緑被率を目標にしてまいりました。","id":"exchange-023"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"その辺の考え方を教えていただきたいのと、みどりとイメージすると、どうしても環境の部分も連動してくるのかなと。教育の部分とも、どのような連携体制を行政の中でとられているのか、もし何か具体的な例がありましたら教えてほしいと求めました。","respondent":"藤田道路公園課長","answer":"トータルで考えれば、私どものほうとしてはやっていきたいと考えておりますので、所管部署のほうとも十分調整をしていきたいと考えています。なかなか現状ではどうなのかなと私も考えているところがございまして、今後、よりよい形で進んでいくのかなと考えているところです。","id":"exchange-024"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"三上委員","kind":"質問","question":"前にもお願いしていましたが、庁舎の耐震工事、免震工事の調査というのはどうなっているのでしょうか。今日、総務委員会が視察に行くという話をさっき聞きましたけれども、どうか尋ねました。","respondent":"松代管理工事課長","answer":"総務委員会が基本的には所管委員会ですので、そちらから情報を得まして、委員から申し出られた内容で、一度ぜひ調整をさせていただきたいと思います。申しわけございません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":32497,"voices":87}},{"id":"h21-20090120-9","meetingId":"h21-cm01","date":"2009年1月20日","dateIso":"2009-01-20","committee":"文教委員会","time":"午後１時０4分～午後３時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"１の校舎改築事業の進捗状況","agenda":"１の校舎改築事業の進捗状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この前、６月の文教委員会でもちょっと伺ったんですけれども、国庫補助率について説明を受けたいと思っています。２つを組み合わせてきた事業というのはどういう意味なのか教えていただけますか。","respondent":"市川教育次長","answer":"さらに、ちょっとこれは全体をきちんと説明するとかなり時間がかかりますので、まず大きなところでの説明ということでご了解いただきたいんですが。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ２分の１とあって、いわゆる構造上危険なものは３分の１だというふうに記されているんですけれども、ちょっとそこを教えていただきたい。ちょっとここに第三条の１がこういう条件、第三条の２がこういう条件、教えていただきたい。","respondent":"市川教育次長","answer":"ほとんどが２年後。１つの改築の案件の中で、どういう助成金を組み合わせたら一番特別財源として確保できるのかという仕組みというか、運用をしています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"この７つの中のどれなのか、それともいないのか、そこを伺いたいなと思ったんですね。適正規模の名前で進むと２分の１だと、お伺いしたんですけれども、そこを教えていただけますか。","respondent":"市川教育次長","answer":"ですから、ただ単に２分の１だということはありません。それからそうでないところについては補助金の適用ということで、適用を受けているというのが実情です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"適正規模についての審議は、今まで議論を進めて、最終答申が出されて、今後どうするかを考えていくという姿勢。一方で、適正規模のために補助金を獲得する整合性がどうも見えてこないんですが、ここら辺、もう少し整理してご説明していただけますか尋ねました。","respondent":"市川教育次長","answer":"これは平塚中学校と荏原第二中学校の統合ということは、２つの中学校の近い将来から将来に向けての教育環境を考えて行ったものです。この後先は決して、大変いろいろ影響が出ますので、ぜひその点は誤解なきようお願いいたします。","id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"確認だけさせてください。非常に桜並木ですか、いいところもあったりするものですから、ちょっと答えられる範囲内でいいのでお願いしたいと思います。","respondent":"田村庶務課長","answer":"時期が全体の会社の方針が固まった上で、できれば早くというのが区の考え方ですから、その辺も調整をしていくです。来年度１年かけて検討することなので、フリーハンドで、これから検討していくという状況にあります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと頑張っていただきたいと思っています。いろいろご要望があるかと思うんですが、その辺はどういう形で進めていくか、いこうとされているのかをお願いします。","respondent":"田村庶務課長","answer":"準備会を２月の頭にも３回目をやる予定ですが、あるいは屋内体育館の中に武道場を入れてくれるんですかという話が具体的に出ているんですね。５年後のイメージを出したので、先ほどの説明の中にありましたけど、またご意見をもらうという形になるのではと思います。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つ教えていただきたいのですが、準備会というのは何をやるのが準備会と理解すればいいのか。懇談会は、我々の理解として何がどこまでが懇談会なのか、それを教えてほしい。","respondent":"田村庶務課長","answer":"やはりこれから基本計画あるいは実施設計と、そういう方向性を出すまでに至る経過を地元に説明して、学校関係者と協議しながら。ですから、基本設計あるいは実施設計を進めていきたいというかかわりを持った準備会あるいは懇談会という位置づけで考えていただければと思います。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"今のお話の準備会みたいなものだったら、先の流れは別としても、今のお話だと始まっていると思うんだよ。だから何でここで、ここのちょっとの色でもいいんだけど、そういうものが文教委員会に出てこないわけ、今の学校改築の事業現況報告書の中にとの意見を述べました。","respondent":"田村庶務課長","answer":"あるいは学校からの地元への説明という形で、正式には平成２１年度予算の中で動くという形なので、改築の進捗状況の中には荏原第六中学校も清水台小も載っていないです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"現況報告をしようというわけだから、１月現在だって動いているわけでしょう、今の話は。それだったら、私はこれはやっぱり今みたいな予算という話とちょっと違うんじゃないかなと、報告事項だったらと思いますとの意見を述べました。","respondent":"市川教育次長","answer":"確かに来年度の入学者、その保護者、それから在校生の保護者に向けて、先般の耐震補強の診断結果の報告、これに関連して説明会等行ってあります。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういう説明というのはいつ、どの段階になるのか、ちょっと教えていただきたい。どうしても近隣との関係でうまくいかない事例もよく伺っているだけに、いつどういう段階で、地域住民に対する説明を行うのか教えていただけますか。","respondent":"田村庶務課長","answer":"どこの時点かは別としても計画説明会というのを地域も含めて１回か２回やって、具体的に工事に、通常ですと工事の説明会をやるということです。事前に、場合によっては仮設校舎の工事の説明会というのもまた前倒しでやりますので、まだ具体的なのは決まっていないです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうしても校舎の向きだったり、高さだったり、今まで手が届かなかったところに届いてしまう。理解と協力を求めていきたいと思いますけれども、まさに要望ですけれども、丁寧に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"２の第二延山小学校の休校措置","agenda":"２の第二延山小学校の休校措置","exchanges":[{"speaker":"川西委員","kind":"質問","question":"第二延山小学校の経過から伺いますけれども、保健所に通知が行ったのが２８日でよろしいですか。ちょっと伺っておきたいと思います。","respondent":"富田学務課長","answer":"保健所に通知いたしましたのが２８日、学校より連絡を受けて、教育委員会よりその日に速やかに連絡をしたところであります。３点目に、臨時休業を実施・決定するに当たっての人数の目安というようなことかと思いますが、学校長が決定をするということになっております。","id":"exchange-012"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、保健所への教育委員会からの連絡は２６、２７のこの増えた状況ではまだちょっと様子見という判断をしたということでよろしいんか尋ねました。","respondent":"富田学務課長","answer":"教育委員会が学校より連絡を受けて、状況を把握したのは２８日ですので、教育委員会で把握した時点で保健所に連絡をしたということです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"状況的には広がるのか、状況によっては委員長の判断で臨時に開くこともあり得るでしょうから、ぜひ委員への報告は重ねてお願いしたいと思います。そのための対策を打ったということでよろしいのかどうか、ちょっとそこを伺いたいなと思っています。","respondent":"富田学務課長","answer":"教室内でやはり１人吐いたお子さんがいたりしますと、そういった吐いたお子さんがいた場合には、速やかにそういった処置をすると。そういったことが何よりも肝要であろうかと思います。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"こういう姿勢が大切なのかなと思っています。単純に言えないでしょうけど、学校の職員や給食の受託事業者の職員の方々の症状というのは何かあったのか、なかったのか教えていただけますか。","respondent":"富田学務課長","answer":"教員につきましては、子どもと同じころに若干ぐあいが悪くなった教員がいるような話は聞いておりますが。お子さんより先にこのような症状があったというようなことは聞いておりません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"事前にどういう対応策が練られていたかということを伺いたいんですけれども、この事実経過を見ていくと、１２月１日に行ったのかなと思ったんですね。そうすると、この教育委員会に連絡があったのが１１月２８日ですから、連絡があったときにそういう対応をするということなのか。","respondent":"富田学務課長","answer":"毎食、保存食というものを保管しており、検査をできるようにしているところであります。学校からの聞き取り、調理事業者に対しても検便の依頼等々をしていったですので、これは保健所から依頼をしてやっているというものです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"再発防止に向けた対策は、責任者が常に見直しをかけて、最善のものをぜひ積み上げていただきたいと思っています。そういうのはどういう事項として入っているのか、契約事項ではどういうふうに規定されているのか、そこらあたりを教えていただきたい。","respondent":"富田学務課長、市川教育次長","answer":"契約の仕様書等々、申しわけございません。お話しできませんけれども、そういったものにつきましては、保健所の十分な指導に従っていくということになろうかと思います。私どもが業者選定をするときに、こうした今申し上げたことへの対応がどう全社的にされているのかという、そこは必ず見ております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"今、契約事項が手元にないのはいいんですが、そういう中にきちんと盛り込まれているという理解でよろしいんか尋ねました。","respondent":"富田学務課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"山元委員","kind":"質問・要望","question":"１つお伺いしたいんですけれども、すまいるのお子さんたちがこのときはどういう状況だったのか、その辺どんな状況だったのか教えてほしいと求めました。","respondent":"田村庶務課長","answer":"学校と連携して、同じ対応をとったという方向で、実際に対応しました。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。これは結局どうなったんですかと言われたって、そこら辺の経過報告がどういうふうに取り扱われているのかというのを説明を求めました。","respondent":"富田学務課長","answer":"この本報告は、学校の教員に対しては学校長より口頭にて報告がなされていると考えております。調理事業者に対しましては、私どもを通しまして、保健所からの最終的な報告というものを業者のほうにお渡しをしています。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"意見","question":"例えば担任の先生がどうなったのとかいろいろ聞かれたりしたときに、口頭だと、本当にまた言葉が違う言葉を生んだりすることがあるじゃない。ある一定のこういうものがあれば、何か正確な情報がちゃんと、学校サイドとしてできるんじゃないかなと思ったという意味で言ったんですとの意見を述べました。","respondent":"市川教育次長","answer":"後から１つご意見をいただいたのは、地元の町会長さんたちも、「どうしたの」と聞きたいのに聞かれる立場になっちゃうんだということを言われました。","id":"exchange-021"},{"speaker":"市川委員","kind":"質問","question":"もうちょっと早く家庭での注意の説明というのがあってよかったんじゃないかなと思って、その辺がどうなっているのかということ。それから第二延山小学校のこの集団感染があって、他校については今どんな対応をされているのか、その辺を３点伺いたいんですけど。","respondent":"富田学務課長","answer":"それがなかなかストップ、この保護者会での説明の中で、ノロウイルスについての細かい説明を行ったと。そういう意味では十分保護者会での説明でご理解いただけ、収束に向かったものというふうに考えているところです。","id":"exchange-022"}]},{"id":"topic-03","title":"３のスクールゾーン・通学路の交通規制時間の変更","agenda":"３のスクールゾーン・通学路の交通規制時間の変更","exchanges":[{"speaker":"川西委員","kind":"質問","question":"それでいいですか。ちょっとすみません。","respondent":"河野指導課長","answer":"赤の網かけになっているところが、いわゆるスクールゾーンということの指定で、そこの車の通行規制が７時半から８時半に今回変更されるはずです。それ以外のところについては、もう既に改正されているところと、全くそういう時間規制がかかっていない道路が大部分です。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"今の説明ですけれども、この赤い部分が改定される場所であって、既に７時半から８時半に規制をされているところはもっとあるということですか。全部がこうだということか尋ねました。","respondent":"河野指導課長","answer":"既に８校のスクールゾーン、あるいは通学路については７時半から８時半の設定でなされております。７時半から９時であるとか、要するに７時半から８時半以外の交通規制について、すべて一斉に７時半から８時半に設定変更を行うという工事です。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"要はこれがないところは、全部７時半から８時半ということ……。もう１回お聞きします。","respondent":"河野指導課長","answer":"今回、この地図に記載されている斜線部分と、赤線の道路部分は今回の工事で７時半から８時半に規制時間を変更する箇所の表示です。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つかちょっと教えていただきたいことなんですけど、網かけのところと、線で指定をしているところと、どう違うのか。そこの違いをちょっと教えていただきたいのが１つと、あと学校が決まると、子ども一人一人に通学路というのを定めますよね。","respondent":"河野指導課長","answer":"それから、個々が提出する通学路のもう１つの意味合いは、これはいわゆる管理下の扱いということで保険の対象になります。その対象になるためには、基本的に届け出たルートを通行している間に、そのために届け出る各自の通学路というふうにご理解いただければと思います。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、ご説明があって、通学路といっても、２つの意味合いがある。警察ともよく連携をとりながら、改善に向けて引き続き取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいんですけど、常々思っていたんだけれども、こういうスクールゾーンとか通学路の交通規制って、登下校で言うと、登校じゃない。でも８３運動は一生懸命やりましょうと、そこの場合はものの３０ｍぐらいなんだけど、よくそこら辺はわからないので教えてもらいたいなと思います。","respondent":"河野指導課長","answer":"例えば午後１時から４時まで、時間規制をして、要するに歩行者優先道路という指定がされている道路があります。その午後の一定の時間帯を歩行者優先道路扱いにして、交通規制をかけて、子どもたちの遊び場ということで提供している地区もあると聞いております。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"意見","question":"地域運動として町会として盛り上げましょうとやったのは、うちのほうもやったけど、それは知っています。いつからというのはわからないんだけど、そんな私が知っている範囲の最近では、地元同意なんかとったなんて記憶ないんだけどとの意見を述べました。","respondent":"河野指導課長","answer":"実は今回のこの７時半から８時半に時間変更をするという、こういうふうに時間変更させていただきたいということでお話を持っていき、同意しましたという書面をあわせて警察のほうに提出しているという経緯です。","id":"exchange-029"},{"speaker":"川西委員","kind":"質問","question":"ほかの方の質問でちょっと思い当たったんですが、先ほど指導課長のご説明の中に通学路・スクールゾーンを通らないで通学・下校した場合は、事故扱いにならないんか尋ねました。","respondent":"河野指導課長","answer":"保険の対象にならない。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"あるいは今度、全面的に７時半から規制されて、特に４月以降はなりますよという紙は保護者に配っていただいているのか。その辺の対策はどうなっていますか。","respondent":"河野指導課長","answer":"通学路として学校が定めて、警察のほうが交通規制をかける箇所については、すべての児童に学校のほうからお知らせをしております。これは４月当初、必ず保護者に通知をし、それに基づいて子どものほうも各自通学路の届け出を行うという取り組みです。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、わかりやすいこういう図面で児童・保護者に配っていただけるかどうかの確認をさせていただきたい。責任担当。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"川西委員","kind":"質問","question":"６時半ごろになると、今の校長先生じゃないですから、ご承知おきください。一通り通るだけですから、７時前から８時半まで、警察の前とこっちのほうに立たせたんですよ。","respondent":"河野指導課長","answer":"それから、２点目のその登下校時の管理・監督責任の考え方なんですが、これは基本的には家庭です。ただ、それに対してどういう形でそれぞれ関係機関に関与してもらったらいいのかというようなことでのアドバイスはいつでもできるかと思います。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"ちょっと難しいですか、ちょっと違うのかなという感じもありますが、その辺はおわかりになっている範囲で。それを見て、通学路を書いてくださいねという指示を学校から出していただくということが必要なのかなと思うんですが、この辺はどうか尋ねました。","respondent":"河野指導課長","answer":"適切に通学路指定を行い、警察等々と連携をした上で、時間規制等に着手をしていくです。これは警察に通報をすれば、警察のほうも周辺のパトロール等を強化して、違反者に対してはそれなりに厳しく対処しているというのが実態かと思います。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"伊藤学園のほうは、いろいろ調整を図って検討していただいたということはあるんですが、今後いろいろ学校ニーズがありますので……。せっかく変えたということもありますので、認識をしていただきたいということで、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"山内副委員長","kind":"確認","question":"１点だけ確認をさせてください。ここがもしスクールゾーン、それで何らかのけがをこうむった場合というものも、その保険の対象になるのかならないのかというのを１点説明を求めました。","respondent":"河野指導課長","answer":"これはおおむね３.５ｍ未満で、歩道の設置ができないような道路については、場合によっては一方通行というような措置をとるです。おおむね５.５ｍ以上の道路については、歩道を設置する、いわゆる車両の通行制限というような交通規制の対象にはなりません。","id":"exchange-036"}]},{"id":"topic-04","title":"４のオリンピックムーブメント共同推進事業少年少女野球教室の実施状況","agenda":"４のオリンピックムーブメント共同推進事業少年少女野球教室の実施状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"品川区とあれですけれども、２０１６年東京オリンピック招致運動を盛り上げたいという考えなのか、そこはどう考えているのか教えていただきたい。国と区、ゼロならゼロでいいですから、その負担割合もあわせて教えていただけますか。","respondent":"堀越生涯学習課長","answer":"それがまず基本のところであると考えておりまして、今回、このような機会を得ましたので、このような形での野球教室を実施させていただいた。経費は総額で４２０万円、すべて東京都の負担です。","id":"exchange-037"},{"speaker":"中塚委員","kind":"意見","question":"先ほど、オリンピックの招致運動、利益だ、国際だとありましたけれども、どうもその辺がはっきりしない。予算が通りやすいからやっているだけなんだったら、これははっきりしてほしいとの意見を述べました。","respondent":"堀越生涯学習課長","answer":"子どもたちにとっては、非常にモチベーションもアップしますし、スポーツに対する楽しさが実感できるのではないかと考えています。そういったものがすべてスポーツ振興につながるのではないかと考えていまして、このような事業を展開してまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"独自で行うべきだし、多くの区民はこの不況下の中で、これだけお金をかけてオリンピック招致をすべきでないという声も伺います。最後に伺いたいのは、先ほどオリンピックは必要だという話はありましたけど、最後にそこだけ説明を求めました。","respondent":"堀越生涯学習課長","answer":"いろいろなスポーツコミュニティの活性化、そういった部分を含めて、この事業を実施させていただきました。このインフラ整備、私のほうでお答えする立場ではございませんが、そのような対応がなされるのではないかというようなふうに認識しています。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"お答えの立場じゃない、教育委員会も主催者ですから、だから端的に言えば、莫大なお金をかけてまでオリンピック招致はすべきでないという声に対して、主催者である教育委員会はどう考えているんだと、答える立場でないとは、それは当たっていないと思うので、ここはちょっと答えてください。","respondent":"市川教育次長","answer":"今、それに対して、この実施したオリンピックムーブメントの事業の趣旨については先ほど課長から申し上げたとおりです。本物のプロの考え方、あるいは生活の仕方、この時期にひとつデモンストレーションという意味合いも兼ねて実施しようということで行ったものです。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"アスリートだったり、そういった方と直接触れ合う機会を子どもたちにつくっていく、これは大いにやるべきだと思うんですね。ですから、そことムーブメントをつなげるなということが私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"意見","question":"古田さんなり何なりなっちゃうのかもしれないんだけど、そういうものをオープンにしていいよというのであれば、そういう何かまとめたものを……。こういうペラ１枚でもいいんだけど、そういうものができるのか、できないのかなというところだけ聞きたいとの意見を述べました。","respondent":"堀越生涯学習課長","answer":"スポーツリーダーの養成に絡めて、そういうのができないかというのを今、内部で検討しているところです。指導者だけを集めた、それから指導者の方と親御さんを集めたような講習会も検討したいというふうに、ちょっと繰り返しになりますが思っていますので。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"これは主催が品川区ということで、東京都とコラボレートできたということなんですけれども、今後これはどういう形で続けられるものなんですか。予算というのはあるんか尋ねました。","respondent":"堀越生涯学習課長","answer":"お話があれば調整して、中身については検討したいと思っています。今回、古田さんのお話もあったということで、ほかの種目についても検討していきたいと考えています。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"４２０万円かけなくても、多分、オリンピアンズというんですか、その方を呼べる可能性もあると思うんですね。そういうのは都がどういう動きになるかわかりませんけれども、また別にぜひこれは拡大してやっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"川西委員","kind":"意見","question":"今のご答弁の中で、ほとんどが少年野球チームのグループ参加が多かったのか、個人参加が何割ぐらいあったのか。それからもう１つは今、地域的な問題にちらっと触れましたけれども、品川全区域からすると、参加の分布はどのようになっているか聞いておきたいとの意見を述べました。","respondent":"堀越生涯学習課長","answer":"１００人という限られた数字でございましたので、グループ参加という形でなく、完全に個人でご応募をしていただく形をとっています。全区域の中でどのような形で割り振られているかというような数値も出しておりませんので、個人の応募で、個人でご参加いただいたということです。","id":"exchange-045"}]},{"id":"topic-05","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"川西委員","kind":"質問","question":"もう１つあるのは、ほかの議員にあげるとか、もったいないですよね。ちょっと伺っておきます。","respondent":"和氣小中一貫教育担当課長","answer":"６個人１２団体はこの趣旨に自治体としては賛成できないけれども、個人で賛成している方。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"構成・レイアウトは正副に一任しているので、意見だけなんですけど、視察の行程表があるといいかなと思ったんです。表紙に日にちだけあるんですけれども、下のほうになるんでしょうか、わからないですけど、行程表があったらよかったなと思ったので、それだけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4658#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":43547,"voices":138}},{"id":"h21-20090120-5","meetingId":"h21-cm01","date":"2009年1月20日","dateIso":"2009-01-20","committee":"総務委員会","time":"午後１時０３分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"を行います。 初めに、１の協働事業提案制度","agenda":"を行います。 初めに、１の協働事業提案制度","exchanges":[{"speaker":"南委員","kind":"提案","question":"今伺っていたんですけれども、ちょっとどんな状況かというのを知りたいと思っているんですけれども、たしか１年間の協働ということですよね。ですから、そういうプログラムを提案するということなので、その辺についてはどういうふうに考えているのかというのを教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"１年間の継続事業ということで、その後の支援はどうするかです。発達障害児者の支援につきましても、そういった支援は継続してやっていけるものだというふうに考えております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それを教えていただきたいのと、私がちょっと聞いたところによると、やはり活動拠点というのがなかなか難しいというのがあるんですよね。例えば１つの講演をするとか、どの程度どういうふうに考え方として示されているのかをちょっと伺いたいのと、全然読んでいない。","respondent":"久保田行財政改革担当課長","answer":"例えば活動拠点とか経済的な支援といったところの話題が中心で議論が進むのかなというふうに私どもいろいろ考えていたんですけれども、今回まで６回。協働に関係する部署で庁内の検討会を開いておりまして、その中で出てきた事業についていろいろ検討させていただいて、規模的。","id":"exchange-002"},{"speaker":"南委員","kind":"提案","question":"出てきたのがこの３つだけど、あるいはこのテーマがあまりあれだったのかなという調査も含めてどんなふうに検討されたのかをちょっと伺いたいのと。公がやるとお金がかかるから、その辺についての考え方というか、そういうものについてもどうなのかを伺っておきたいと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"決して経済支援とか活動拠点は要らないよというところではないんですけれども、区に必要な部分は支援をしてもらいたいというところもありますが。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"何かお役に立ちたいというそういう自発的な、積極的な姿勢に対しては本当に前向きで受けとめていきたいというふうに思っているんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"だから、改めて確認したいのが１年間活動した後、この事業をどう評価していくかということ。おかしくなるので、その２つ、評価制度の点とこの位置づけについての確認をもう少しお願いします。","respondent":"久保田行財政改革担当課長","answer":"継続して違う形で、所管との直接の関係での事業というところもありますし、そういったところはお互いに確認をしながらやっていきたいです。こういう制度を使ったり、協働の方向性というものをお互いに探していきたいなというふうに考えているところです。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"提案","question":"そうすると、例えば区民提案事業の中で、成年後見という制度、それから子育てのテーマということで普遍的なものがあるでしょう。もっと広い意味で言えば、継続をどうするかというのも当然裏腹なものとしてあるわけだから、そういうところについてはもう少しお考えをお願いしますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"今後は例えばこの制度とは違うところで所管課と団体とで直接協働というところで事業を進めていければなというふうには考えているところもありますの…どの事業をやめるのかというところの判断はしていかなければいけないというふうに思っております。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"これを逆に行政側がしたくなってくることも考えられる。だから、最後、そのことについての考え方をお聞きしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"引き続き継続して協働でやっていかなければならない事業もありますし。継続的にこちらの事業をやっていただいてもそれは構いませんので、事業について進めていきたいというふうに思っております。","id":"exchange-007"},{"speaker":"金野委員","kind":"提案","question":"区民提案の事業としてこれだけのものが出てきて４月１日から始まっていくので、アピールもあるでしょうし、どういったかたちで１年間流れていくのか。そんなことが具体的に、たった１年ですからもうそういった日程的なものがもしあるのであれば説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"ご提案いただきまして公園ということで１年間継続してやっていくというところで、何カ所かでやるというふうに聞いております。ですから、子育てメッセにつきましては、１回のイベントというふうにご提案になっております。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"そうした姿勢でやっていただきたいなと思います。お願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問・要望","question":"協働事業をこのようにして進めていくわけですから、それをここで発揮をされるということでお願いをするということになるわけです。ほかの人は何やっているのというお話があったわけですから、新たな、そういうことでご努力をいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"林委員","kind":"質問・要望","question":"協働という字、財政的には一方的に区側の負担ということが見込まれるわけで、この事業についての財政的な区側の考え方の裏づけを教えていただきたい。３、３は８名なんだけど、８名の上限があるけど今７名というふうに受けとめるのかどうか。","respondent":"久保田行財政改革担当課長","answer":"ちょっと説明が足りませんでした。ちょっと説明が不足しまして申しわけございませんでした。","id":"exchange-011"},{"speaker":"林委員","kind":"質問","question":"３年間はスパンを計算した中でやってもらって、次の年のスタートをどうするかというのはそこの時点でやるというようなこともある。これは区民の人の意欲をこういう形でやっていきますよということですから、それは意欲はもう買っている。","respondent":"久保田行財政改革担当課長","answer":"協働して事業を提案して、今回提案説明までしなきゃいけないといったところで、大分事業を進めていくのは大変なんだなというのがあったと思います。所管課のほうも確認しながら、そういう相談に乗っていい方向で１年間活動していきたいなというふうに考えております。","id":"exchange-012"}]},{"id":"topic-02","title":"２品川区長期基本計画の策定状況","agenda":"２品川区長期基本計画の策定状況","exchanges":[{"speaker":"南委員","kind":"質問","question":"改めて伺いたいのと、できたらこういうふうに品川区としては今後１０年間のスパンで区政運営していきますよという説明をする。それが目的でやっていくべきだというふうに思っているんですけれども、その辺についてはどうなんか尋ねました。","respondent":"福島長期計画担当課長","answer":"今のところ考えていますのは１万５,０００冊印刷しまして、それをさまざまな形で配布し、周知したいというふうに考えてあります。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"新たに計画が具体化されるわけですから、そういうことを本当に検討をしていただきたいということを強くお願いをしておきたいと思いました。どうなのかなと伺って。","respondent":"福島長期計画担当課長","answer":"今回につきましては、まだ検討段階ではありますけれども、都市像をわかりやすくどんな形で今後区が１０年間進めていくのか。概要版につきましても、できるだけ区民の方へこのメッセージが伝わるように考えていきたいと思ってあります。","id":"exchange-014"},{"speaker":"林委員","kind":"意見","question":"この３月から４月、いろいろな手配というと言葉がいけないかもわからないけれども、いろいろなところへの手はずをきちんと何度も何度もやってほしい。答えはもうやりますと顔に書いてあるというふうに判断しますから、それだけお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"続きまして３番目に、第１８回品川区世論調査","agenda":"続きまして３番目に、第１８回品川区世論調査","exchanges":[{"speaker":"南委員","kind":"確認","question":"それから、クロス集計の結果でそういうことが言えるという上でそういう説明だったのかを確認しておきたいと思うんですけれども、やはり私たち。きのうも違う場面でこの問題を質問したら、改めてこの時期にここのところに関してもう一度その辺の見解を伺っておきたいと思いました。","respondent":"中川原広報広聴課長","answer":"広報としましては、必要な方に必要な情報を届けるのが非常に大事な仕事だと考えています。この前も説明しておりますが、スピードと予算のいろいろなことを考えあわせて、最善の方法が今は新聞折り込みを中心としつつ。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろ工夫をするということが同時に求められているというふうに思いますので、ああ、区民といろいろな話をしてくる中で感じている部分なんです。したがって、そのことを世論調査のところですからそれ以上のことは申しませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-04","title":"続きまして４の武蔵小山駅前広場シェルター新築工事請負契約","agenda":"続きまして４の武蔵小山駅前広場シェルター新築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そして、今回、制限付き一般競争入札で第１緑道、第２緑道、業者が３者ということで全く同じなんですが、ほかは入ってこられなかったのか。その辺についても説明を求めました。","respondent":"阿部経理課長","answer":"第１と第２と業者の件ですけれども、これは別々に公告いたしまして、ＪＶの募集を行いました。結果としては同じ業者になったです。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ、実際線路上づたいですか、そこをずっと通っていけるような形になるのか。それとも通過性があるのかどうか、その辺お聞きします。","respondent":"阿部経理課長","answer":"駐輪場のほうは詳しくは存じませんけれども、ここにあります緑道ですけれども、ここは道路との交差部、これは車どめをやっておりまして、災害時にはその車どめを抜けば通れるというふうになっていると聞いております。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"東急とか自転車の置き場とかありますが、その辺はやはり迂回しないと、または避けて通らないと通れない。つまり、通過性が西小山から武蔵小山までは避難路としては途中はちょっとずれるよという避難路になるんか尋ねました。","respondent":"阿部経理課長","answer":"先ほど申しましたようにそこまでは承知はしておりません。今回の緑道については承知していますけれども、その他の件は承知しておりません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1810#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":36477,"voices":68}},{"id":"h21-20090121-14","meetingId":"h21-cm01","date":"2009年1月21日","dateIso":"2009-01-21","committee":"行財政改革特別委員会","time":"午後１時０４分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"公有財産の有効活用に関すること","agenda":"公有財産の有効活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"パブリックコメントの結果についてなんですが、前回の委員会で何件ぐらいを目標にしているんですかと質問をさせていただいたんですが、なるべく多く集めたいということでありましたけれども、今回の件数の評価といいますか、どのように考えているのかをまずお伺いします。","respondent":"久保田行財政改革担当課長","answer":"私、担当としましては、５１件といえども関心を皆さんお持ちなのかなと考えています。そういう意味では広く皆様にお伝わりして、関心をお持ちいただいているのではないかと考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご要望に沿うことは困難と書いているんですけれども、したがいまして要望には沿えないというのは、一方通行としか思えないんです。ここら辺のところですごく疑問を感じてしまったんですが、今の私の意見に関していかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"これにつきましては、基本的には文化施設と多目的広場に整備していきますということに対してご意見をいただいていると考えております。区で主体的に検討して利用計画案を策定してきたというところもありますので、考え方ということでお示しさせていただいているです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"非常に区民の皆さんが思いを込められたような意見が、とってみたら、こんなに出てきたんだというところだと思うんです。再三求めているんですけれども、パブリックコメントだけにとどまらない活用検討をする仕組みづくりということに関して考えをお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"地元の要望とか、そうした中で地域にもご説明させていただいて、いろいろと検討した中でこういう利用計画案をつくらせていただいたです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"パブリックコメントもやったし、その前にも意見を伺っていたという話なんですが、これは何度もやってもいいと僕は思うんです。そもそも区政協力委員会というのはどういうものなのかも含めて、具体的にわかりやすいように、改めて経緯をお話ししていただけると助かるんですが。","respondent":"久保田行財政改革担当課長","answer":"そうした中で意見を取りまとめる際には、そういった意味では、地域の総合的なご意見をちょうだいしているのではないかと考えています。窓口に来て、そういうお問い合わせもあったと聞いておりますので、そういう形で幅広く意見を聞いているです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"町会から意見を伺う、区政協力委員会の中でもいろいろ意見も伺ったということなんですが、建物がなくなるわけですから。ですから、この荏原の地区の学校をどうするかという説明会なり、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"防災に関係いたしましては、しかるべき時期が来れば、そういう組織を通じて説明をしていきたいと考えているところです。学校避難所がなくなりますけれども、防災課でも協議を進めておりますので、そういった説明もあわせてご説明はできるのかなと考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"今の説明を伺っても、そういった防災機能ということも大事な学校の１つの大きな機能なわけですから、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"そこには防災の主な方々が、各地域の防災の方々が集まって結成されている組織ですので、そういった方を通じてご説明します。そうした中で、また個別にも防災課のほうでご説明をする機会がありますので、そういったところを通じまして説明はしていきたいと考えております。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"２点ほど伺いたいと思います。バレーボールにしろ、この辺との今までの対応ですとか、展開の辺を伺えたらと思います。","respondent":"久保田行財政改革担当課長","answer":"十分対応はできるのではないかといったところは計算していますけれども、ご要望に沿うことも難しいかなというところはありますけれども、その辺は今。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"提案","question":"その中で政務調査会あてにいただいたものに対して、苦言もありますし、ご提案もあると、すべてに対して、礼儀の一貫として、まずお礼状を出す。まず儀礼的なものも姿勢として必要ではないかなと、それがちょっと気になったので、もう一度確認させてくださいとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"個別の返答というところでは、先ほど私がご説明して、ちょっと個別にはやっていないと認識しております。こういうご回答をいただければ、私どももできるだけこういうご意見をいただいたら、速やかに回答をしていきたいとは考えているところです。","id":"exchange-008"},{"speaker":"阿部委員","kind":"提案","question":"今回、何かご提案いただいたものを庁内で共有するような仕組みなり、共有ができるようになっているかどうかということをお伺いできればと思います。ここでせっかく一覧表もつくられているわけですから、５０通ぐらいだったら、そんなに手間暇かかるものではないかなと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"今後また何かいろいろ検討する中では参考になる意見もあるかと思いますので、そうしたところでは、意見として伺っていきたいなと考えています。ケース・バイ・ケースの対応でできるかどうかということもあると思うんですけれども、そういった状況でご理解いただければです。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"３００件もそんなに大変かなと、私たちはいろいろ大量の郵送になれているものですから、３００件ってそんなに多いかなと思いますが、最初の件だけ。そういうとまった関係といったらいいんですかね、知りたいという気持ちを持ってパブリックコメントを実施してほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"今度変えていきますといったようなところは、直接の担当ではございませんので、お答えすることが難しいかです。ただ、委員からそういうご意見があったというところは所管課には伝えていきたいと考えています。","id":"exchange-010"},{"speaker":"須藤委員","kind":"提案","question":"これが私は１つのルールだろうと思うんだけれども、そこで改めて聞くけれども、区側は文化とはどういうふうに考えているんでしょうか。文化施設の文化とは、どういうふうに考えているんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"生活の中から生まれてまいりました有形無形の活動の英知というんでしょうか、皆さんが活動してきた中で生まれてきたものというところのものだと考えておりますけれども、ちょっと説明が。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"どういう根拠があって、この狭い一画だけれども、そういったスペースも考えられるよというようなこともとっていってもらえないのかなと。できるだけパブリックコメントで来たものを取り入れていけるような方向性というのはつくっていけないんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"これは私どもが地域に説明に入った際に、道路は拡幅していかなきゃだめだよというような、本当に地域の実情に応じたような意見もいただいております。いただいた意見を見た中には、そうした中で、ちょっとこういう回答になったというところでご理解いただければと思います。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問・要望","question":"それがまたパブリックコメントが来たからもう一回元に戻して、みんなの意見を聞きなさいよという話だと、なかなか形ができてこない。やはり区民の方々の協働という気持ちをこれから育てていってもらう中に生かしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"今、パブリックコメントを求める側のいろいろな努力というか、そういったところは今回に限らずいろいろなところで計画を持ってもほしいと思いますし。本当にこれが全体的な区民の要望であるかということは少し考えたほうがいいんじゃないかと思うんですけれども、まず、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、室内コンサートとかのほうも対応できるような多目的ホールということで特色を持たせていきたいなと考えているところです。あくまでも多目的な地域の方のご利用というところを基本として考えているところです。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"ちなみに、荏原文化センターのホールの稼働率はどのくらいになっているんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"申しわけございません。何％ということはお答えできないんですけれども、そういうところですと、６割とか７割といったところが一般的だと聞いております。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問・要望","question":"私が担当課に伺ったところ、９９％と１００％程度使われているというところでは、そこについては大変皆さん利用勝手がいいと。パブリックコメントを求めた後に、何かできるんじゃないかという検討の会はきちんと行われているのかどうか、その２点についてお伺いします。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、今のこの段階でこれができるとか、できないとかというのは、ちょっとお答えが難しいのかなと。いろいろ正式な競技ですと、そうした中で、本当にそういうものが可能なのかどうかというところを検証しながら進めていきたいと考えております。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"区民の方からも伺ったところ、そういうことも踏まえてつくってほしいということと、ここに荏原文化センターの料理講習室が５割を切っているんです。一般質問の答弁でも区長は、本当の区民のニーズを生かせるところで見直しができるのであれば、ぜひしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"１つだけお聞きしたいんだけれども、計画案の段階で説明すべきかどうかと、これは地域に説明しますよというお話でしたよね。どうして案の段階で示すことに問題があるというか、躊躇されるのかどうか、そこをお聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"先ほどの私からの説明ですけれども、それでいいのかどうかというところがございまして、そういうふうなお話をさせていただいたです。そういった意味では、案が決まった段階で、できるだけ区民の方に安定した形で運用していただきたいと思いまして判断させていただいたです。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"１０月にいただいた資料の中で、これはどういう使い方をするかという問題とあわせて、こういうことが必要なのではないですか。今の再度いただいた課長の答弁では、なかなかそこは区民に示さないままパブリックコメントをいただいたということになるんじゃないか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"ただ、近くの学校に振り分けるのかということはきちんと利用計画が決まった段階でご説明させていただきたいということをお話ししております。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"別にそういう会を開いたわけじゃないということですから、当然、示されていないわけですよね。そこはやっぱりしっかり考えるべきではないか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"地域で必要であれば、個別にご説明というところは考えていますけれども、まずは町会連合会にご説明させていただいた中で。私どもが基本的に考えているのは、その前から、早くから地域の方にも防災協議会等を通じて説明をしていきたいと考えているところです。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、そういう声が生まれてくるというのは、そういう手続がきっちりなされていない結果なんだと思うんです。そこをぜひ強化をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"例えば広報紙、最近の世論調査が出ていましたけれども、ほとんどの方がそういう形で広報を見ると。回答を寄せなかった人の区の考え方というんでしょうか、どのように分析をして、それで進めていくのかというところを１点お伺いしたいなと思います。","respondent":"久保田行財政改革担当課長","answer":"回答をくれなかった方をどう分析するかです。回答を出す、私も説明や意見交換なんかをした際にもありますけれども、そういう印象を受け取っているところです。","id":"exchange-022"},{"speaker":"浅野委員","kind":"質問","question":"声なき声というものもしっかりと区としてもこれからも吸い取っていくような、そういう努力をしてほしいと求めました。その上でお伺いしたいんですけれども、こういうことは考えていなかったというような回答はこの中に含まれているのかどうかをお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"さまざまな方からさまざまな意見が寄せられるというところを考えておりますので、想定をしなかったという意見はないと考えているところですけれども、いろいろな意見があるんだなというふうに印象を持っております。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問・要望","question":"行財政改革特別委員会では発表というんでしょうか、お知らせいただく機会があるのかどうか、その点だけ確認でお願いします。","respondent":"久保田行財政改革担当課長","answer":"この計画案につきましては、この計画案ができましたらば、公表の前に、当然ながら行財政改革特別委員会に報告はさせていただきたいと考えております。","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"それから荏原文化センターなんかの場合には、５００人ですから、講演、式典かなと。感覚的には全然違った見方から２つ、もしくは３つなのかな、その２点をちょっとご質問させてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、ここの荏原のところにももう１つ１,０００人規模のものが必要かどうかというところの検討はさせていただいてきております。所管課といろいろ検討している中では、四重奏というんでしょうか、何かそういうフルオーケストラではないですけれども。","id":"exchange-025"},{"speaker":"原委員","kind":"意見","question":"企画的な考えはわかるんですけれども、公有地の平塚小学校としての活用となると、やっぱり荏原地区の核だと思うんです。商店街からつながる問題等が、この２点が非常に大きく考えられるんじゃないのかなというところで、もう一度お考えをお聞かせほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"今、委員がおっしゃったように、私ども、こちら、平塚小学校については、荏原西地区の核になる位置にあるのかなと認識をしております。補助２６号線のところにあるということで、例えば多目的ホール、多目的ホールなども整備をしていきたいと考えておるところです。","id":"exchange-026"},{"speaker":"原委員","kind":"質問・要望","question":"もっと少なく２００か、その辺のところでお考えがあったらば、お聞かせほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"今後、基本設計とか実施設計をやっていく中で、そういう専門家の意見等も聞きながら検討はしていきたいと考えております。５００人というところ、荏原文化センターがありますけれども、それよりは小さくなるのかなというところでは考えているです。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"もう一度しつこく要望として申し上げておきますけれども、品川区はサービスがいいよねという、要するにほかの区役所に比べると非常にいいんです。その辺をもう一度、すいませんけれども、よりよいサービス向上のために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592995?Template=document&Id=5854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":35053,"voices":60}},{"id":"h21-20090122-16","meetingId":"h21-cm01","date":"2009年1月22日","dateIso":"2009-01-22","committee":"街づくり特別委員会","time":"午後１時０２分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"安全・安心のまちづくりに関することとして、「滝王子通りの避難道路機能強化」","agenda":"安全・安心のまちづくりに関することとして、「滝王子通りの避難道路機能強化」","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういうアンケートの意向がどういうふうになっているのか比較したいんですけれども、それを教えてほしいと求めました。このアンケートをとられて、区として、どういうふうにこのアンケート結果を評価したかというのをちょっと聞きたいと思います。","respondent":"吉川住環境整備担当課長","answer":"「回答数１１６」と書いてありますから、先ほど説明の中で申し上げましたとおり、こちらとしてはお願いしていく考えです。十分この結果を踏まえてお話しをして、理解していただくよう努めてまいりたいと、こういうふうに考えています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"２２.４％の回答をいただいて、そういう個別の質問については、わかるように出されましたよね。そこをちょっと教えていただきたいのと、さっき質問したんですけれども、教えてほしいと求めました。","respondent":"吉川住環境整備担当課長","answer":"事業開始前からかなり、住民説明会を何回か開催して、地域の中に入っていきたいなと考えています。これは地域の中に入って、こういった意向がある方については、具体的な話を事業開始とともに進めていく予定です。","id":"exchange-002"},{"speaker":"稲川委員","kind":"質問","question":"どういう形のアンケート調査だったかというのを教えてください。その辺の理由というか、もうちょっとわかりやすいアンケートにしたほうがいいのではないかと思うんですけれども、その辺、説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"初めに、地区現況調査についてですが、これは私どもで委託しましたコンサルタントが現況調査を実施しております。番号に丸をつけてもらうようなアンケートを実施したんですが、分母の若干のずれが生じているというふうにご理解いただければと思います。","id":"exchange-003"},{"speaker":"稲川委員","kind":"質問","question":"若干のずれと言っても、例えば１７ページで、権利者の方で、回答数４０というのは、若干のずれなんですか。直接質問形式でやったほうが、その辺、どうお考えか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"回答数４０ということで、問１４で建替えの予定はありますかと聞いておりまして、「予定がある」と回答した方だけに対する質問ですので。２回いらっしゃらなかった方は、多くの回答をいただきたいという努力は、しています。","id":"exchange-004"},{"speaker":"稲川委員","kind":"意見","question":"「訪問配布」としか書いていなかったので、それはすみませんでした。２２.４％が高いか低いかは別にしても、やはりもうちょっと高いほうが、今後もしっかりとしたアンケートをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"そうすると、もちろん国や、それから都からの補助金というものが一応あると思うんですが、その辺の割合、率を教えてほしいのが１点。建替えの助成が出るということで、こちらのほうに詳細が書かれておりますけれども、この建替えの助成の率というのを説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"個別にお話を事業開始とともにしていく予定なんですが、お答えするのはかなり難しいと思いますが、真剣に取り組むつもりです。４３％の不燃化率でございまして、一概にお答えするのは難しいんですが、おおむね建物の建築費に対して７％から１０％超ぐらいになるかと。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"あそこの通りには、もう既にセットバックをして、集合住宅を建てられていますよね。その辺の事業者には、やはりこのような助成金というのは既に出ていると考えてよろしいんか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"両方つく事業でございまして、これは事業がまだスタートしておりませんので、まだ助成金は出ておりません。東京都と国の認可を取って、１０月のスタートをめどに今、手続きを進めているです。","id":"exchange-007"},{"speaker":"山内委員","kind":"確認","question":"そのマンションの施主は、要は工事費を１００％自分で払っているということで、その助成は一切受けていないということでいいですか。確認ですけれども、それでよろしいか尋ねました。","respondent":"吉川住環境整備担当課長、谷田部まちづくり事業部次長","answer":"現在、不燃化建築物をつくられても、助成金は出ておりません。 私のほうから補足します。この事業がスタートすれば、それを私どもが道路用地として買収させていただいて、道路として整備をするというようなことを考えてあります。","id":"exchange-008"},{"speaker":"山内委員","kind":"質問","question":"その辺をわかっておきながら質問させていただいたんですけれども、そういう意味でも、早急な道路拡幅というのは重要ではないかなと。１日も早く事業に着手するということが、そういうふうなことで、お願いできればというふうに思います。","respondent":"岩田まちづくり事業部長","answer":"果たして４０年も、５０年も、地域の方々からそういう意見が出てくる可能性はあります。おおむね５０年ぐらいという都市計画制度の中で、将来はこういうきちんとした道路が担保されますよということで始めたいと、こういうことです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"滝王子通りと沿道３０ｍをおおいかぶすように防災街区整備方針に沿って、そういう定めが進んだというふうにお話を伺っているんですけれども、その計画と目的を教えていただきたいんです。","respondent":"吉川住環境整備担当課長","answer":"東京都市計画防災街区整備方針について、どういう事業をやるためにとか、そういう目的等はございません。あくまでも、現在の防災都市づくり推進計画の整備地域との整合性を図ったという見直しです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"この滝王子通りと沿道３０ｍをおおいかぶせたというところと、何が、どのように変わるのか。その説明では、正直、よくわからないので、教えていただけますか。","respondent":"吉川住環境整備担当課長","answer":"国の制度がありますけれども、新たに何か事業を開始するときに採択されやすいとか、そういう意味合いはあります。事業を実施するということで、これを導入するという予定があったので、実際は。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つ、このアンケートをとるときも、９ブロックごとに分けてアンケートをとられていますよね。考え方を教えていただけますか。","respondent":"吉川住環境整備担当課長、岩田まちづくり事業部長","answer":"ただいま例に挙げられたような、大崎のような再開発というのは全く想定しておりません。それと、どういう意味があったのかというところでは、滝王子通りを防災公共施設に正確に位置づけるようになったということがあります。 奥行きプラス１０ｍの方が、今度は、耐火建築物でないと建てられなくなるという規制がかかるということです。その違いだけです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、制限としては３０ｍではあるんだけれども、どんなふうにお考えなのかということ。説明をしたり、そういう事業説明会をやっていく必要があるのではないかなと思うんですけれども、いかがか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"さらにもっと広い防災生活圏という考え方があるんですが、まちづくり検討会みたいなもの、検討していただくというようなことを考えています。そういう地区計画の例はありますというような回答も、まちづくりを進めていきたいと、こういうふうに考えてあります。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"こういう幅広いことに対して、地域に対して事業説明会、これをしてからでないといけないのではないのかなと思うんです。そういう形にどうしてもなってしまうでしょうから、幅広い方々にやるべきではないかと思うんですけれども、どう考えていますか。","respondent":"岩田まちづくり事業部長","answer":"こういった方に事業の内容を説明して、住民参加が言われているこの中では、当然のことだろうと思います。いろいろ、地域の町会長の方々などと相談しながら、そういうＰＲや意見を聞く方法は考えてまいりたいと思います。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"２ページのところ、３番目の拡幅整備でやるということは、もう既に測量が終わっているという理解でよろしいんか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"現況調査の中で、測量も実施しております。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"住んでいらっしゃる方のどれだけが住めなくなってしまうかというような状況によっても、この道路をどうしていくのかという理由になると思うんです。もう既に測量しているというのであれば、そこはきちんと私たちに示してほしいと求めましたが、それはいかがか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"やはり個人情報ですので、こうした場で表に出すというのは難しい面があるということで、ご理解いただければと思います。","id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"商店街ですから、商店街の考え方も変えていかないと、多分、この道路はうまくいかない。それが、個別の問題もありながら、全体で、広域の問題ということになっていくので、そこの持っていき方を今後どうされるのか、お聞きしますとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"この地域で成り立つかどうかというものの考え方のほうが大事だろうと思うので、逆に、地域の防災まちづくりの話し合いの中でやっていく。常に、私どもの事業部はそういう考えで、仕事を進めております。","id":"exchange-017"},{"speaker":"西本委員","kind":"提案","question":"アンケート結果での３ページのところに書いてありますように、点線のところはまだ未整備ですよという意味合いでよろしいんですか。滝王子通りの整備と、補助３１号線の絡みというのを、今後、どういう形で進めていかれるのかをお聞きしたいんですとの意見を述べました。","respondent":"梶都市計画課長","answer":"ただいまのご質問の中で、補助３１号線が出てまいりましたので、補助３１号線の現在の内容についてご説明します。ですから、事業化されていない路線という形で、今後、まだ、これからの路線という話です。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"決められてしまえば、その補助３１号線は、整備することが、順番としてあるわけですか。両方の避難道路という形でこの先やっていくという順番はあるんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"振り替えという考えではなくて、今、そう指定しております。それから、補助３１号線については、ここは防災面については期待をしておりません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/504318?Template=document&Id=6380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":20324,"voices":48}},{"id":"h21-20090227-3","meetingId":"h21-c-budget","date":"2009年2月27日","dateIso":"2009-02-27","committee":"予算特別委員会","time":"午後３時５７分～午後４時０４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=908#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":2065,"voices":18}},{"id":"h21-20090302-6","meetingId":"h21-cm03","date":"2009年3月2日","dateIso":"2009-03-02","committee":"区民委員会","time":"午前１０時０２分～午後０時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"第２３号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第２３号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"もう１つは、どんな行動計画がそういう企業から上がると想定されているのか、具体例をお伺いしたいなと思います。そもそも対象となる企業、事業者数がどれぐらいあって、条例改正の効果というのはどれほどを見込んでいるかということをお伺いします。","respondent":"金子産業振興課長","answer":"先ほどもご説明申し上げたとおり、国を挙げての取り組みですので、区としても全体として取り組んでいこうというふうにしています。平成２３年からは努力義務化から完全な義務化に変わりますので、こういうところには取り組みは進めていきたいと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"ワークライフバランスマニュアルの策定状況と、それをいただけるのかどうか、あるいは、もし簡単にかいつまんで中身がお話しできるのであれば、今、ちょっと紹介していただきたい。","respondent":"金子産業振興課長","answer":"取り組みの内容というのはどうしても企業の特色といいますか、変わってくるということで、マニュアル自体はかなり一般的な内容になっています。その方針もきちっと、それから取り組んでいく場合には、そういった取り組みが重要であるというようなことが骨子です。","id":"exchange-002"},{"speaker":"若林委員","kind":"意見","question":"企業はどういうところへ使おうと、ワークライフバランスのためにこの１,０００万円を使えるのか、そこら辺をちょっとの意見を述べました。","respondent":"金子産業振興課長","answer":"今回のこの支援資金は、あるいはこれから取り組む企業に対するインセンティブとして設置しているもので、そのいわゆる融資の資金の使途というのは。","id":"exchange-003"},{"speaker":"若林委員","kind":"質問","question":"その使途についてはとくにチェックはしないと、お貸しして、ちゃんと返してくれればいいということですよね。特に人材確保とか、仕事と家庭の、要するに働きやすさにつながっているかどうかというチェックというのはどうなんか尋ねました。","respondent":"金子産業振興課長","answer":"支援資金ですので、取り組んでおられる、取り組む計画があるというところで要件としてやっていくことを考えております。取り組む計画を出して実行しないような場合には、それは満たしているわけですけれども、指導はしていきたいと考えております。","id":"exchange-004"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"今のお話だと、指導していくということなんですけれども、もうちょっとしっかりした担保というものが必要じゃないのかなと思うんです。もうちょっとそこの担保といいますか、監視といったら何なんですけれども、考えがないものかどうかをお聞かせいただきたいんですけれども。","respondent":"金子産業振興課長","answer":"あくまでも現在取り組んでいる、計画も含めて、取り組みがもっと多くの企業に広がるようにということでこの資金を設置しているものです。ですけれども、もしそういうようなお話の企業がある場合には、かなり強力なプッシュをして指導を強めていこうと考えているところです。","id":"exchange-005"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"その中身を、実際にそうなっていかないと、制度をつくる側の期待というものもありますので、ぜひその辺のところは制度の趣旨に沿った成果が上がるように運営してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"第２４号議案 品川区立工場アパート条例の一部を改正する条例","agenda":"第２４号議案 品川区立工場アパート条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年と去年とその前の年ぐらいに、工場８ユニットと住居８戸ということだったんですが、２年前から今年までの埋まり状況ということを教えていただければと思うんですけれども。","respondent":"金子産業振興課長","answer":"平成１９年度に改修して、これも議会でご説明申し上げているとおり、工場と住宅が２部屋ずつあいている状態というのがずっと続いていたわけです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"意見","question":"今の説明だと、すごくあきが埋まらないというようなところがいまいちよく伝わってこないというか、わりと埋まっている状況なのかなと思うので、今回の改正をしなくちゃいけないという必然性が逆にわからなくなってしまったんですが、そこら辺に関してのお考えをとの意見を述べました。","respondent":"金子産業振興課長","answer":"正確を期して説明したので非常にわかりにくくなっていたと思いますが、少なくとも平成２０年度に入りましてから、公募をかけていたところなんです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"それに合わせて目的の条例を変えるというのは、ちょっと順番としてはおかしいのかなと思ってしまったんですけれども、いかがか尋ねました。","respondent":"金子産業振興課長","answer":"私どもとしましては条例を改正した上で本契約をしようと思っていますので、条例が仮に、万が一否決された場合には本契約しないわけですから、それは手順が間違っているとは思っていないところです。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"あいている状況がしばらくあって、課題になったのが、議会からもいろいろと課題が出て、今回の改正ということで、受け皿が増えたり、改正についてはいいなと思うんですけれども、この部屋の面積をもう一度改めて教えていただきたいんです。","respondent":"金子産業振興課長","answer":"それから５４m2が３工場、それから４４.５５m2が２工場、この３種類となりまして８工場です。それから旧住宅、今回の事務室の分ですけれども、５０.７０m2が７戸、それから１つが２６.８５m2、約半分ですが１戸ということの計８戸です。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"細かいことを聞いちゃうんですけれども、シャワー１回１００円ということなんですけれども、この利用料をどのようにして振り込んでもらうというか、回収するのかを説明を求めました。","respondent":"金子産業振興課長","answer":"シャワー１回１００円ですけれども、これは住んでいる方等々で、今、組合じゃないですけれども、協議会みたいなものをつくっていただいておりますけれども、そこでプールしておいていただいて、月１回、私どもで調定をあげて収入しようと考えているところです。","id":"exchange-011"},{"speaker":"若林委員","kind":"確認","question":"１点だけ。どちらが正確なのかをお聞きしたいのとともに、こういうものづくり関係なんですかね、こういう理解でよろしいのかどうかを確認させてください。","respondent":"金子産業振興課長","answer":"製造設備を持たない、具体的に入るというところの話にはならなかったものですから、ちょっと微妙な言い方になってしまって失礼いたしました。情報通信業、特に品川区内は増えているということでもありますので、こういうふうに業種の枠を拡大したところです。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"意見","question":"それが今度は、また状況が変わってきた場合に、今度は区としてはどういう対応が出てくるのかということがよくわからないんですけれども。そこら辺のお考えというか、一応、聞いておきたいなと思いますけれどもとの意見を述べました。","respondent":"金子産業振興課長","answer":"委員がご指摘のとおり、品川区としましては、今現在で製造業、ものづくりについて全く出ていっていただこうという考えは持っていません。で、このメニューに限らず、さまざまものづくりの支援に関してはメニューを豊富にして対応していければなと考えています。","id":"exchange-013"}]},{"id":"topic-03","title":"第２５号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２５号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"平成１８年度ですか。先ほど激変緩和措置が終わるという話もありましたけれども、それぞれどのように変化していったのかということを教えてほしいと求めました。","respondent":"本城国保年金課長","answer":"今、何点かご質問いただきましたが、先に短期証と資格証明書の世帯からご説明いたします。それから保険料の推移ですが、保険料の推移につきましては所得割と均等割、それぞれ説明します。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"１人世帯の方で、年収が２００万円のひとり暮らしの方の国保の保険料は、平成１７年から来年度予定の平成２１年度までの保険料がどのように変化しているかということをお伺いします。","respondent":"本城国保年金課長","answer":"２００万円の年金所得者、１人世帯ということでご報告します。平成１９年度５万７,０７９円、平成２０年度７万３,３７５円で、平成２１年度が７万４,３３０円という状況です。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"平成１７年度で６万１,８００円だったのが、平成２１年度で１７万９,５６５円という、３倍近く上がるという負担なんです。この負担増を２００万円、どのように生活に影響を与えるとお感じになっているのか、お考えをお聞かせほしいと求めました。","respondent":"本城国保年金課長","answer":"資料の中でもご説明させていただいたところですが、１人当たりの保険料に見ますと、少しずつ上がっているところです。これも途中で少しご説明させていただきましたが、この間、経過措置等を実施してきて今の形になったところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはもうなくなるわけですから、国が負担していた負担というのはどういうふうに変化してきたのかということもご説明いただきたいのと、そういった子どものいる世帯というのはあるんか尋ねました。","respondent":"本城国保年金課長","answer":"３４％の前は一時代、４０％の時代があって、３４％になっているところです。国が４０％負担していたところを、東京都がその部分、６％を肩がわりする形で現在のような形になっているところです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"国民皆保険であるわけですから、今までどおり、ここまで保険料が上がって区民生活を圧迫するということがないんじゃないかなと思うんです。そういうお考えがあるかどうかということと、これまで区が出していた補助金ですか、どう変化したのかなということを伺いたいと思います。","respondent":"本城国保年金課長","answer":"６５歳から７４歳までの方の被保険者の数が、国民健康保険などのように高齢者の割合が多いところに対してお金を移転するというような仕組みです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"保険料は上がっているわけですから、京都市等では年間１人当たり１万円、いかがか尋ねました。","respondent":"本城国保年金課長","answer":"国保料の計算につきましては、資料の説明の中でもございましたように、法令の考え方に即して条例に基づいて計算しているというような形です。","id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"資料の１０ページにそれぞれモデル的に保険料の、平成２０年度から平成２１年度にかけての増減、増加率があります。６５歳以上の１人世帯と未満の１人世帯と４人世帯ということで、そこら辺の努力というのか、運用されているのかということをちょっとの意見を述べました。","respondent":"本城国保年金課長","answer":"１点目の特定の年代に影響がということに関してですが、控除分がなくなった分だけ保険料が増えているという、そのような形になっております。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問","question":"保険料の算定、要するに住民税、今もそうですけれども、当初、所得税を算定基準にということで、特別区とかでまだ検討、あれは変えたときにですよね、ちょっとすいません、うろ覚えで、たしか国保もそうだったと思うんですけれども、そこら辺の動きというのは何かご存じか尋ねました。","respondent":"本城国保年金課長","answer":"いわゆる旧ただし書き方式をということで、今、その方向で検討しているです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"わりと所得の高い、例えばこの表で言うと５００万円の方ですとか、あるいは４人世帯の７００万円のところですとかは下がっていたりするわけですよね。きちんと国に国庫負担を上げろと求めて、区としてできることも行い、今回の条例には反対ということを表明したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-04","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"このところ、全国の自治体での同様の請願が採択されるという状況があると思うんですが、その状況を教えてほしいと求めましたのと、あと、税理士会、税務のスペシャリストですけれども、その専門家の税理士会の意見というのはどのような状況になっているんか尋ねました。","respondent":"武内税務課長","answer":"２３区の中については、近隣区の大田区が同じように昨年９月に請願が出ておりますけれども、今回は提出がないです。第５６条、これをそのまま廃止するというのはどうかと言われているのではないかと、私はそういうふうに解釈しております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"８税理士会、質問をしたいんですが、この第５６条があることで不利益の実態が生まれているということが中に書いています。こういうような請願の中にあるような第５６条があることでの不利益、実態、この辺についてはどのようにお考えになるんか尋ねました。","respondent":"武内税務課長","answer":"第５７条ということを趣旨説明させていただきましたけれども、より細かな部分で事業の個人の収入が把握できないという部分も出てくるのかなと。ぜひ個人事業者の方、大変だとは思いますけれども、青色申告の手続で申告をしていただきたいというのが私の考えです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"第５６条の中身の同一生計親族に支払う対価を必要経費として認めないと、制定時は戦前ですか、大分前ですよね。第５６条は私は本当にこれがあることで世界的にも恥ずかしいなというぐらいなんですけれども、いかにも時代おくれだと思いませんか。","respondent":"武内税務課長","answer":"最高裁までこの第５６条の是非については訴訟が起こって争われたという結果、時代おくれかどうかというのはそれぞれ皆さんの立場で考え方は違うのかなと思うんですけれども、時代おくれなのかどうなのかというのは個人的な認識の違いなのかなと思います。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"この第５６条ってそもそも、不正を防ぐために第５６条が必要なんだと、実際そういう不正の実態をつかんでいるんですか。それがあるんだったら、それは必要かもしれない、そういう実態はあるんか尋ねました。","respondent":"武内税務課長","answer":"不正だとか何とかというものは私が直接は見たことはありませんけれども、例えば１つの例として、それは家賃として払うわけです。始めるときは、それが所得が増えてくれば、その事業者の方の所得というのは低く抑えられるということができると物の本には書いてあります。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"それによってさまざまな請願にあるような弊害のほうが大きいわけですから、それはやっぱり私は廃止すべきなんじゃないかなと、そうだと思うんです。ぜひ区としては廃止の方向で考えていただきたいんですけれども、いかがか尋ねました。","respondent":"武内税務課長","answer":"いわゆる第５６条があることによって、不正を防止するとか抑制しているということではないかと考えます。税務行政に携わる中で、この第５６条があるからこそ、そういう租税回避的なことが行われないと私は考えます。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後にします。住民税ですから、きちんと専門機関と連携をとって、強く区には要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"若林委員","kind":"確認","question":"去年９月ですか、確認をして、理事者のお話も聞きながら審査をしたつもりです。１点、これは確認だけですけれども、第５７条の間違いだというのはどこか尋ねました。","respondent":"武内税務課長","answer":"第５６条が配偶者が従事したときには対価の支払いを軽減しないということで、５７条で、そういうことがうたわれています。第５６条じゃなく、第５７条です。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"そういうふうに去年はやられていますので、私としては不採択、意見書を求めることは必要ないかなと考えています。なぜ、その１つ上の違った工夫の仕方をまた考えて出されるのがよかったんじゃないかなと思うんですけれども、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"ますますこういった観点で第５６条廃止ということが必要になっていると思いますので、この第５６条を廃止にして、採択を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-05","title":"の専決処分の報告について（報告第２号）","agenda":"の専決処分の報告について（報告第２号）","exchanges":[{"speaker":"宮崎副委員長","kind":"質問","question":"そういうものの考え方というのはどういうふうになっているのか、例えば５割５割とか、どういうふうに算出したんか尋ねました。","respondent":"中山防災課長","answer":"私どもの今回の例で申しますと、私どもが責任割合６０％、相手方が４０％です。したがいまして、相手方の損害額が１５万５,５７９円でございましたので、その６割ということで、私どもは９万３,３４７円を負担するです。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/911630?Template=document&Id=2542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":33406,"voices":115}},{"id":"h21-20090302-7","meetingId":"h21-cm03","date":"2009年3月2日","dateIso":"2009-03-02","committee":"厚生委員会","time":"午前１０時０２分～午後５時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"改正された背景というのを少し教えていただきたいのと、４月１日からの新しい制度ですけれども、委託先がどういうところになるのかを説明を求めました。","respondent":"諸岡児童課長","answer":"これは都道府県から委託を受けて事業を実施するということで、具体的には児童相談所から委託を受けて、要保護児童の養育を実施するというものです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"養護施設も、今、あちこちいっぱいになっているということも以前にお伺いしたので、受け皿としてはいろいろな工夫が必要かなと思っています。ＮＰＯも結構いろいろなＮＰＯがあるんですけれども、この辺の審査というのはかなり厳しく行われるんか尋ねました。","respondent":"諸岡児童課長","answer":"ほっとファミリー、養育里親につきましても、東京都の方で審査基準というものを設けております。今後、法人等につきましても一定の審査基準を設ける方向で検討しているというふうに聞いております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"里親制度の充実ももちろん大事なんですが、基本的には、養護施設なんかも十分に充足していく必要があるんではないかと、一点思っています。審査基準もつくられるということなので、充実した、子どもたちによい環境が保てるような制度にしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"今、品川区でファミリーホームに相当するような、個人あるいは法人の運営されているものがあるのかどうか。あるいは、今後つくられるような動きがあるかどうかを説明を求めました。","respondent":"諸岡児童課長","answer":"これは全体的にもまだ数が少なくて、全都で、平成１９年度末の時点で１２件です。そこで預かっていただいている子どもの数が５４人ということで、数的にはそう多くないです。","id":"exchange-004"},{"speaker":"阿部委員","kind":"意見","question":"今後の動きがあるかどうかも、あわせてお願いしますとの意見を述べました。","respondent":"諸岡児童課長","answer":"養育里親に登録していただいている方々を集めて、ファミリーホーム制度を含めて、この制度の説明会を開催するということを聞いております。そういうことで、その次の段階として、社会福祉法人とかＮＰＯの方へ働きかけをしていきたいというような予定をしていると聞いております。","id":"exchange-005"},{"speaker":"阿部委員","kind":"確認","question":"品川区で設置の動きがあるかというのを確認したかったんですが。","respondent":"諸岡児童課長","answer":"まだ具体的には、この制度を受けての東京都としての考え方、これをまだ法人等にも説明していない段階ですので、特に今の段階で手を挙げて、この制度に早速乗りたい、予定をしているというところがあるということは聞いておりません。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"品川区内で養育里親の登録者数がどのぐらいかというのと、今現在、里親の制度で養育していただいている子どもさんというのがどのぐらいなのか。概略でも構わないんですけれどもとの意見を述べました。","respondent":"諸岡児童課長","answer":"そのうち、実際にお子さんを預かっていただいている家庭が６家庭、お子さんの数が１１名です。約３カ月までの間を一時保護委託ということで預かっていただいているわけですが、これが３家庭で、子どもの数が５名という実態です。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、前に里親登録をしている方とお話をしたときに、制度自体をあまりよくわかっていないというのを言われたことがあったんですね。実際にそれと結びつくかどうかはまた別の面もあるけれども、登録者数もまた増やしていただきたいなという思いもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"かなり質問がありまして大体理解はできたんですけれども、里親が１０家庭あるということで、人数もお伺いいたしました。そこら辺、ちょっと細かいところで申しわけないんですけれども、お伺いしたいと思います。","respondent":"諸岡児童課長","answer":"４名から６名ぐらいと、現在で実施している中ではそういう数ですが、個々に判断をして東京都の方で委託をお願いしているです。それから、東京都の方では里親の方に、この制度について周知を図るために説明会を何回か開いて呼びかけていきたいということで予定をしているです。","id":"exchange-009"},{"speaker":"浅野委員","kind":"確認","question":"１人当たり約１５万円支給されるという資料があったので、今は出ていないのかどうか、確認したいと思います。","respondent":"諸岡児童課長","answer":"これは平成２１年から大幅に引き上げられることが予定されていまして、予定では７万２,０００円にアップするということで聞いております。これはその都度、学校によって金額が異なりますので、請求をして受領しているです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"今の質問の中で、児童１人当たりおおむね月額１５万円と資料の方で出ていたので、そこら辺の危惧というものがあるのかどうか教えていただきたい。","respondent":"諸岡児童課長","answer":"これまでは１人当たり１０万円程度ということで聞いておりますけれども、それが今回の里親手当の大幅な増額につながったものだと聞いております。ほぼ倍以上になっておりますので、里親のそういった要望が反映されているというように聞いております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"この里親に預けられるというんでしょうか、子どもが健全に成長するように支援していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"堺委員","kind":"確認","question":"１点目は、基本的な違いというんですか、それはどういうところなのか。ファミリーホームですから、着手していく、そういうことは可能なのかどうかですね。","respondent":"諸岡児童課長","answer":"この要件に合えば、ファミリーホームの方に移行していただいて、お子さんを４人ないし６人程度預かっていただくということが可能です。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今、どういうふうな形で増えているのか、そこら辺が増えているために多分養護施設も満杯になっているということなんだと思うんです。その満杯だという状況と、品川区で、養護施設に入られている子どもさんがどのぐらいいるかというふうなこととあわせて教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"養護施設、要するに家庭で生活することのできないお子さんの数ですけれども、これが平成１９年度末の時点で東京都内で３,９００人と言われています。精神的疾患に陥ったりということで子どもの面倒を見ることができないというお母さんの数が最近増えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の子どもたちの中で、養護施設に入られている子どもさんがどれぐらいいるかという数字も、わかったら教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"区内でといっても、区外に転出されたりしまして、なかなか実質としては区ごとの把握ということはしてございません。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"養護施設の充実のところも含めてやっていただきたいということも含めまして、この条例に関しては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料の順番に沿ってお伺いしたいと思いますが、今までのリハビリのサービスに加えて三つを新たに市町村特別給付で行っていくというところです。介護給付と市町村特別給付の違いをはっきりと教えてほしいのと、財源についてもあわせて教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"制度上は国での平均的なものではありませんけれども、必要であると判断をした場合に、条例によりまして設ける給付です。そのようにして、現行のリハビリテーション給付もされているです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"財源のところが一番聞きたいところなので、そこの違いをはっきりと教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"この特別給付の財源につきましては、第１号被保険者の保険料をあてるという内容です。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜ今日、６５歳以上の方の負担が増大をしていくというところにおいて、ほとんどここを使っていないんですよね。私たちは、他区のように一般財源を使えば高齢者に負担をかけないで済むと考えているんですが、この点もあわせて説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"それから、この部分ですが、これは例えば通常の給付ですと、６５歳以上の方は２０％の負担ということになります。必要ということであり、これを負担していただく、第１号被保険者の方の保険料からいただくということがよろしいのではないかという判断です。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保険料を１人幾らぐらい押し上げることになるのか、その数字を教えていただきたいのと、他区の状況を幾つか知らせたいと思います。なぜなんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"特別給付で実施することにつきましては、６５歳以上の方、第１号被保険者の方の。ここにつきましては、１号被保険者の方の保険料から負担いただくです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"保険料のところもお伺いをしたいんですけれども、品川区は２３億円、その１割の根拠が全く理解ができないんですね。私たちは、２３億円たまっている基金とはどういう中身なのかなというところもあわせて、もっと取り崩せないかというところの答弁をお願いいたします。","respondent":"冨岡高齢福祉課長","answer":"そういうことも含めまして、ぎちぎちに基金を残しておくのではなく、一定程度の部分というのは必要だと考えています。その総体の中で今回も９ないし１０億の基金の積み崩しということで、３,９００円という今までどおりの料率に据え置いたという内容です。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ですから、この時期のところに基金を歳入として入れて、保険料を下げろと書いてあるんですよね。他区の状況からも実際というものをぜひ知っていただきたいと思うんですけれども、２３区調査においても、品川区の基金は断トツに多いんですね。","respondent":"木下福祉高齢事業部長","answer":"１割相当を留保していると、どういうことが起こるかわかりませんけれども、言ってみればかなりの対応力を持つことができる。療養病床の転換も今後大きく進行してくる可能性もありますので、そういうことも含めて、１割程度を確保すべきだろうと考えているです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"意見","question":"最高額が３００万円以上というところにおいては、ここのところはもっともっと工夫が必要、応分な負担をしてほしいなと思っています。たとえば１.８とか、２とか２.５とか、その辺もちょっとお答えくださいとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"１.何倍とかですと、結果的に人数が３％の部分ですので、いくら保険料を上げてもなかなか埋まっていかないんですね。介護保険というのは支え合いの部分ですので、そういうことで果たして保険料体系の信頼が得られるかというと、非常に難しい部分が出てくると思います。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"１,０００万円以上の方が３％という数字を教えていただいたんですが、２,０００万円の方も、それはちょっと修正が必要であるなと思います。料率を細やかに工夫をすることで、少しでも公平性を担保しているというところにおいては、品川区ももっと努力が必要であると私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、多段階化も理解をするし、市町村特別給付も十分対応してもらったというのも、まず前提に思っています。できれば政策的判断ということでお願いしたい。","respondent":"木下福祉高齢事業部長","answer":"区としては、そういうことから考えると、横出しサービスにふさわしいんだったらこの制度の中で対応するのが基本だろうと思います。要介護・要支援の方々に対するサービスですから、これは１号保険料の中で対応する、区としては。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これ自体、一般に区民の方に広めて、パブリックコメントも出ていると思うんですけれども、我々の中でも評価している声を聞いています。こういう形でいいなというのは我々も伝えていますし、理解している部分があるということを言って、この場は終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問・要望","question":"それだけ「自分は３００万円ちょっとであるにもかかわらず最高額払っているんだ」という不満が少し和らげられると言ったらいいでしょうか。９段階であるときと、これが１２段階ぐらいになったときと、そういった議論はありますか。","respondent":"冨岡高齢福祉課長","answer":"そういうのを考えた場合に、なかなかそれもどうかなと、いろいろな議論があります。８５％ぐらいの方は元気で、介護保険を使わずに活動されているという方のことも考えなければいけないと考えています。","id":"exchange-027"},{"speaker":"阿部委員","kind":"提案","question":"検討課題としてそういった視点もどうであろうかというご提案も含めておりますので、またゆっくり考えてほしいと求めました。厚生労働省がそういう方針を出した背景というのをもしご存じでしたら説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"国の通知が出た背景ということですね。さっきも申し上げましたように、最終的には各自治体が判断すべき部分もあるということを国の方は述べているんだというふうに私どもは考えております。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひこちらの適正な額を確保していただきたいということと、これはできるかどうかは別といたしまして、また維持していっていただきたい。私の方からは、質問は全部出払ったと思いますので、要望だけにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"堺委員","kind":"質問","question":"ただ、時間が２２時から７時となっておりますが、それ以外の時間帯の中ではだめなのか。それも含めて教えていただけますか。","respondent":"冨岡高齢福祉課長","answer":"これは制度的には夜間対応のサービスですので、見守り機能とかというのは、ほかにもいろいろ様々なものがあります。一応２２時から７時という形で対応しますが、近隣とのおつき合い、そういうものを様々併用しながら対応してまいりたいと考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"市町村特別給付からお伺いしたいんですが、今まで身近にリハビリと水中ウォーキング、この５種類のそれぞれの予算を教えていただきたいのが１点です。そこら辺のところも含めて、これだけでは不十分なんじゃないかと思うので、その辺はいかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"要支援の夜間対応が５９７万４,０００円です。これは、これにつきましては、そういうことで対応できれば時間的には何とか大丈夫だろうと理解しております。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところを、区民にどう説明するんですかということをお聞きしたい。じゃあ、どういうところにどんな例があるのかということも示していただきたいし、この理由について改めてお答えほしいと求めました。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"一番最後の東大井のケアホームの関係についてご説明しますが、これは、いわゆるケアハウス制度というのがありますね。移り住むということを考えたときに、グループホームは大体１７万円相場にしてありますから… 要支援者の外出支援の部分を要介護ではということでございましたけれども、要支援者の方に予防通所介護を利用するときに、こういうものを合わせてお使いいただくといいということで設定をさせていただいたです。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう思いでずっと質問もしてきましたし、そういうところではもっと下げてほしいというのが要望です。これももっと減額してほしいと思うぐらいですけれども、西五反田は、２５万円から３０万円ぐらいの利用料のままじゃないか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"そういうことを言っているのは品川区ぐらいしかありませんから、ケアハウスの歴史的経過から言うと、そこは給付の上乗せをするというのが正しい。だとすると、まだそういうふうになっていないんだから、横出しサービスで行きましょうというのが、我々の制度的な整備の考え方です。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この助成金が平成１９年４月からなくなったということなんですけど、じゃあ、助成金がなくなった理由は何なんでしょうか。そういうことであれば、先ほどの２９人以下の施設の人件費の助成金が廃止になったというその理由というのも、改めて教えていただきたい。","respondent":"木下福祉高齢事業部長","answer":"２９人以下は対象外にしたということで、２９人ぐらいの規模のものというのはみんな地域密着型で、２９人以下は東京都の方は対応しなくなった。ご報告をすることになりますけれども、そういう形をとおす中で、区民の方のご意見もちょうだいしているということであります。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介護保険の３年間の、これからの区民の介護にかかわる大事な条例ですから、聞きたいことも聞かずに終わるという委員会は間違っていると思います。区民に責任を持たなきゃならない委員会ですから、しっかりと聞きたいことも聞く、審議をする、そういうふうな委員会にしてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"平成２３年度もあります。その中で最適なもの、一番適当と思えるものを選んできたです。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この９段階の方が９,５７５人いらっしゃるわけですけれども、９段階の、先ほど１,５００万円を超えた方が３％でしたっけ。１,５００万円、２,０００万円、収入別の人数を教えていただきたいと思うんですけど。","respondent":"冨岡高齢福祉課長","answer":"１,５００万円以上が１,３１３人。合計で１万２６５人です。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これの１.５倍ですから、毎月の保険料を引き下げるということにもつながっていくと思うんですけど、そういう試算というのはされたんでしょうか。区民の負担を少しでも公平にしていくということを考えれば、それが必要なんじゃないかと思うんですけれども、その点についてはいかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"お話の部分も当然検討はしてまいりました。いろいろな角度から検討した結果、例えば合計所得金額３００万円というのはどのぐらいの生活水準の方かというと、これに１２０万円足す数字ですね。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"厚生労働省の指針に沿ってやっているわけですから、２,０００万円あろうが、私は３００万円の人にも納得いかないのではないかなと思うんですね。そういう方がどれくらいいらっしゃるのかということだけ教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"１.１６というそれぞれの細かい段階がありましたので、その方たちは１.２０になるということで、上がるということです。人員的には、ちょっと調べないと出てまいりません。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"地域密着型ケアハウスでも、この介護報酬が比較的低額であることなどの利点と、それから質の確保がされるという点で、賛成なところです。介護保険料の多段階化についても、所得によって負担の見直しをしたということで、今回の条例案に対しては賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"堺委員","kind":"質問","question":"前回の委員会の中で請願審査だったでしょうか、各自治体の判断に任されているわけですから、我々としては理解をするところです。ですから、できればその方々に、同じような趣旨のご質問は、どちらかの方にお願いをして、なるべく質問はダブらないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"市町村特別給付の追加ですけれども、新たな横出しサービスの財源は、６５歳以上の保険料を使わずに、一般財源をあてるべきです。基本的には６５歳以上の方に返すべきものですので、もっと保険料を引き下げる、６５歳以上の方に還元すべきであると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"阿部委員","kind":"質問・要望","question":"これまで民主品川としても求めてきた内容が入っているということ、在宅介護について新たなサービスをつくっているということを評価しております。たまりぐあいと言ったらいいんでしょうか、今、このような形で財源を組んでいくというのは妥当な選択であるかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうしてこういう基金という形をとられるのかというもとのところをひとつ教えていただきたいのと、今回、この辺がどのように使われるのか。ある人なんかは２万円アップとか、すごい期待が高まっている中で、このお金がどういう使い途をされるのかというところを説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"中身とは若干違ってまいりますが、上げないでいくという機能といいますか、活用をするものです。３年間でこの交付金を使い切るわけですので、単年度ではないということで基金化するということです。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"単年度ではなくて、３年間で使うところにおいては、こういった基金をつくっていかないとお金の入り場所がないという理解でいいんでしょうか。そこがちょっとよくわからないのでもう１回と、処遇改善基金ということにおいては、そこのところには全然影響しないということなんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"そういう趣旨で交付金を出しているということでありますが、これについては、介護従事者の方の処遇をよくするために３％介護報酬をアップします。これを使うことによって抑制してくださいという趣旨の基金であり、交付金です。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを区が３年間という使い方はできないということなんですねという確認を一つと、過去において２回、介護報酬の引き下げがありましたよね。２回の引き下げで、改善でということで３％引き上げになったんですが、どういうところに３％アップ分を使えるのかというあたりを教えていただきたい。","respondent":"冨岡高齢福祉課長","answer":"それから、これについては、国では使い途とかそういうのは、基金をつくりなさい、設置しなさいということで、準則も出しております。全国共通の形の準則が出ておりまして、これに応じて、これについては特に財源をということはできないなというふうに理解しています。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"意見","question":"使われていないかというのは、返すということのここら辺はどうも意味が納得いかなかったんだけど、どうとったらいいのか。ただ、ちょっと引っかかるので、何かお答えをほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"これについては、そういう全体の中で、残れば返さなければいけない。残額があるときは返さなければならないんですが、残りがないということは、そのまま報告を出して終わると理解をしております。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もちろんそうあってほしいし、だけど、これはどうしても入れなきゃいけない文言だったのかなというのがちょっと気になっているところが。答えはわかったんですけどとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"この附則は、建て前といたしましては、３年間で清算するという考え方があります。返納する、あるいは足らないからちょうだいという話は、基本的にはないだろうということを前提に組み立てていると理解しております。","id":"exchange-047"},{"speaker":"阿部委員","kind":"質問","question":"２とあって、これはまさにそのためにお金が来るわけですから、交付されるお金の基金ですからそうであろうと思うんですが。ご説明お願いします。","respondent":"冨岡高齢福祉課長","answer":"これは最終補正でまた計上する予定になっております。保険料については、保険料に充当するなりして落としていくというのと、それ以外のものについては、基金からおろしまして予算化するです。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"そこに１,３９０万円というのが、広報とか、システム整備などに使われるということでよろしいんでしょうか。両方とも２年間あわせての数字だと思うんですが。","respondent":"冨岡高齢福祉課長","answer":"単年度で使うものです。ですから、新年度の準備とかそのための経費ということになります。","id":"exchange-049"},{"speaker":"阿部委員","kind":"質問","question":"そのほかに、初年度に１,３９０万円、広報等の費用が来る。この１,３９０万円というのは、きっちり１円のプラスマイナスもなく使い切るものなのか、説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"これも余れば基金の性格からすると当然清算するということになりますけれども、準備経費、円滑経費ですので、予算的には使い切るという予定であります。","id":"exchange-050"},{"speaker":"阿部委員","kind":"質問","question":"それは多分、それ以上使っても国が持ってくれるというわけではないでしょうけれども、１,３９０万円使い切らなかったら、初年度のうちに清算する。１,３９０万円使い切るまで使っていくということなんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"の方の分については、単年度で使うです。","id":"exchange-051"},{"speaker":"阿部委員","kind":"意見","question":"理屈として了解しました。とにかく、軽減のための財源まで使っちゃいけないんだなと思ったんですけれども、そこのところはきちんと使い分けができるということで結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"堺委員","kind":"意見","question":"聞き取りにくい部分も若干あったので、単年度で準備経費として１,３９０万円。それ以外に、今ここでお話があるような、積立金として３カ年で使っていいお金が２億５００万円という金額でしたかとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"委員のおっしゃったように、３年間で使う交付金が２億５００万円、それから単年度で使うものが１,３９０万円という金額です。","id":"exchange-053"},{"speaker":"堺委員","kind":"質問","question":"３カ年、来年、再来年にかかわる準備経費は、初年度に全部終えているから、もう来ませんという考え方になるんですか。それをもう１回。","respondent":"冨岡高齢福祉課長","answer":"今回の基金は、両方合わせて２億１,９００万円余交付されるわけでございまして、それをあるものは１年間で使いなさい、あるものは３年間基金として運用してつかいなさいと、こう二つに分かれているという内容です。","id":"exchange-054"},{"speaker":"堺委員","kind":"確認","question":"２８号議案の段階では、今のこの２９号議案については触れていませんでしたから、理解をしていいんだろうと思うんです。もう１回その辺確認させてください。","respondent":"冨岡高齢福祉課長","answer":"今、委員のおっしゃいましたように、この基金については、第四期の保険料の基準額を定めるために充当活用して、この３,９００円を維持したというところに使われた、同じように基金についてもそうですけれども、この交付金についても同じように、その中に織り込んであるです。","id":"exchange-055"},{"speaker":"堺委員","kind":"質問","question":"ご説明いただいている資料の２ですか、さっきの２億５００万円というのは３カ年使用可能というか、使っていいお金ですよね。数字の基準の方法というんですか、さっき２億５００万円というお話があったから、どういうふうになってくるのか。","respondent":"冨岡高齢福祉課長","answer":"考え方をまず申し上げますと、国が基金として交付金をするものは、改定分の３％に相当するものをいただいています。３年目はあげませんという意味の対応が２年という交付額です。","id":"exchange-056"},{"speaker":"堺委員","kind":"質問","question":"そうすると、ここに「国の考え方」というのがありますけれども、それは今ご説明いただいたことになるんですか。要するに２億５００万円と、平成２１年度の当初予算案に書いてある金額と、どう理解をしたらいいのかなと思ってお尋ねをしたんです。","respondent":"冨岡高齢福祉課長","answer":"重複になりますが、国の考え方と区の考え方、もちろん違っておりますが、これは当然、話をして、原則はこうだけれどもということで話はできているですので、品川区につきましては、今言った趣旨に立ちまして、均等ですることによって、負担もそのようにしていきたいです。","id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかっている範囲で、処遇改善がどの程度まで行くのかというあたりについて、１点お聞かせいただきたい。本来であれば３％、それでも３％上がるというふうなところで、そこの点についてお聞かせほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"それから、今のところそんなに審査の結果に移動はないというような話を受けていますので、その点についてはそんなに変更はないものと思っています。その結果も介護現場の方に反映していくだろうと考えております。","id":"exchange-058"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから、この名前に書いてあるように、介護従事者の処遇改善というところでは、私は３％では本当に足りないんだと思うんですね。４.７％が既に引き下げられているわけですから、３％にとどまらず、区の方からも引き続き国の方に言っていっていただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"堺委員","kind":"質問・要望","question":"その部分はすべて保険料の急激な上昇を抑制するという形の中で使われていくということですから、大変いい施策ではないかと考えています。そのことは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"意見","question":"介護報酬の３％引き上げははなはだ不十分であって、もっと国は努力をしてほしいなと思うところですけれども、今回国が財源を示して、保険料に跳ね返らないようにという対策なので、賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"阿部委員","kind":"意見","question":"３年間の基金で標準化してというひな型をつくってくれというのは、一体国というのはむだなやり方をするなというのが率直な感想です。それぐらいなら定額を３年間同じように配ってくれればお互いにすっきりすると思うんですけれども、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"阿部委員","kind":"質問","question":"大変基本的な質問で恐縮なんですけれども、今回、この新体系への移行を条例上定めるのがこの条例になってくるんですか。それとも、この新体系の移行内容というのは、また別途何らか定めて、それでスタートということになるんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"この条例によりまして、新体系、自立支援法の事業を展開するというスタートです。","id":"exchange-063"},{"speaker":"阿部委員","kind":"質問","question":"非常に技術的な内容になっておりますけれども、むしろ、審議すべきはこの新体系の内容そのものと考えた方がいいんですか。以前も委員会で、一応移行についてご説明がありましたけれども、今回の状況で、改正案の検討後、移行の形がほぼ決まると考えてよろしいか尋ねました。","respondent":"高橋障害者福祉課長","answer":"この内容で、来年度以降進めするということで、事業内容は個別に今後はそれぞれの施設で具体的なメニューが入ると思いますが、基本的な事業展開をこの条例で、各施設も今後につきましては理事会等で検討し、最終的には、４月１日以降実施というふうな形になるかと思います。","id":"exchange-064"},{"speaker":"浅野委員","kind":"質問","question":"阿部委員からもお話がありましたとおり、逆の立場から言うと、利用される側からとってどうなのかもちょっと気になるところなんですね。そのような利用する側の立場に立つと、一体どのような変化があるのかというのを、ちょっとわかりやすく教えてほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"この条例案の提案の前に、９月３０日以降、各施設の保護者、もしくは本人への説明会につきましては、最低でも２回行っております。その間、それぞれのメニューに合わせてご本人の希望を取り入れた上で変更ということも考えられますし、急激な変化は今のところ考えておりません。","id":"exchange-065"},{"speaker":"浅野委員","kind":"質問・要望","question":"ここの部分が一番心配されることでありますので、ご本人、利用される方には少しずつの変化で、急激な変化がないように、これからも注意を払っていってほしいと求めましたので、この点は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"もう１回この間のおさらいみたいになっちゃうんですが、こういう体系になっているという受けとめ方でいいんでしょうか。集会室のことで質問を私がいただいてしまって、利用勝手や何かで変わるところがあるのかどうか、その辺のところを説明を求めました。","respondent":"高橋障害者福祉課長","answer":"変更があるかと思いますが、また障害者団体への関係、それから地域のボランティアの活動の支援ということでは変わりなく進めてまいります。訓練センターの１、２を基本的には使っていただいているので、その辺についてはご安心していただければと考えています。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"もう一つ、知的障害者の援護施設条例なんですけれども、大もとのところで、援護という言葉が自立支援法に入っていないので、福祉施設に変わるということにおいては、法律の根拠のところも、援護という言葉が外れることでの影響が何かあるのかどうか、説明を求めました。","respondent":"高橋障害者福祉課長","answer":"就労支援、継続支援ということでの事業の名前で運営するということで、自立支援法に基づいた内容で運営するということになります。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"西大井の福祉園と、かがやき園のところに事業内容が書いてありますけれども、名称は変わっても中身的には変わらず、利用者さんにとっては同じように利用していただけるということでよろしいか尋ねました。","respondent":"高橋障害者福祉課長","answer":"そのように利用していただくようになると思いますので、よろしくお願いいたします。","id":"exchange-069"},{"speaker":"阿部委員","kind":"質問・要望","question":"特別支援学校卒業生とあって、自立訓練センターの中でもそういう形で説明されているんですけれども、これは特別支援学校の卒業生に限るんですか。そこはもうならないのか、説明を求めました。","respondent":"高橋障害者福祉課長","answer":"就労継続Ｂにつきましては、作業所ネットワークを通じまして、具体的なそれぞれの事業のメニューを膨らませている段階です。特別支援学校の卒業生ということで、生活支援センターのご相談、もしくはうちのところでのご相談ということが必要になってくるかと思います。","id":"exchange-070"},{"speaker":"堺委員","kind":"質問","question":"先ほどご説明いただいた資料の真ん中辺にある、就労継続Ｂ型事業、この括弧の中に、「工賃の支払い目標水準を設定し、額のアップを図る。自立支援法に基づいて移行するということですから、障害を持った方も、この辺のところをもう少し具体的に教えていただけるとありがたいです。","respondent":"高橋障害者福祉課長","answer":"自立支援法ができた段階で、それぞれの就労継続を行っている施設、それぞれ工賃を５年間の間に倍増を行うという目標を立ててあります。授産内容の検討をしながら、５年間にということで、徐々には上がってきている。","id":"exchange-071"},{"speaker":"堺委員","kind":"質問","question":"ここで示されているのかどうかわかりませんが、それを５年かけてここまでアップしていくんだという、何か数字が出ているんですか。それもご説明いただければお願いしたいんですが。","respondent":"高橋障害者福祉課長、大沢委員長","answer":"どこどこの施設に８,０００円ですので、今のところ手持ち資料もありませんし、わかっている段階ではございません。工賃を５年間に倍増するように努力してくださいというような内容ですので… なお、３０号議案、３１号議案につきましては、別々に採決を行いますので、よろしくお願いいたします。これより第３０号議案品川区立心身障害者福祉会館条例の一部を改正する条例について採決を行います。","id":"exchange-072"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"新体系への移行については、昨年９月３０日に厚生委員会でご説明いただいて、その目的とか、いろいろ話もお聞きしていました。もっと丁寧にしてくださいという要望を出したと思いますけど、それからまた、自民党として賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"堺委員","kind":"意見","question":"賛成です。急激な変化はさせないですので、本人の状況をよく踏まえた上で、基本的には本人の都合を取り入れて対応していただければ大変ありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本条例には賛成をいたします。本人が満足できるような働き方という工夫を、この体系の中でも十分追求をしていただきたいということをつけ加えさせていただいて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"阿部委員","kind":"意見","question":"本人の状態と希望に合った形で支援をしていくということを目指していくということで、ぜひ力を入れて新体系を進めてほしいと求めました。ぜひご留意いただきながら、この新体系の移行については大変期待をしておりますので、しっかりとやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"賛成をいたします。特に、入所支援のところ、生活介護のところ、これからも大変重要であるし、充実をしていっていただきたいなという思いを込めて賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"提案","question":"高齢になり、医療が必要になったときに安心して受けられる制度が、今、求められていると思います。品川区の財政で十分まかなえる範囲と考え、提案をいたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"阿部委員","kind":"提案","question":"以前、同じような内容でご提案があったかと思うんですけれども、変わった点があれば教えていただきたいんですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜならば、共産党の区議団、今年第６回目のアンケートをしましたけれども、医療に対する要望が大変多い。今すぐにでも支援ができる、自治体でできるというところにおいて、再度提出をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"渡辺委員","kind":"質問","question":"件数で、２万３,０００件とありましたが、一月当たり１万円を限度というのが対象の額だったんですが、人数的な算出というのはどのような形で。これは件数なので、一月当たり１万円を限度という中で、１万円の根拠みたいなことを具体的に教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"提案","question":"私たちが提案したときに、私たちの提案としては、マックスの提案ということで。こちらの提案としては、１万円で、２億３,０００万円という予算を立てさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"渡辺委員","kind":"質問・要望","question":"要望するときには多いに越したことはないとは思いますが、おおもとが大切な税という中で、僕らも真剣に考えていかなければいけないなと思います。最後に確認なんですが、予算の２万３,０００件の件数で、特段はされていないということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"浅野委員","kind":"提案","question":"前回と同じ内容だったということも、事前に確認をさせていただきましたけれども、前回と同じ質問をさせてほしいと求めました。その算出の根拠というんでしょうか、ただ、高齢者の場合は入院の機会が多いということでの今回の提案だと思いますけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問","question":"日用品の考え方というんですか、私たち、聞いたところによると、例えば入院して、おむつ代だけでもかなり費用がかかるということなんですね。入院に伴う負担、家族が入院すると、こういった日用品類でも支援ができたら大変な助けになるのではないかというところを根拠にしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"浅野委員","kind":"意見","question":"７５歳以上ということで、様々なサービスを高齢者も受けられているということで、そのバランスはしっかりと見ていかなければいけないなと考えます。これにつきまして、そこの部分を踏まえて、全体的なバランスを見るということも必要かなと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ここで在宅の方と入院している方の、そこら辺の公平性はどういうふうにお考えなのか、説明を求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"意見","question":"以前、東京都の制度で、寝たきり手当、あの場合は、本当に寝たきりの方に温かい支援がされていたので、ぜひここも広げていきたいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"鈴木（真）委員","kind":"提案","question":"その予算を計算した上で、そういう事務的なものの事務費負担というのは、提案者としてはどういうふうにとらえているのか。もしここで予算をとっていたら、その分が乗っかっていなければおかしいのではないのかと思いますけど、そこら辺、提案者としてどう考えているのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"提案","question":"予算のところは、まず申請を受けて、登録をして、用紙を送って返してもらうということで、かかる費用といったら、郵送料は確実にかかるわけですけれども、予算の修正をこれから提案する中で、その辺はしっかりと精査をしていきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"堺委員","kind":"提案","question":"提案者の方から、ご提出いただいている条例の第３条の中で、医療機関への入院に関して生じた費用とする」と。こういうふうに定めておりますが、今日提出していただいている説明の中の条例内容の３番目か尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今ここに書いてあるように、医療費も含む、それ以外も含むんだという説明ですよね。関係者にはお尋ねしたかもしれませんが、それでよかったかどうか、ちょっと説明を求めました。","respondent":"諸岡児童課長","answer":"子どもすこやか医療費助成制度につきましては、保険診療分の医療費にかかわる自己負担分について助成をしているものです。","id":"exchange-092"},{"speaker":"堺委員","kind":"提案","question":"今、課長のご答弁にございましたように、あくまで保険診療分の医療費についてということですから、子どもすこやか医療費については、お子さんが入院した際の、今日提案されているような、いわゆる日用品類とか、そういったものについては対象になっていませんよという理解でいいんか尋ねました。","respondent":"諸岡児童課長","answer":"あくまで保険が適用される分です。入院時食事代とか、そういったものも、保険が適用される分については助成されます。","id":"exchange-093"},{"speaker":"堺委員","kind":"提案","question":"ですから、それ以外のものにも充当させるということについては、どうしても首を縦に振れないなと。この提案理由の中に示されているようなこと等を踏まえると、どうしても私、そんな感想を持ちましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"年をとったときに安心できる、そういう気持ちになれるような施策というのは、とても求められていると思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"阿部委員","kind":"意見","question":"前回どおりということですので、前回どおり反対です。それぞれに経済的にも精神的にも苦しい中で、そのみんなで出した税金の中で７５歳以上だけというのが、ちょっと制度としてどうかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"}]},{"id":"topic-02","title":"平成２１年請願第３号 医療依存度の高い障害者（児）の在宅生活を支える福祉支援を品川区に求める請願","agenda":"平成２１年請願第３号 医療依存度の高い障害者（児）の在宅生活を支える福祉支援を品川区に求める請願","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"今、訪問看護という言葉が出ましたけれども、訪問看護という制度でその要望を満たせているのかどうか。その辺についてお伺いしたいと思います。","respondent":"高橋障害者福祉課長","answer":"自立支援法の介護給付費を出しているものにつきましては、利用者数が、平成１９年度末で３８人行っているものです。それと、例えば子どもさんであれば、東部療育センターみたいなところで療育機関とつながったショートステイを利用していただくというような状況です。","id":"exchange-097"},{"speaker":"阿部委員","kind":"質問","question":"医療ケア等の必要な方が、家庭の方の看護を受けられないときには、施設の方にショートステイをお願いし、行くしかないということなんですね。在宅のままでケアを受けられるような仕組みというのは、今のところないと考えてよろしいか尋ねました。","respondent":"高橋障害者福祉課長","answer":"大人の方でしたら、基本的には医療機関が重なっているところのショートステイをご利用いただくというような形になるかと思います。通院ということではなくて、基本的には医師が往診という形で、看護師を連れて往診を重ねているということが一般的な状況と聞いております。","id":"exchange-098"},{"speaker":"阿部委員","kind":"質問・要望","question":"今の医師法等々の仕組みの中で、看護師を派遣する制度というのは、つくろうと思えばできることなんですか。可能かどうかといったときに、ここで求められているような仕組みというのは、なかなか困難であるというものなのか。","respondent":"高橋障害者福祉課長","answer":"昼間と夜との変更ということも、いろいろ今、厚労省の方で検討している段階です。医師の指示なくして医療行為はできませんので、福祉制度ではなくて、医療の中の制度として派遣するのがベストかと考えています。","id":"exchange-099"},{"speaker":"阿部委員","kind":"意見","question":"１泊２日という設定ということですが、昼の数時間を預けるために２泊しなければいけないというのは、お互いにとってむだだと思うんですね。そういったことも、ぜひ行政の方で、これは知恵を絞れば解決できることだと思いますので、ぜひご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"鈴木（真）委員","kind":"確認","question":"これは私の知っている限り４回目の請願だと思っていますが、まず、区として適切な指導とかアドバイスは送られていると判断してよろしいんですね。そこの確認だけ、ちょっとお願いします。","respondent":"高橋障害者福祉課長","answer":"うちとの連携は進めさせていただいていますので、医療だけをやっているということではございませんので、その辺については連携を進めしています。","id":"exchange-101"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私も、実際に人工呼吸器をつけている子どもさんのところに訪問看護に行かれているという訪問看護ステーションからお話をお伺いしたんですけれども。充実をさせていくというところではどういう方法があるか、考えられているところがあったら、お聞かせほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"２４８時間のヘルパーの派遣、ものによっては１日１２時間等、その人の状況におきましてヘルパーを派遣しています。医療機関がきちっとした対応ということで、役割分担を続けながら連携をして進めするのが、在宅で生活を継続できる重要なポイントかと考えています。","id":"exchange-102"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところも含めての負担軽減がとれないのかというあたりがどうなっているかということと、そのヘルパーさんのことを一つお聞かせいただきたい。区も大病院と連携をとって、そういうものを復活させて、充実させていくという点についてはいかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"医療の問題なのか福祉の問題なのかということでは、全体的な検討の中で進めるということが必要になってくるかと考えています。ただ、今後の検討なり、研究課題として取り上げる必要があるかと思います。","id":"exchange-103"},{"speaker":"堺委員","kind":"確認","question":"４回目の請願ということですが、医療行為と福祉のあり方というんですか、医療と福祉というんでしょうか。もう１回、確認でその辺を教えていただけますか尋ねました。","respondent":"高橋障害者福祉課長","answer":"私が申し上げた週１回の３時間程度というのは、１年に１回医師が判断し、週１回程度行っているというものです。ですので、地域での訪問看護につきましては、保険法の中で十分利用できているのではないかと考えています。","id":"exchange-104"},{"speaker":"堺委員","kind":"質問","question":"健康保険法ですか、医師の指示のもとで看護師を派遣するということですから、我々は理解をしていいんでしょうか。もう１回ちょっと説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"品川区が例えばそういうような制度をつくったとしても、それは違法な制度になってしまうという問題になります。品川区がそういう制度をつくれという趣旨のように読み取れますので、それは法上の問題があってできないというのが、現在の判断になろうかと思います。","id":"exchange-105"},{"speaker":"鈴木（真）委員","kind":"意見","question":"意見陳述の申し出はいただいておりますが、今回４回目の請願ということと、再三質疑もしている中で、私は意見陳述していただかなくてもここまで理解していると判断いたしますので、意見陳述に対しては反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"},{"speaker":"堺委員","kind":"質問・要望","question":"４回、これはあくまでも医療行為ということですから、僕はどうも非常に難しい気がします。お気持ちは十分理解するし、わかるんですけれども、今日のところは意見陳述については差し控えさせていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問・要望","question":"請願文からは読み取れない部分もありますので、ぜひ、共産党としては、ご意見を聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"阿部委員","kind":"質問","question":"意見陳述はお伺いしたいと思います。ただ、運営のこともありますので、手短になり、あるいは委員長に時間を区切っていただくなりするような形で伺うことができればと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"堺委員","kind":"質問","question":"意見陳述については、いろいろな面で難しいという趣旨のご発言をさせていただいたんですが、訂正させていただいて、せっかくの機会ですので、意見陳述をお聞きさせていただければというふうにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"確認","question":"意見陳述をやるということは、今日この質疑はこのまま止まって、意見陳述は明日ということで、時間的にはこのまま続けるんですか。その辺の事務的な流れを確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"質問","question":"継続ということは、次のところでまず意見陳述をする・しないということも諮るということからスタートですか。オーケーをとっていない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"ご自身の意思で口座振替になった方がどのぐらいいるのかというのが聞きたいのが１点。その辺の滞納者の状況がわかったらぜひ知らせてほしいのと、滞納の理由を説明を求めました。","respondent":"永尾高齢事業課長","answer":"申しわけありませんが、昨年８月と今年の１月に、全員に「選択できる」というような通知をお送りしております。ただ、１０月以降についてはまだこれから督促状をお送りする予定ですので、９２から９６％の間というような状況になっております。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺を確認させていただきたい。７５歳以上は保険証の取り上げは絶対行ってはいけなかったので、それは絶対やるべきではないと思っているんですが、その辺はいかがか尋ねました。","respondent":"永尾高齢事業課長","answer":"８月、９月の督促状をお送りした後の反応ですけれども、区としても周知が必要かなと考えています。相当な収入があるにもかかわらず納めないという方については、また相談に応じながら考えていくというような体制をとりたいと考えています。","id":"exchange-114"},{"speaker":"飯沼委員","kind":"質問・要望","question":"悪質な方とか、国保や何かのときにもよく言われますけれども、その辺の判断はどういうふうにしていくんでしょうか。実際に７月から徴収が始まってかなりたっているんですけれども、実際にその辺の声というんですか、負担増がどのぐらいになっているか。","respondent":"永尾高齢事業課長","answer":"プロジェクトチームの方での検討の状況をいろいろお聞きしておりますが、７５歳で区切るのはどうかとか、出されている状況です。そういうことも考えて、区といたしましては、国の議論の結果を待ちたいと考えております。","id":"exchange-115"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お聞かせいただきたいのは、６９０人ということだったんですが、この方たちがその後どうなっているのか。先ほど包括払いのところは凍結になっていますということだったんですが、包括払いのところはどうなっているのかとか、この辺を説明を求めました。","respondent":"永尾高齢事業課長","answer":"わからないことがあれば高齢者の方々、すぐにお問い合わせをいただいていますので、その方について一人ひとり対応はしております。高齢者の方々は皆さんわからないということで、かなりお問い合わせがありまして、その都度ご説明をしております。","id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さっきの６９０人のところもそうですが、しっかりと一人ひとり把握をして、追いかけていただきたいなと思います。凍結という言葉を使われていますが、決してなくなったわけではないので、私は本当になくしていただきたいなということを申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"浅野委員","kind":"質問・要望","question":"もしわかれば教えていただきたいのと、「このような制度はすぐに中止すべきです」という中で、現状できているかなと思える部分があります。国民健康保険に皆さん入るような形になるという回答だったと思いますけれども、この点について、３点ほどですけれども。","respondent":"永尾高齢事業課長","answer":"最初にご説明申し上げました、医療証を交付するということで、また大きな急激な変化になるのではないかということが想定されます。実務面につきましても、システム改修や、条例の整備など、かなり煩雑なものがございまして、多額の費用と時間がかかるのではないかと思われます。","id":"exchange-118"},{"speaker":"浅野委員","kind":"質問","question":"これは当時のことですから、適切な対案というんでしょうか、後期高齢者の医療制度にかわるような案というのが果たして出されたのかどうか。それはある意味では無責任な参議院での強行採決ではなかったかなと思うんですけれども、この点については、区としてはどのようなお考えか尋ねました。","respondent":"大沢委員長","answer":"それは国の問題ですので、国に対して区で云々という立場にありませんので、その件については答弁は結構です。","id":"exchange-119"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もともとこれが医療費を抑えるためにということでできた制度ですから、ＯＥＣＤ３０カ国中、ＧＤＰ比の医療費が２２番目という。健康診断なんですけど、これは区民健診と比較して、受診率がどれぐらいになっているかということについてもお聞かせほしいと求めました。","respondent":"永尾高齢事業課長","answer":"４月から保険料の計算の仕方が変わるですが、今のところ何月何日号というような予定はしておりませんが、広報をするというように考えております。健診の件ですが、正確な数字がまだ出てきていない状態になっておりますので、その辺についてはご了承いただきたいと思います。","id":"exchange-120"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ですから、そこら辺の取り組みについて、どう考えられているかということについてもちょっとお聞かせほしいと求めました。ここのところも、ぜひしていただきたいなと思うんですけれども、その点も説明を求めました。","respondent":"永尾高齢事業課長","answer":"保険料の軽減についての変更点についてのわかりやすい表示ですが、明確な言葉で、大きい字で表示するような方法で考えてまいりたいと思います。その辺の対応については、なるべく受けるようにというお話は、お電話では申し上げております。","id":"exchange-121"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうふうに、受診率を上げるというようなことでの取り組みをぜひしていだきたいと思いますので、これは要望させてほしいと求めました。減額制度を知らないために受けられなかったということが１人もないところまでの取り組みを、ぜひ区としてもやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"飯沼委員","kind":"質問","question":"委員会の場で、皆さんと一緒に意見陳述をお聞きしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"阿部委員","kind":"質問","question":"何度もと言うほどでもないですか。今回については、とりあえずは伺っていいかなと。","respondent":"大沢委員長","answer":"意見陳述については挙手採決で行います。","id":"exchange-124"},{"speaker":"鈴木（真）委員","kind":"意見","question":"国民皆保険制度を維持していくということからも、このまま維持していくべきだと私どもは思っております。先ほど４月というお話もありましたが、そのように対応されているということで、この請願に対しては不採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"},{"speaker":"堺委員","kind":"意見","question":"今も担当課長からお話がございましたように、５年後の見直しについては前倒しをして、この４月には一定の局面が出るという流れにもなっております。この請願については、願意に沿いがたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-126"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日もいろいろご議論ありましたけれども、手直しだけではだめだという制度だという認識をしっかり持たなければいけないと思います。中止を求めながら、求められていると思いますので、採択を強く主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"阿部委員","kind":"質問・要望","question":"意見をするとか、要望書を出すとかといったことがあるんでしょうけれども、逆に地方自治を疲弊させてしまうことにもつながりかねないのではないか。こうした種類の請願にどこまで力を割いていくのかというのは、区レベルでちょっと考えていけたらいいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"飯沼委員","kind":"質問","question":"これによると３０２基、こんなところに３０２基もお墓が建つのかと、このような密集した墓地が建つような例が最近あるんでしょうか。区として、今、どういう状況に受けとめているのかというところを説明を求めました。","respondent":"荒井品川区保健所衛生課長","answer":"それ以前につきましては、平成１２年ですとか、平成８年ですので、新規墓地はここ最近あまりなかったというふうに記憶しています。今のところは丸山寺さんからの説明会の内容として、住民の方たちとよくお話をなさるように、理解を深めていただけるようにという指導をしています。","id":"exchange-129"},{"speaker":"飯沼委員","kind":"質問","question":"その辺をもうちょっと教えてほしいのと、ご意見をいろいろ伺ったら、何らかの規制というのはないのでしょうか。なかなか書きとめられなかったんですが、こういった地域の環境を守っていきたいという住民の方の立場を考慮するような部分はないのか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"例えば墓地の中には１ｍ以上の幅の通路をつけることであるとか、墳墓地の２％以上の駐車場を確保すること、給水等々の管理施設の設置。墓地敷地内１５％以上の緑地確保等々のことがあります。","id":"exchange-130"},{"speaker":"飯沼委員","kind":"質問","question":"今お伺いしたところではないといったことでは、建設を進める側と、地域住民の方々のお話し合いによるということなんでしょうか。安全性が脅かされるということだと思うんですけれども、この辺について、区ができる援助とか、何かないのか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"の方の質問にお答えするような形になりますが、墓地の予定地の前については４.３ｍ道路で、一方通行になってあります。説明会でもご意見として出されておりますし、お寺さんの方で受けとめていただいて、方策を考えていただくように強く指導しています。","id":"exchange-131"},{"speaker":"飯沼委員","kind":"質問・要望","question":"3)のところに、こういう悪い前例にならないようにと書いてありますけれども、これは新しい事態だと思うんですね。ですから、４月１日に工事が始まるというところでは、ぜひしっかりとご指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今の確認もかぶるんですが、もともとこの墓地等の関係の根拠法という中では、都条例がある。その確認が１点と、もう一つ、今回の陳情内容に沿った中での近いやりとりが把握されていれば教えてほしいと求めました。","respondent":"荒井品川区保健所衛生課長","answer":"説明会の内容として把握していますが、蚊が来たりとか、鳥が来たりとかというような被害が想定される。できるだけ皆さんが見てもきれいだと思われるような墓苑をつくりたいというのが、お寺さんの側の回答だったというふうに内容を把握しています。","id":"exchange-133"},{"speaker":"渡辺委員","kind":"質問","question":"肝心な近隣住民の方の意見をどのように取り入れていくか、反映するかという、その方法論とタイミングについて伺わせてください。可能性のところも含めてお聞きしたいのと、ほかの案件を踏まえてどんな考えがあるのか、その２点を伺えればと思います。","respondent":"荒井品川区保健所衛生課長","answer":"１点目の、車が集中した場合の対応についてですが、そういったことを主な指導内容として考えているところです。今までの墓苑の例なども、求められればお答えしていくというような形が考えられると思います。","id":"exchange-134"},{"speaker":"浅野委員","kind":"質問・要望","question":"お伺いしたいことがほとんど出てきたかなと思うんですけれども、お寺があって、その周りが墓地というのが普通の景色として見られる。当然、住民の皆様もいろいろと要望とかを出される中で、対応なんかも考えていくという段になるかと思うんですね。","respondent":"荒井品川区保健所衛生課長","answer":"丸山寺さんにつきましては、お墓につきましては、今の当該地にはお持ちでありません。保健所としてもお寺さんの方にできるだけ住民の方々の意向を大事にくみ上げるようにという指導は、重ねてしていきたいと考えております。","id":"exchange-135"},{"speaker":"阿部委員","kind":"確認","question":"繰り返しの確認になりますけれども、まずこのお寺さんが自己で所有する土地に墓地をつくる。それが条例の決める範囲を重視した中でつくるという計画を持ったときに、最終的に保健所なり区というのは、ノーと言えるんか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"基本的には、要件を備えてあればという話ですので、例えば、先ほど説明の中でも少し触れさせていただきましたが、経営者としての適格性であるとか、資金計画であるとか、お墓は永続することが大事なものですから、そちらの方の審査は十分にすることになるです。","id":"exchange-136"},{"speaker":"阿部委員","kind":"質問","question":"この陳情の要旨を見せていただいて、一つ住民の方の不快感と言ったらいいんでしょうか、不満を増幅させているところがあると思うんですね。ですので、区としては、住民の方とお寺の間で相互の理解が深まるといったらいいんか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"保健所としては、墓地を設置する予定者に対しての指導をしていくという立場にあります。","id":"exchange-137"},{"speaker":"阿部委員","kind":"質問・要望","question":"今後５０年、１００年、２００年どけられないようなものはつくるべきではないといった指針みたいなものは。ですから、この件については答弁を求めることはできませんが、こういうのはどうしたらいいんでしょうね。","respondent":"中村品川区保健所長","answer":"道路の拡張なんかをやり直すときは、改葬の公告を出しまして、お墓をほかのところへ移転というようなものが制度的にできております。５０年、１００年もその土地にずっとということにはならない、そういうご心配はないです。","id":"exchange-138"},{"speaker":"阿部委員","kind":"質問","question":"別にやってうれしいものじゃないわけで、狭いところにあえてつくって、すぐに「拡幅ですからまたどいてください」という話ではないと思うんですよね。これ以上言っても同じですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"堺委員","kind":"質問・要望","question":"１点だけ教えていただきたいのは、３月２日というと今日ですから、これは提出されているんですか。あるいは、出ているとすれば、どういった内容のものが出ているのか、参考までに教えてほしいと求めました。","respondent":"荒井品川区保健所衛生課長","answer":"1)、2)、3)が代表的な意見だというふうにとらえてあります。このほかにも先ほど少し申し上げました、構造設備に関すること、あるいはお墓自体の設置に反対するお声なども、申立書の中にはあります。","id":"exchange-140"},{"speaker":"堺委員","kind":"質問","question":"その意見申出書に基づいて仲立ちをするというんでしょうか、意見申出書が出ているので、それに基づいてお話し合いをしてくださいということですね。あるいはそういう場をしかるべきところにセットするとか、役所としてはそういうアクションを起こしていくという理解でよろしいんか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"おっしゃる通りです。その中で特に協議すべき事項については指摘させていただきまして、当事者間の間でお話し合いをお願いしますという形をとらせていただいています。","id":"exchange-141"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この陳情で言うと、今できるのは、協議しなさいという指導までができるということの判断でよろしいんですね。そこだけ確認で。","respondent":"荒井品川区保健所衛生課長","answer":"今の時点では、協議していただくということで指導させていただいています。","id":"exchange-142"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"南大井で昨年新たにできたということですが、このマンションのような、そこら辺のところを把握していたら教えてほしいと求めました。住宅街とか、葬祭場の環境指導要綱みたいなものというのはつくっていけるんじゃないかと思うんですけれども、そこのところはいかがか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"今おっしゃっていただいている件につきましては、おそらく東京都の条例の方がそれに対応しているものではないかと考えているところです。事業系の墓地といいますか、そういうのが増えてきているという状況はあるというふうに伺っているところです。","id":"exchange-143"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都の許可申請の手引というのを見せていただいていたら、初めは、周辺住民の承諾書を求めていたということで書かれていたんですよね。そういう話し合いを進める点での指導をぜひとも強めていただきたいと思うんですが、その点説明を求めました。","respondent":"荒井品川区保健所衛生課長","answer":"私が全国的な墓地の状況について説明したときに、つまり宗派にこだわらない墓地が増えているというのが正しい表現でしたので、ここで訂正します。","id":"exchange-144"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"本日結論を出すということで進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"堺委員","kind":"意見","question":"厚生委員会に付託されて、厚生委員会としてこの陳情に何らかの反応を示すというのは非常に難しい中身かなという気がしているんですね。私どもとしては、継続という形で、しばらく当事者間のお話し合いを見守りたいなという気がしているんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-146"},{"speaker":"阿部委員","kind":"意見","question":"というのは、今、まさにお寺さんと住民の方々で、ぜひ協議を重ねてほしい、話し合いを進めてほしいと考えています。その両者のスタンスを見ながら次にまた審査をするという形ができればと思いますので、継続にしたいと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"意見","question":"大前提の、協議を進める指導はきちんとやってくださいと。陳情の方には大変申しわけないですけれども、理解はするけれども、陳情に対しては願意に沿い難いというのが我が会派の答えですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-148"},{"speaker":"堺委員","kind":"質問","question":"もとになっているのはあくまでも東京都の条例ですから、協議の場はセットできるんだということですから、その対象になるわけですから。そんな感じになるんですが、採択と思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区は２個目のケースになるんですか、十分な話し合い、住民の方はそこにすがっていくというところがありますよね。品川区が今後考えていく課題でもあるので、ぜひ検討事項の一つにしていっていただきたいなという意見を添えて、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"阿部委員","kind":"意見","question":"少なくともうちの会派としては、ぜひ進めてほしいところで、陳情の要旨をどうとるか。陳情者の方にも、皆さんにご納得いただけるであろうと期待しつつ、採択いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/854582?Template=document&Id=3228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":102205,"voices":331}},{"id":"h21-20090302-8","meetingId":"h21-cm03","date":"2009年3月2日","dateIso":"2009-03-02","committee":"建設委員会","time":"午前１０時０２分～午後４時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"それぞれ今３カ所ずつあって、一応何台とめれるかというのは決まっていますけれども、現実的にはそれぞれ下神明駅のところと戸越公園駅のところと実際には何台ぐらい入っているのか、ちょっと教えてくれますか。","respondent":"諸石交通安全担当課長","answer":"下神明駅第２駐輪場の収容台数が８０台、利用台数が７６台、率が９５％となります。第３駐輪場は収容台数８０台、利用台数９５台、率が１１８.８％となっております。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"設定されている台数から見ると、両方ともかなりオーバーした状態で出されていて、新たに設定をされるのがそれぞれ少なくなる。実際の利用者からのアンケートですとか、今後の有料化についての声というのは聞いているのかどうか、ちょっとお聞かせ願いますとの意見を述べました。","respondent":"諸石交通安全担当課長","answer":"平成１３年からこの駐輪場の整備、それから有料化を進めてきております。利用者の方からは非常に好評を得ているなというふうに考えております。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"そうした中で、今回の場合は当日利用のみだということなんですけれども、この間有料化を進めてきた中で、当日利用のみの駐輪場というのは、ほかに何カ所ぐらいあるのかということと、それから、当日利用のみにした理由を少し教えていただけますか。","respondent":"諸石交通安全担当課長","answer":"今回、どうしても１カ月の自分がとめるスペースの確保はできますけれども、そうした方々が空きスペースがあっても駐輪場を利用できない。当日利用の割合、それぞれの駐輪場の環境によっても違うとは思いますけれども、研究していきたいというふうに考えております。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"１５０円という単位で考えてみると、通常、通勤とか通学で毎日のように使われる方、平均的に２２日間動くとして、月３,３００円になるんですかね。そういう状況というのも生まれてきて、その辺の想定は十分されるのではないかなというふうに思うんですけれども、その辺はどうか尋ねました。","respondent":"諸石交通安全担当課長","answer":"１５０円という料金の関係ですけれども、これは以前にもご説明を申し上げましたとおり。これからは定期利用の料金の改定等も含めた研究・検討をするということで、そうしたものも含まれているというふうにお考えいただきたいと思います。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"定期利用の改定を考えているというのは、そうすると、そこに他の駐輪場の定期利用についても合わせていくんだよという考え方なんですかね。ちょっとその辺をもう少し説明を求めました。","respondent":"諸石交通安全担当課長","answer":"それから、定期の額の関係、それから当日利用の額の関係、こういうものをトータルで研究をする。例えば駐輪場ごとに違う値段の設定があってもいいのではないかなというふうに考えておりますので、そういうものを含めて今後は検討・研究をするです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"それとも全然別の要素があっての話なのか、その辺も問題だと思うんですけれども、その辺ではどうなんでしょう。ターミナル駅とそうではない駅との違いがどういうふうにあるのかとか、その辺がよくわからないんですけど、その辺を説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"具体的に１年後を目指して有料月極め駐輪場の料金の改定を検討しているとか、行政のほうは、もっといい方法はないかという検討は常にやっております。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"通常の定期利用から見ればかなりの額がその方にかかっていくことになるわけですから、公平性の観点から、よく区が言う公平性とかという。もう一つだけちょっとお聞きしたいんだけれども、タコ公園ですか、公園の整備日程みたいなものをちょっと最後に教えていただけますか。","respondent":"松代管理工事課長","answer":"当面、今お話ししました駐輪場等を先にやりまして、その後公園整備ということで話を聞いてあります。平成２１年度になれば、今のところ、おおむね平成２１年度中にそのような話が来るというふうにこちらでは受けとめているところです。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"聞きたい部分については、今大体話は伺いましたけれども、バイクについての考え方というのはどうされるんでしょうか。そこのところは全く考えていませんということでいいのかどうか、駐輪条例というか、そこらあたりのお考えをちょっとお聞かせいただきたい。","respondent":"諸石交通安全担当課長","answer":"バイクの放置対策という観点で駐輪場の整備を進めているところでございまして、５０ccにしろ、自転車よりも行動範囲がかなり広くなります。とめるスペースを、駐輪場を整備していく中でも少し考え方を異にしているのかなというふうに考えているところです。","id":"exchange-008"},{"speaker":"三上委員","kind":"質問・要望","question":"武蔵小山商店街の脇道のところだって、許可なしに区道上を占有しているバイクが何台もあるではないですか。そうでなければ、そういうふうなことが一緒になっているような条例ならば、そういったところまできちっとやるということが大事ではないか尋ねました。","respondent":"諸石交通安全担当課長","answer":"そうしたものについて、区としてどういうご支援ができるかなというところは当然考えていかなければいけないところだとは思います。今言いましたように個々の自転車、自分のところの敷地内に収容してもらいたいということでお願いしていきたいというふうに考えております。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問","question":"本当に考えるんだったら、３万５,０００円ぐらい出して、車１台とめられる駐車場を確保して自分のバイクを置かざるを得ないじゃないですか。そういったことも含めて、バイクだって放置するわけにいかないじゃないですかということになってくると、そういうふうに思います。","respondent":"岩田まちづくり事業部長","answer":"通勤通学で駅利用者のいわゆる１日の間、８時間以上、長時間とめる方々の対策としてやってきたです。現実にそういう車が結構いて、これからの本当に大切な検討課題だと考えていますので、そこら辺を十分議論してまいりたいと思います。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"京都市もやっぱりそれなりの、どこまで援助ということについては詳しく調べていませんからわかりませんけれども、そういう取り組みもやっていると。これは当然商業の所管課と、商売の流れの中でどうするかということとやっぱり一緒になって話し合って考えていかなければならないところでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"井上委員","kind":"提案","question":"子育て世代にとっては、その辺の基本的な姿勢というのをそろそろ区民ニーズに合ったものにしてほしいな、検討してほしいということ。基本的なところで考えてほしいと強く提案をさせていただいてお聞きするんですけれども、その辺が憶測ではなく、ちょっと確認させてくださいとの意見を述べました。","respondent":"諸石交通安全担当課長","answer":"多いところでいきますと、大井町駅の東口、ここが８６％、最も少ないところは新馬場駅の３１.１％というところもあります。そうしたものをトータルで平均を考えてみますと、やはり６割から７割に減少するということで今までご説明したとおりです。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"外に放置されている現状がないのかどうかということと、使い勝手が悪いというところで３１％で、そういうことはないか尋ねました。","respondent":"諸石交通安全担当課長","answer":"ただ、これは有料化にしたから増えたというふうには考えておりませんし、そういう状況にはなっていないというふうに思っております。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"通勤通学で定期で来ているのかというのは把握される必要があると思うんですけど、方法はどういう方法でもできると思うんですね。まだ８月まで時間があるということで言えば、基礎データを持って研究をする必要があると思うんですけど、そういった考えはいかがか尋ねました。","respondent":"諸石交通安全担当課長、岩田まちづくり事業部長","answer":"これはやることに反対はいたしませんけれども、基本的に先ほど説明したとおりなんですが、有料化はまずすると。ただ、今回は当日利用でやらせていただきたいというふうに考えているところです。これが一番最初の説明ですので、調査すること自体はいいことですからそれは調査をして、今後のいろんな駐輪場計画に生かしていきたいと思います。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうのをかけるとか、その方向でも検討していただきたいというのは、そっちにぜひ力を入れていただきたいというふうに思っています。さっきの当日利用のところは、ぜひ調査をして説得力を持った取り組みとしてしていただきたいというふうに思いますが、最後に一言お願いします。","respondent":"岩田まちづくり事業部長","answer":"今の段階でどうするということのお答えは先ほど申しましたようにできませんが。あるいはバイク置き場をどの駅まで拡大してやっていくのかということは総合的にこれから検討してまいりたい、こういうふう思っております。","id":"exchange-015"},{"speaker":"原委員","kind":"質問・要望","question":"一言要望です。三上委員がおっしゃったようにバイクの件をどうにかもう少し研究をしていただいて、対処していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"それと、やっぱり自転車が実際に生活の中で重要な部分を占める中でどう考えるのかというところの考え方については大きな疑問があります。以上で、この第３２号議案については反対をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"利用料が高くなるわけですから、そこのところをしっかりと調査をした上で判断をしてほしいということと、そこで対応できなかったときにどのように対策をとっていくかということについての検討を必ずするということをもって賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"第３３号議案、品川区地球環境基金条例","agenda":"第３３号議案、品川区地球環境基金条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"１０億円ぐらいで、今回１０億円積み増しすることで、全体で年間２,４００万円ぐらいですかね。現時点でどういう施策を打っていこうとするのかというところと、垣根の助成だとか、ちょっとその辺も教えていただきたい。","respondent":"藤田道路公園課長","answer":"これから、運用益金がどれぐらいになってくるか、その辺がはっきりした段階での検討になろうかなというふうに思ってあります。環境活動推進会議、それから拠点回収とかエコボックスの回収、それらの費用の一部に充当してきたものです。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"約９億幾ら積み増しをするわけですね。どういうことのためにこの基金を使おうという前提があって、どうして先にこの１０億円が積み増しをされて、そこを教えていただけますか。","respondent":"藤田道路公園課長","answer":"すみません、ちょっと説明不足でございました。例えば水とみどりの分野で言うと、そういった面の中でも活用できるような果実運用の基金という形にしていきたいというふうに考えてあります。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"なぜこういうふうに、どういうふうに使うか逆にわからなくなってきてしまっている基金の名称だと思うんですけど、その辺の検討の過程を教えていただきたい。","respondent":"藤田道路公園課長","answer":"今回、次代につなぐ環境都市という一つの大きな都市像に向けて、組織改正をして都市環境事業部という形で力を合わせてやっていこう。それから環境の話、リサイクルの話と、区民の皆様にお知らせをしていくということで一つにまとめていこうというふうにしたものです。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"結局、果実運用型なので一般財源に普通に入って、その中の財源を一般財源とともに振り分けるということになって運用の仕方というのが見えにくい。そういう意味で、もっと見える形にこれをつくっていこうという何か工夫とかはあるんか尋ねました。","respondent":"藤田道路公園課長","answer":"それからみどりを増やしていけるのかと、そういうような検討の材料としての実態調査、それから行動計画をつくっていきます。それからどうすればわかりやすいのかとか、その辺りについても十分に検討しながら今後の検討の課題としていきたいというふうに考えております。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"これがここにあるからいいじゃないですかということで、第５条の(3)で「区長が必要と認める事業」に対しては使っていいよということがあるんですが、何かに使ったケースというのはあるんか尋ねました。","respondent":"藤田道路公園課長","answer":"これと別にして何か基金というお話ですけれども、その中ですみ分けが可能な基金であれば、その検討の余地というのはあるのかなというふうに思います。それはまだまだこれからいろんな社会情勢も含めていろいろ検討はしていきたいというふうに思います。","id":"exchange-023"},{"speaker":"三上委員","kind":"意見","question":"いわゆる清掃事業の流れの中にあるリサイクルというような状況があって、果たしてこういうようなことでいいのかなという思いも実は私もありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問・要望","question":"この基金がどういうふうに使われていくのかというのがどこかでわかるような、そういったものになっていただきたいなというふうに思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"事業者と交渉して、そうした皆さんについても、ここに位置づけをするんだということになるんでしょうか。そこをお聞かせ願えますか。","respondent":"吉川住環境整備担当課長","answer":"区としても、都心共同住宅供給事業実施の際の再開発準備組合ができたときには、今後もそのように指導していきます。したがいまして、入居できることになりますが、そのあたりは基本的には地権者が補償していくというのが前提であるというところは変わりありません。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"今課長が言われた部分についての、そういう方たちは当然事業者が面倒見るんですよというところをどういうふうに位置づけるのか。要するに条例上、事業者が責任を持つんですよというのをどういうふうに条例上位置づけるのかというのが出てくると思うんですけれども、どうか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"地権者と借家人の関係で言いますと、条例以前に借地借家法の規定がありまして、それはきちんと話し合いをして補償していくようにということが法律で位置づけられているところですので、条例の中でそのようにうたう予定はございません。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、密集事業でも同じことなんではないかなと思うんですよね。それはそれぞれの権利者のところでの考え方もあるんでしょうけれども、その辺での違いはどこにあるんか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"本当に一人二人、そういったもともと借家人がいるところとそうでないところもありますし、それは個々具体的な事情に応じて区としては指導しています。","id":"exchange-028"},{"speaker":"三上委員","kind":"質問","question":"この条例についてはソレイユ戸越を指していると、こういうことでいいんでしょうかね。いわゆる事業によってはソレイユ戸越を利用するということができるという、そういうふうに変えるということで、そういう理解でいいか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"若干制度としての説明が不足していたようですのでちょっと補足しますと、仮入居者、一定の範囲で仮入居ができるという規定を設けています。そうした中で、今回の改正は本来の入居資格者として位置づけられると、こういう改正であるです。","id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"常に満室だったというときというのは、どれぐらいの割合であるんですか。入居の条件としては何年とかという決まりがあるのか、ちょっともう少し説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"利用実態ですけども、全部で１０部屋あるんですが、おおむね５部屋から６部屋ぐらいの入居者の推移です。多いときで７世帯という状況です。","id":"exchange-030"},{"speaker":"三上委員","kind":"質問","question":"１０室ある中で、ずっと５世帯ないし６世帯が大体入っているとなると、空き室率というのはちょっと高いかなと。ちょっとどうなのかなというのはずっと思ってきたわけですけども、かなり上がりそうだと見込んではいるんでしょうか、どうなんか尋ねました。","respondent":"吉川住環境整備担当課長","answer":"空き室率が、やや高いという認識は私どもも持っておりまして、今回範囲が広がったことで、入居者が拡大することは我々としても期待しています。品川区のホームページで仮入居者については継続的に募集を常時行っているところです。","id":"exchange-031"},{"speaker":"三上委員","kind":"質問・要望","question":"５カ月ぐらい、本当に半年ぐらい何とか貸してもらえないだろうかという要望も私は何人かから声をかけられたことが実はあるわけですよね。ですから、自分の自宅に転居できるんだというのがわかる範囲であれば、そういうような条件を考えて入居を認めてもいいんじゃないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"民間の建築確認申請機関から来たものについての手数料が載せられていますけれども、さっき課長が言われた、その中身はきちんとしたものなのかどうか。チェック方法を教えていただきたい。","respondent":"片田建築課長","answer":"将来の家族の変更とか家族形態のライフスタイルに合わせた変更ができるような構造になっているかどうかとか、それの配管とか、策定していく予定です。そういうものをきちっと評価を受けていただけるのであれば、手数料もある程度、そのように緩和できるというような考え方です。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"民間のチェックの甘さが指摘をされたわけですから、これだけの手数料として、どういうチェックをするのかという。区で直接やるときのチェックの方法と民間から上がってきたチェックの方法との違いでしょうかね。","respondent":"片田建築課長","answer":"これについては国が指針を決めたとおりの内容になっているかどうか、それは総合的な目で見て、区として最終的には認定評価をするという考え方です。あるいは住戸の面積についても７５m2以上あるとか、そういった基準がありますので、数字的なことで判断するというものです。","id":"exchange-034"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"請願の趣旨としては、本当にごもっともな中身だなというふうに私は思います。今回の再開発が進むと７００戸ぐらいの住宅ができるということで、当該地域での状況というのはどうなっているのか、お聞かせ願いますとの意見を述べました。","respondent":"小林保育課長、冨岡高齢福祉課長、青木都市開発課長","answer":"なお、これにつきましては、現在区として待機児等の需要に対応すべく既存保育園・幼稚園を確保して対応しておりますけれども。都市開発課と協力いたしまし… 現在７カ所ございまして、それから八潮南地区に建設する予定ですが、確かにご指摘のように大崎第一地区には特養施設がございません。… まず最初にご説明したとおり、保育サービス機能は支援していきたいということで自ら事業表明しておりますので、指導しています。","id":"exchange-035"},{"speaker":"菊地委員","kind":"質問・要望","question":"認証がいいかどうかは全然別問題として、子どもたちの施設をこの地域に整備していく必要性はあるんだということですよね。行政としてこういう要望があった場合、どういう結論を求めるのかというのがあると思うんですけど、その辺の都との関係をちょっと説明を求めました。","respondent":"青木都市開発課長","answer":"それは東京都あるいは再開発準備組合のほうにも伝えてございまして、これに対して対応可能かどうか検討を行っていただいております。東京都の見解といたしましては、東京都は先行まちづくりプロジェクトを進めるに当たって、この都有地を活用していくという方針があるそうです。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問・要望","question":"オフィス棟が１棟と、そこを活用するわけですから、区民の声としてそれを要求するということは十分可能なのではないかなというふうに思います。これから議会でどうするかは決めるわけですけれども、区の立場として考えれば、その辺はぜひ要望したいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"ここについて地域の方の要望とか、ここに３カ所ぐらい先行プロジェクトがあって品川区で計画が進む中で、その辺のところというのはわかりますか尋ねました。","respondent":"青木都市開発課長","answer":"ですので、まず１点目として、この東京都のプレスリリースに対して的確にご自身の考えを示してプロジェクトに参加されたということ。それを十分斟酌して、これまでのところは少なくとも地元の方々のご意向には反映できているものであるという前提で進めてまいったものです。","id":"exchange-038"},{"speaker":"井上委員","kind":"提案","question":"先ほどの都議会に出された趣旨採択された５項目のうちの中に、そういった部類のものは５項目の中に趣旨として入っていたのかどうかということと、保育サービスと高齢者福祉のそういったものがずっと提案されてきたものかどうなのかということはどうか尋ねました。","respondent":"青木都市開発課長","answer":"三つ目として、ＩＴを含めた国際化に対応した情報交流拠点、まちづくりの中心となる行政サービス拠点等の形成を図ること。３番目として、国際化に対応した情報交流拠点、今回の請願のような中身までちょっと斟酌することはできていなかったというのが現実です。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"品川区として行政サービスで在宅介護支援センターもここのところはちょっと間借りをしたような形で小さいのがあるというふうに理解しているんですが、そういう意味で、このエリアの高齢者に向けたサービスをする拠点というのは必要度をどの程度考えていらっしゃるんか尋ねました。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"それをもってここでそういった機能をあえて設置することが望ましいのかという議論については、まだ議論を深めるところが必要かと考えています。再開発において… 子育て支援施設については平成１５年当時から東京都は活字にしておりますけれども、周辺の子育て支援施設、公共あるいは私立も含めてですが。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"そうすると、今部長が言ったとおりこの地域に行政としてどうあるべきかというのが先ほどの国有地も含めて、そのところをちょっとお答えいただきたい。そこは広くとらえていただきたいというふうに思うので、検討の成り行きというのはどういうふうになるのか、そこだけお伺いしたいと思います。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"それをこの再開発プロジェクトで実現できるとしたらどういった方策で何なのか、それについては引き続き検討してまいりたいし、地元の方々のご意見もちょうだいしたいということを再三繰り返し申し上げているところです。 これをきちっとした上で、この当再開発に対する指導方法は自ずから決まってまいりますので、引き続きこれは３部のほうで協議を続けさせていただきたいと思うんです。","id":"exchange-041"},{"speaker":"三上委員","kind":"質問","question":"それなりに受けとめるということを言っているわけですから、どういう方針を進めていくかということについて、区としたって取り組まざるを得ない。ですから、この請願そのものが、要旨だけが書いてあって、項目そのものが具体的にこれをやってくれという話でないだけに、読み取るのは非常に難しい。","respondent":"青木都市開発課長","answer":"地域の皆様からも、また議会からもちょうだいしているところで、そういった問題点があることは私ども所管をまたいで全員認識しています。５年たっていますから、引き続き各所管と調整を図って検討していきたいと申し上げているところですので、ご斟酌いただければと思います。","id":"exchange-042"},{"speaker":"石田（慎）委員","kind":"提案","question":"多分お答えが同じになってしまうのでお答えをいただかずに要望という形で、内容の中にも書いてありますが、港区には近くに特養ホームがある。じゃあ品川区の、ぜひともそういった観点からも品川区として東京都ならびに準備組合に対してさまざまなご提案をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと質問で部長にできればお願いしたいんですけど、それからさんま祭りなんかは、それこそ世界的なものになってきている。そこをちょっともう一回、部長にご答弁ほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"逆に言えば、区としても非常に検討しやすい請願をいただいたというふうに認識をしております。私どもとしては、商業あるいは事務所機能を含めて、より目黒周辺が今後活性化するような方向性を持って進めてまいりたいと考えています。","id":"exchange-044"},{"speaker":"原委員","kind":"質問・要望","question":"私は紹介者ですので、できることであれば、出していただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"三上委員","kind":"意見","question":"先ほどの部長の答弁にもあるように、もう少し区長部局としてどういう方針を立てていくのかということを聞いた上で結論を出してもいいんじゃないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、もう少し広いエリアでの要望にもつながっているのかなと、地域の方の要望にもつながっているのかなというふうに判断をさせていただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"ちょっと質問なんですが、紹介議員にもなられているので原委員にお伺いしたいんですが、ここですよという思いでしょうか。そのことを、私は地域の方に本当にお聞きしたいなというふうに思っているんですが、この事業の計画のこの地域につくってほしいんだということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"原委員","kind":"質問","question":"皆さんが言っているように、ずっと今までいろいろ品川区の行政のものがなかったという話がずっとここで出ていたじゃないですか。ですから、ここにつくらなくてはいけないのかというご質問なんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"菊地委員","kind":"意見","question":"私も採択をする中身だと思います。先ほど他の委員から出た部分で、この地域の中で少ないという意味の現実を踏まえれば、この声にこたえていくべきものだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"菊地委員","kind":"質問・要望","question":"私がした一般質問は、今回は請願で区民の皆さん自らがこうした住宅建設を進めてほしい、その辺はお間違いのないようにしていただきたい。そういう意味で、もう一度課長にぜひ求めたいのは、請願の内容そのものをどのように感じるのかというのをまずお聞かせを願いたいと思います。","respondent":"齋藤住宅課長","answer":"これが一つの社会政策として大きなテーマであることは十分認識をしております。住宅提供につきましては、さまざまな方策も考えて区としても取り組んでまいりましたが、皆さんとの公平の関係から見ましてもなかなか難しいです。","id":"exchange-051"},{"speaker":"菊地委員","kind":"質問・要望","question":"真に困窮をしている人、一般質問の答弁でもありましたけれども、都営住宅に申し込む資格を持って何度も何度もそういう要望をしているわけですよね。こうした内容の議長会の要望については、これは無謀な要望だという立場なのか、その辺の議長会の要望についての見解もちょっと伺いたいと思います。","respondent":"齋藤住宅課長","answer":"今収入分位で言うと３６％、給与所得で標準世帯で４４７万円、現在ですと５１０万円以下の世帯が申し込めます。これは都営住宅を建設してください、ちょっと把握をしておりませんが、議長会は議長会としてご要望されたものだというふうに理解をしております。","id":"exchange-052"},{"speaker":"菊地委員","kind":"質問・要望","question":"品川区内の都営住宅で見れば、大井林町と伊藤町がなくなったので、都営住宅は今３,８００戸ぐらいですかね。その辺をちょっとお伺いいたします。","respondent":"齋藤住宅課長","answer":"いわゆる社会政策というふうに申し上げましたのは、他の府県と比較して、東京都はとても難しい状況があります。昭和４８年ぐらいになって、そういった東京の人口一極集中に対して、東京都は基本的に頑張ってこられたということだと思います。","id":"exchange-053"},{"speaker":"菊地委員","kind":"質問・要望","question":"今課長が言われた昔の時代に匹敵するほど大変な状況下にあるわけですから、公営住宅の増設というのは推し進めるべき中身だと思うんですね。先日の一般質問の続きのようになってしまいますけれども、区の言うストック３万戸、私は示すべきだと思うんですね。","respondent":"岩田まちづくり事業部長","answer":"２３区の中でも品川は中以上のストックを保有している、現在は新規の区営住宅を建設するという段階ではない、こういう考えです。今、高齢者の方が多少体が悪くなっても安心してお住まいいただけるような住宅対策はとれないかどうか、これを今重点的に検討しているです。","id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"区営住宅のほうは、わずかに１１戸ですから、本当に年間を通してみればわずかな方しか入居できない状況にあるわけですから。公営住宅法ではきちんと国と地方公共団体は住宅政策をしていくべきだという位置づけをしているわけですから、広域的も何も、どうでしょう。","respondent":"岩田まちづくり事業部長","answer":"先ほど私が言いましたのは、都と２３区は県と市との関係とは大きく異なるところがあります。４区と少し離れた市町村のほうで、こういう実態の中で低所得者の方の住宅というのはどうあるべきかというのが先ほど私どもで申し上げたものです。","id":"exchange-055"},{"speaker":"菊地委員","kind":"質問・要望","question":"今度林町の跡地につくるいわゆる高齢者住宅の家賃そのものが高いわけですから、その入る方たちもそのままストレートに負担されるわけですけれども。今の流れの中で実際に解決していけるのかどうかというところをもう少し明確にしていただきたいのと、最後にその辺をお聞かせ願えればと思います。","respondent":"岩田まちづくり事業部長","answer":"ですから、それだけの分の世帯数の果たして公営住宅をつくることが現実的に可能かといえば、これは極めて難しい。土地は高いですけれども、何とか手当するように努力はしているということは、一方でご理解をお願いしたいと思います。","id":"exchange-056"},{"speaker":"井上委員","kind":"意見","question":"その９番目というのはどういうのが何で９番目なのかというのがわからないんですが、２３区で何番目なんだという計算をしているのか、その辺をちょっと整理させてもらいたいんですとの意見を述べました。","respondent":"齋藤住宅課長","answer":"区営住宅を持たない区が２区ほどありますけども、そういうことです。それはちょっとうちのほうでも統計がとれないので、把握をしておりません。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問・要望","question":"戸数で９番目というのは、人口で考えると全然比較にならないと思うんですけれども、もうちょっと人口に合わせて順番が変わってくると思うんですね。そこが２３区で何番目かということをちゃんと正確に教えていただきたいということと、その辺は整理ができないか尋ねました。","respondent":"齋藤住宅課長","answer":"したがって、収入がどの分位にいるから、その方が区営住宅に申し込めるかというのは、また一つの審査がありますので、その統計把握が難しいです。収入だけではないんです。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問・要望","question":"だから、区はこういうふうな数をもってやっているのでというようなことがこういう審査においては議論のしようがあるのかなというふうに思うんですね。そこを、現状を教えていただきたいということなんです。","respondent":"齋藤住宅課長","answer":"さらに切り開くという手法もありましたが、２２万m2の品川区で空き地というものはなかなか難しゅうあります。２５％以下の方に必ずしも各々の地方公共団体が住宅を提供するんだと、なかなか委員のご質問に対して正確にお答えするデータは持っていないです。","id":"exchange-059"},{"speaker":"井上委員","kind":"意見","question":"２５％のこのぐらいの人がいます、その２５％の人に住宅を限りなく提供すべきでしょうと言っているわけではないんですね。そこは多分理解していただけるかなと思うんですとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"ただ１００倍とか、先ほどのご回答の中で、そういうことではございません。私どもは施策を展開していかなければいけないという、一方、そういう姿勢であるということをご理解をお願いしたいと思います。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうことで、そこは理解ほしいと求めましたので、わかる範囲で後ほど確認をするということでお願いをしたいと思います。そこをどうするのかというのが今こういう経済状況も踏まえて要望されているというところで、そうじゃない、今のところどうなっているんか尋ねました。","respondent":"齋藤住宅課長","answer":"住情報センターというものを考えておりますが、こういった方、オーナーを探しています。区のほうで、何とか質を伴った形でもって住宅要確保援護者の方のために住宅を提供したいと、こういう仕組みをつくりたいということで考えているです。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"建物を建てるんではない、そういうところの考え方というのは、これからは必要になってくるんじゃないかと思うんですけどどうか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"いろんな情報も提供できるような、いわゆる民の力をかりながら、そういう総合的な器ができないだろうかということを今これは行政内部で検討している。近々新年度になれば、どういうものにしていくかということは議会にもお示しできるようになろうかと思います。","id":"exchange-062"},{"speaker":"菊地委員","kind":"質問・要望","question":"採択すべき中身だというふうに思います。きちんと都に対して新規建設を行うよう求めていくべきですし、私は区営住宅の建設、これを積極的に進めていくことが必要だというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、要望になります。ご説明、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"菊地委員","kind":"質問","question":"確かに今説明があったように変えるべきところは障害者の方の視線に立って変えていきますよということですので、陳情された方は。その辺の表示というのも必要なのかなというような気がするんですけれども、そこだけお願いします。","respondent":"諸石交通安全担当課長","answer":"今ご説明したとおり、あそこの表示、案内、看板も含めて改善をしていきます。その中に看板の下のほうに「品川区」という表記を入れたいというふうに考えております。","id":"exchange-065"},{"speaker":"三上委員","kind":"確認","question":"左右の安全確認をした上で出ていくということが大前提のことですから、こういうふうに、ちょっと聞いていて思ったわけです。ですから、ご本人とやりとりしていただくことも大事だと思いますし、早急に改善できることはやっていく必要があるだろう、こう思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"三上委員","kind":"質問・要望","question":"ご本人に話を、あえて採択という話にしていいのかどうかということも微妙だし、そういう取扱いでもいいのかなというふうに思います。皆さんの意見でお決めいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"菊地委員","kind":"質問・要望","question":"今度駐車場を３月で契約を打ち切ると、そのことの報告を、できれば明日にでもいただきたいなというお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3936#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":75518,"voices":245}}]);
